global.RoomPosition = class RoomPosition {
    constructor(x, y, roomName) { this.x = x; this.y = y; this.roomName = roomName; }
};
RoomPosition.prototype.isEqualTo = function (x, y) {
    const pos = x && x.pos ? x.pos : x;
    if (pos && pos.roomName && pos.roomName !== this.roomName) return false;
    return this.x === (pos && pos.x != null ? pos.x : x) && this.y === (pos && pos.y != null ? pos.y : y);
};
RoomPosition.prototype.isNearTo = function (target) {
    const pos = target && target.pos ? target.pos : target;
    if (pos && pos.roomName && pos.roomName !== this.roomName) return false;
    return Math.max(Math.abs(this.x - pos.x), Math.abs(this.y - pos.y)) <= 1;
};
RoomPosition.prototype.inRangeTo = function (target, range) {
    const pos = target && target.pos ? target.pos : target;
    return Math.max(Math.abs(this.x - pos.x), Math.abs(this.y - pos.y)) <= range;
};
RoomPosition.prototype.findClosestByPath = function (kind, opts) {
    const room = Game && Game.rooms && Game.rooms[this.roomName];
    if (Array.isArray(kind)) {
        const list = opts && opts.filter ? kind.filter(opts.filter) : kind;
        let best = null;
        let bestDistance = Infinity;
        for (const object of list) {
            const pos = object && object.pos ? object.pos : object;
            if (!pos) continue;
            const distance = Math.max(Math.abs(pos.x - this.x), Math.abs(pos.y - this.y));
            if (distance < bestDistance) { best = object; bestDistance = distance; }
        }
        return best;
    }
    const list = room && typeof room.find === 'function' ? room.find(kind, opts) : [];
    return list[0] || null;
};
RoomPosition.prototype.findClosestByRange = RoomPosition.prototype.findClosestByPath;
RoomPosition.prototype.findInRange = function (kind, range, opts) {
    const room = Game && Game.rooms && Game.rooms[this.roomName];
    return room && typeof room.find === 'function' ? room.find(kind, opts) : [];
};
RoomPosition.prototype.lookFor = function (kind) {
    const room = Game && Game.rooms && Game.rooms[this.roomName];
    return room && typeof room.lookForAt === 'function' ? room.lookForAt(kind, this.x, this.y) : [];
};

