class CostMatrix {
    constructor() {
        this._data = new Uint8Array(50 * 50);
    }

    set(x, y, cost) {
        this._data[y * 50 + x] = cost;
    }

    get(x, y) {
        return this._data[y * 50 + x];
    }

    clone() {
        return CostMatrix.deserialize(this.serialize());
    }

    serialize() {
        return Array.from(this._data);
    }

    static deserialize(data) {
        const matrix = new CostMatrix();
        matrix._data.set(data);
        return matrix;
    }
}

global.OBSTACLE_OBJECT_TYPES = ['spawn','extension','constructedWall','link','storage','tower','observer','powerSpawn','extractor','lab','terminal','nuker','factory'];

global.PathFinder = {
    CostMatrix,
    search(from, target) {
        if (Array.isArray(target)) target = target.filter(goal => goal && goal.pos).sort((a, b) =>
            Math.max(Math.abs(from.x - a.pos.x), Math.abs(from.y - a.pos.y)) -
            Math.max(Math.abs(from.x - b.pos.x), Math.abs(from.y - b.pos.y)))[0];
        if (!target) return { path: [], incomplete: true };
        const path = [];
        let x = from.x, y = from.y;
        const tx = target.pos.x, ty = target.pos.y;
        let guard = 100;
        while ((x !== tx || y !== ty) && guard-- > 0) {
            if (x < tx) x++; else if (x > tx) x--;
            if (y < ty) y++; else if (y > ty) y--;
            path.push(new RoomPosition(x, y, from.roomName));
        }
        return { path, incomplete: false };
    },
};

