const NEUTRAL_TYPES = new Set([C.STRUCTURE_CONTAINER, C.STRUCTURE_ROAD, C.STRUCTURE_WALL]);
function makeRoom(name, opts = {}) {
    const structures = opts.structures || [];
    const sites = [];
    const room = {
        name,
        controller: {
            my: opts.my !== false,
            level: opts.rcl || 1,
            id: opts.controllerId || ('ctrl_' + name),
            progress: opts.progress || 0,
            progressTotal: opts.progressTotal || 200,
            ticksToDowngrade: opts.ticksToDowngrade || 20000,
            pos: new RoomPosition(opts.ctrl ? opts.ctrl.x : 25, opts.ctrl ? opts.ctrl.y : 40, name),
            owner: opts.owner ? { username: opts.owner } : null,
            reservation: opts.reservation ? { username: opts.reservation.username, ticksToEnd: opts.reservation.ticksToEnd } : null,
        },
        energyAvailable: opts.energy != null ? opts.energy : 300,
        energyCapacityAvailable: opts.cap || 300,
        storage: null,
        terminal: null,
        _hostiles: opts.hostiles || [],
        _drops: opts.drops || [],
        _tombs: opts.tombs || [],
        _ruins: opts.ruins || [],
        getTerrain() { return { get: (x, y) => grid[y][x] }; },
        lookForAt(kind, x, y) {
            if (kind === C.LOOK_STRUCTURES) return structures.filter((s) => s.pos.x === x && s.pos.y === y);
            if (kind === C.LOOK_CREEPS) return Object.values(world.creeps || {}).filter((c) => c && c.pos && c.pos.roomName === name && c.pos.x === x && c.pos.y === y);
            return sites.filter((s) => s.pos.x === x && s.pos.y === y);
        },
        find(kind, o) {
            let list = [];
            if (kind === C.FIND_SOURCES) list = room._sources || [];
            else if (kind === C.FIND_MINERALS) list = room._mineral ? [room._mineral] : [];
            else if (kind === C.FIND_STRUCTURES) list = structures;
            else if (kind === C.FIND_MY_STRUCTURES) list = structures.filter((s) => s.my !== false && !NEUTRAL_TYPES.has(s.structureType));
            else if (kind === C.FIND_MY_SPAWNS) list = structures.filter((s) => s.structureType === C.STRUCTURE_SPAWN);
            else if (kind === C.FIND_MY_CONSTRUCTION_SITES || kind === C.FIND_CONSTRUCTION_SITES) list = sites;
            else if (kind === C.FIND_HOSTILE_CREEPS) list = room._hostiles || [];
            else if (kind === C.FIND_MY_CREEPS) list = Object.values(world.creeps).filter((c) => c.room === room);
            else if (kind === C.FIND_DROPPED_RESOURCES) list = room._drops || [];
            else if (kind === C.FIND_TOMBSTONES) list = room._tombs || [];
            else if (kind === C.FIND_RUINS) list = room._ruins || [];
            if (o && o.filter) list = list.filter(o.filter);
            return list;
        },
        createConstructionSite(x, y, type) {
            if (grid[y][x] === 1) return C.ERR_INVALID_TARGET;
            const canCoexist = (a, b) => a !== b && (a === C.STRUCTURE_RAMPART || b === C.STRUCTURE_RAMPART ||
                (a === C.STRUCTURE_ROAD && b === C.STRUCTURE_CONTAINER) || (a === C.STRUCTURE_CONTAINER && b === C.STRUCTURE_ROAD));
            const conflict = structures.some((s) => s.pos.x === x && s.pos.y === y && !canCoexist(s.structureType, type));
            if (conflict || sites.some((s) => s.pos.x === x && s.pos.y === y)) return C.ERR_INVALID_TARGET;
            const site = { id: 'site_' + world.nextId++, my: true, pos: new RoomPosition(x, y, name), structureType: type, progress: 0, progressTotal: 1000 };
            site.remove = () => {
                const idx = sites.indexOf(site);
                if (idx >= 0) sites.splice(idx, 1);
                delete world.constructionSites[site.id];
                return C.OK;
            };
            sites.push(site);
            world.constructionSites[site.id] = site;
            return C.OK;
        },
        createFlag(pos, flagName) {
            const position = pos && pos.pos ? pos.pos : pos;
            const nameToUse = flagName || ('flag_' + world.nextId++);
            const flag = {
                name: nameToUse,
                pos: new RoomPosition(position.x, position.y, position.roomName || name),
                remove() { delete world.flags[nameToUse]; },
            };
            world.flags[nameToUse] = flag;
            return nameToUse;
        },
    };
    world.exits[name] = opts.exits || world.exits[name] || { '1': 'W33S6', '3': 'W34S7', '5': 'W33S8', '7': 'W32S7' };
    world.rooms[name] = room;
    room._structs = structures;
    room._sites = sites;
    return room;
}

function mkStore(energy, cap, extra = {}) {
    const st = {
        [C.RESOURCE_ENERGY]: energy,
        getUsedCapacity: (t) => {
            if (t == null) return Object.keys(st).reduce((sum, key) => typeof st[key] === 'number' ? sum + st[key] : sum, 0);
            return st[t] || 0;
        },
        getFreeCapacity: () => cap - st.getUsedCapacity(),
        getCapacity: () => cap,
    };
    Object.assign(st, extra);
    return st;
}

function costOf(body) {
    return body.reduce((a, p) => a + ({ work: 100, carry: 50, move: 50, claim: 600, attack: 80, ranged_attack: 150, heal: 250 }[p] || 0), 0);
}

function makeStructure(room, type, x, y, opts = {}) {
    const structure = {
        id: opts.id || (type + '_' + world.nextId++),
        room,
        my: opts.my !== false,
        structureType: type,
        pos: new RoomPosition(x, y, room.name),
        hits: opts.hits == null ? 1000 : opts.hits,
        hitsMax: opts.hitsMax == null ? 1000 : opts.hitsMax,
        cooldown: opts.cooldown || 0,
        store: opts.store || null,
        actions: [],
    };
    if (type === C.STRUCTURE_STORAGE || type === C.STRUCTURE_TERMINAL || type === C.STRUCTURE_CONTAINER ||
        type === C.STRUCTURE_LINK || type === C.STRUCTURE_LAB || type === C.STRUCTURE_POWER_SPAWN ||
        type === C.STRUCTURE_NUKER || type === C.STRUCTURE_FACTORY || type === C.STRUCTURE_EXTENSION ||
        type === C.STRUCTURE_SPAWN) {
        structure.store = structure.store || mkStore(opts.energy || 0, opts.capacity || 2000, opts.extraStore || {});
    }
    if (type === C.STRUCTURE_LINK) {
        structure.transferEnergy = (target, amount) => {
            structure.actions.push({ action: 'transferEnergy', target: target && target.id, amount });
            if (!target || !target.store) return C.ERR_INVALID_TARGET;
            const send = Math.min(amount == null ? structure.store[C.RESOURCE_ENERGY] : amount, structure.store[C.RESOURCE_ENERGY] || 0);
            structure.store[C.RESOURCE_ENERGY] -= send;
            target.store[C.RESOURCE_ENERGY] = (target.store[C.RESOURCE_ENERGY] || 0) + send;
            return C.OK;
        };
    }
    if (type === C.STRUCTURE_OBSERVER) {
        structure.observeRoom = (roomName) => (structure.actions.push({ action: 'observeRoom', roomName }), C.OK);
    }
    if (type === C.STRUCTURE_LAB) {
        structure.runReaction = (labA, labB) => (structure.actions.push({ action: 'runReaction', a: labA && labA.id, b: labB && labB.id }), C.OK);
    }
    if (type === C.STRUCTURE_FACTORY) {
        structure.produce = (resource) => (structure.actions.push({ action: 'produce', resource }), C.OK);
    }
    if (type === C.STRUCTURE_POWER_SPAWN) {
        structure.processPower = () => (structure.actions.push({ action: 'processPower' }), C.OK);
    }
    structure.destroy = () => {
        structure.actions.push('destroy');
        const idx = room._structs.indexOf(structure);
        if (idx >= 0) room._structs.splice(idx, 1);
        delete world.byId[structure.id];
        return C.OK;
    };
    room._structs.push(structure);
    world.byId[structure.id] = structure;
    if (type === C.STRUCTURE_STORAGE) room.storage = structure;
    if (type === C.STRUCTURE_TERMINAL) room.terminal = structure;
    return structure;
}

function makeSpawn(room, x, y) {
    const s = makeStructure(room, C.STRUCTURE_SPAWN, x, y, { capacity: 300, energy: 300 });
    s.spawning = false;
    s.recycleCreep = function (target) {
        if (!target || !target.pos || target.pos.roomName !== room.name || target.my === false) return C.ERR_INVALID_TARGET;
        if (Math.max(Math.abs(target.pos.x - s.pos.x), Math.abs(target.pos.y - s.pos.y)) > 1) return C.ERR_NOT_IN_RANGE;
        s.actions.push({ action: 'recycleCreep', target: target.name });
        if (target.actions) target.actions.push('recycled');
        return C.OK;
    };
    s.spawnCreep = function (body, name, o) {
        if (body.length > 50) return C.ERR_INVALID_ARGS;
        if (world.creeps[name]) return C.ERR_NAME_EXISTS;
        if (name.length > 100) return C.ERR_INVALID_ARGS;
        const cost = costOf(body);
        if (cost > room.energyAvailable) return C.ERR_NOT_ENOUGH_ENERGY;
        const creep = makeCreep(room, name, body, o.memory);
        world.creeps[name] = creep;
        room.energyAvailable = Math.max(0, room.energyAvailable - cost);
        if (global.Memory && Memory.creeps) Memory.creeps[name] = o.memory;
        return C.OK;
    };
    return s;
}

function makeSource(room, x, y, id) {
    const s = { id: id || ('src_' + world.nextId++), room, pos: new RoomPosition(x, y, room.name), energy: 3000, energyCapacity: 3000 };
    world.byId[s.id] = s;
    return s;
}

function makeDropped(room, x, y, amount, resourceType = C.RESOURCE_ENERGY) {
    const drop = { id: 'drop_' + world.nextId++, pos: new RoomPosition(x, y, room.name), amount, resourceType, room };
    room._drops.push(drop);
    world.byId[drop.id] = drop;
    return drop;
}

function makeTombstone(room, x, y, energy, extra = {}) {
    const total = energy + Object.keys(extra).reduce((sum, key) => sum + extra[key], 0);
    const tomb = { id: 'tomb_' + world.nextId++, pos: new RoomPosition(x, y, room.name), room, store: mkStore(energy, total, extra) };
    room._tombs.push(tomb);
    world.byId[tomb.id] = tomb;
    return tomb;
}

function makeRuin(room, x, y, energy, extra = {}) {
    const total = energy + Object.keys(extra).reduce((sum, key) => sum + extra[key], 0);
    const ruin = { id: 'ruin_' + world.nextId++, pos: new RoomPosition(x, y, room.name), room, store: mkStore(energy, total, extra) };
    room._ruins.push(ruin);
    world.byId[ruin.id] = ruin;
    return ruin;
}

function makeHostile(room, x, y, body, opts = {}) {
    const hostile = {
        id: opts.id || ('hostile_' + world.nextId++),
        room,
        pos: new RoomPosition(x, y, room.name),
        body: (body || []).map((p) => ({ type: p, hits: 100 })),
        owner: { username: opts.owner || 'enemy' },
        hits: opts.hits == null ? (body || []).length * 100 : opts.hits,
        hitsMax: opts.hits == null ? (body || []).length * 100 : opts.hits,
        getActiveBodyparts(type) {
            return this.body.filter((part) => part.type === type && part.hits !== 0).length;
        },
    };
    room._hostiles.push(hostile);
    world.byId[hostile.id] = hostile;
    return hostile;
}

function workParts(body) { return utils.bodyPartCount(body, 'work'); }

function makeCreep(room, name, body, memory, opts = {}) {
    const cap = body.filter((p) => p === 'carry').length * 50;
    const creep = new Creep();
    creep.name = name;
    creep.room = room;
    creep.memory = memory || {};
    creep.body = body.map((p) => ({ type: p }));
    creep.pos = new RoomPosition(25, 25, room.name);
    creep.spawning = false;
    creep.fatigue = 0;
    creep.ticksToLive = opts.ticksToLive == null ? 1500 : opts.ticksToLive;
    creep.store = {
        [C.RESOURCE_ENERGY]: 0,
        getUsedCapacity: (t) => (t == null
            ? Object.keys(creep.store).reduce((sum, key) => (typeof creep.store[key] === 'number' ? sum + creep.store[key] : sum), 0)
            : (creep.store[t] || 0)),
        getFreeCapacity: () => cap - creep.store.getUsedCapacity(),
        getCapacity: () => cap,
    };
    creep.hits = 100;
    creep.hitsMax = 100;
    creep.actions = [];
    creep.moveCalls = [];
    creep.harvest = (target) => (creep.actions.push('harvest'), target && target.energy != null && (target.energy = Math.max(0, target.energy - 2 * creep.getActiveBodyparts(C.WORK))), creep.store[C.RESOURCE_ENERGY] = Math.min(cap, creep.store[C.RESOURCE_ENERGY] + 2 * Math.max(1, creep.getActiveBodyparts(C.WORK))), C.OK);
    creep.transfer = (target, resourceType, amount) => {
        creep.actions.push('transfer');
        const key = resourceType || C.RESOURCE_ENERGY;
        const have = creep.store[key] || 0;
        const store = target && target.store;
        if (!store) return C.ERR_INVALID_TARGET;
        if (!have) return C.ERR_NOT_ENOUGH_RESOURCES;
        const free = typeof store.getFreeCapacity === 'function' ? Number(store.getFreeCapacity(key)) : Infinity;
        if (!(free > 0)) return C.ERR_FULL;
        const send = amount == null ? Math.min(have, free) : amount;
        if (have < send) return C.ERR_NOT_ENOUGH_RESOURCES;
        if (send > free) return C.ERR_FULL;
        store[key] = (store[key] || 0) + send;
        creep.store[key] = have - send;
        return C.OK;
    };
    creep.withdraw = (target, resourceType, amount) => {
        creep.actions.push('withdraw');
        const key = resourceType || C.RESOURCE_ENERGY;
        const have = (target && target.store && target.store[key]) || 0;
        const empty = creep.store.getFreeCapacity();
        if (empty <= 0) return C.ERR_FULL;
        const want = amount == null ? Math.min(empty, have) : amount;
        if (want > empty) return C.ERR_FULL;
        if (!want || have < want) return C.ERR_NOT_ENOUGH_RESOURCES;
        target.store[key] = have - want;
        creep.store[key] = (creep.store[key] || 0) + want;
        return C.OK;
    };
    creep.build = (target) => (creep.actions.push('build'), target && target.progress != null && (target.progress += Math.min(5, creep.store[C.RESOURCE_ENERGY] || 0)), creep.store[C.RESOURCE_ENERGY] = Math.max(0, (creep.store[C.RESOURCE_ENERGY] || 0) - 5), C.OK);
    creep.repair = (target) => (creep.actions.push('repair'), target && target.hits != null && (target.hits = Math.min(target.hitsMax || target.hits, target.hits + 100)), creep.store[C.RESOURCE_ENERGY] = Math.max(0, (creep.store[C.RESOURCE_ENERGY] || 0) - 1), C.OK);
    creep.upgradeController = (target) => (creep.actions.push('upgradeController'), target && target.progress != null && (target.progress += Math.max(1, creep.getActiveBodyparts(C.WORK))), creep.store[C.RESOURCE_ENERGY] = Math.max(0, (creep.store[C.RESOURCE_ENERGY] || 0) - Math.max(1, creep.getActiveBodyparts(C.WORK))), C.OK);
    creep.reserveController = () => (creep.actions.push('reserveController'), C.OK);
    creep.claimController = (target) => (creep.actions.push('claimController'), target && (target.my = true, target.level = Math.max(1, target.level || 0)), C.OK);
    creep.signController = () => (creep.actions.push('signController'), C.OK);
    creep.suicide = () => (creep.actions.push('suicide'), C.OK);
    creep.attack = (target) => (creep.actions.push('attack'), Math.max(Math.abs(creep.pos.x - target.pos.x), Math.abs(creep.pos.y - target.pos.y)) <= 1 ? C.OK : C.ERR_NOT_IN_RANGE);
    creep.rangedAttack = (target) => (creep.actions.push('rangedAttack'), Math.max(Math.abs(creep.pos.x - target.pos.x), Math.abs(creep.pos.y - target.pos.y)) <= 3 ? C.OK : C.ERR_NOT_IN_RANGE);
    creep.rangedMassAttack = () => (creep.actions.push('rangedMassAttack'), C.OK);
    creep.heal = (target) => (creep.actions.push('heal'), C.OK);
    creep.rangedHeal = (target) => (creep.actions.push('rangedHeal'), C.OK);
    creep.pickup = (target) => {
        creep.actions.push('pickup');
        if (!target) return C.OK;
        const key = target.resourceType || C.RESOURCE_ENERGY;
        const take = Math.min(Number(target.amount) || 0, creep.store.getFreeCapacity());
        creep.store[key] = (creep.store[key] || 0) + take;
        target.amount = Math.max(0, (Number(target.amount) || 0) - take);
        return C.OK;
    };
    creep.drop = (resourceType) => (creep.actions.push('drop'), creep.store[resourceType || C.RESOURCE_ENERGY] = 0, C.OK);
    creep.posIsEqualTo = null;
    creep.pos.isEqualTo = (x, y) => {
        const pos = x && x.pos ? x.pos : x;
        if (pos && pos.roomName && pos.roomName !== creep.pos.roomName) return false;
        return creep.pos.x === (pos && pos.x != null ? pos.x : x) && creep.pos.y === (pos && pos.y != null ? pos.y : y);
    };
    creep.pos.isNearTo = (t) => {
        const pos = t && t.pos ? t.pos : t;
        if (pos && pos.roomName && pos.roomName !== creep.pos.roomName) return false;
        return Math.max(Math.abs(creep.pos.x - pos.x), Math.abs(creep.pos.y - pos.y)) <= 1;
    };
    creep.pos.inRangeTo = (t, n) => Math.max(Math.abs(creep.pos.x - (t.pos ? t.pos.x : t.x)), Math.abs(creep.pos.y - (t.pos ? t.pos.y : t.y))) <= n;
    creep.pos.findClosestByPath = (kind, o) => {
        const l = Array.isArray(kind) ? (o && o.filter ? kind.filter(o.filter) : kind) : room.find(kind, o);
        return l[0] || null;
    };
    creep.pos.findClosestByRange = creep.pos.findClosestByPath;
    creep.pos.findInRange = (kind, n, o) => room.find(kind, o);
    return creep;
}

function headingTo(creep, target) {
    const pos = target && target.pos ? target.pos : target;
    return !!pos && (creep.moveCalls || []).some((m) => m.target && m.target.x === pos.x && m.target.y === pos.y);
}

function retiring(creep) {
    return creep.actions.includes('suicide') || creep.actions.includes('recycled') ||
        (creep.memory.retireSpawn != null && creep.moveCalls.length > 0);
}

function resetWorld(time) {
    world.time = time;
    world.creeps = {};
    world.rooms = {};
    world.byId = {};
    world.nextId = 1;
    world.exits = {};
    world.constructionSites = {};
    world.flags = {};
    global.Game.creeps = world.creeps;
    global.Game.rooms = world.rooms;
    global.Game.constructionSites = world.constructionSites;
    global.Game.flags = world.flags;
    global.Game.getObjectById = (id) => world.byId[id] || null;
    global.Game.resources = {};
    global.Memory = { creeps: {}, rooms: {}, map: {}, roomPlanner: {}, errors: [], stats: [], brainRetiredAlert: { at: 0 } };
    global.roomPlanCache = {};
    plannerState.cache = {};
    plannerState.calls = [];
    wheelMovementState.intents = [];
    wheelMovementState.resolved = [];
    wheelMovementState.deletedRooms = [];
    wheelMovementState.apiCalls = [];
    wheelMovementState.lastResolver = null;
    wheelMovementState.begin = 0;
    wheelMovementState.end = 0;
}

