console.log('== Memory 探针残渣回收：内容不再变化的下划线键按 TTL 删掉 ==');
{
    const ttl = require('../src/config').memoryProbeTtl;
    const savedTime = world.time;
    world.time = 20000;
    Memory._mon = JSON.stringify({ t: 1, big: 'x'.repeat(100) });
    Memory._dbg2 = 'stale';
    Memory._visuals = { t: 1, until: 999999 };
    Memory.rooms = Memory.rooms || {};
    main.gcProbeKeys();
    assert(Memory._mon && Memory._dbg2, '第一次只登记，不删');
    assert(Memory._gcSeen && Memory._gcSeen._mon && Memory._gcSeen._dbg2, '登记表记下了两个探针键');
    assert(!Memory._gcSeen._visuals && !Memory._gcSeen._gcSeen, '游戏内自己用的下划线键不进登记表');
    world.time += ttl + 1;
    Memory._mon = JSON.stringify({ t: 2, big: 'y'.repeat(200) });
    main.gcProbeKeys();
    assert(Memory._mon, '内容变过的探针键重新计时，不删');
    assert(!Memory._dbg2, '内容一直没变、超过 TTL 的探针键被删');
    assert(Memory._visuals, '游戏内自己用的 _visuals 不受影响');
    world.time += ttl + 1;
    main.gcProbeKeys();
    assert(!Memory._mon, '再过一个 TTL 没有新内容，_mon 也被删');
    assert(!Memory._gcSeen._mon && !Memory._gcSeen._dbg2, '登记表跟着清干净，自己不会长大');
    delete Memory._visuals;
    delete Memory._gcSeen;
    world.time = savedTime;
}

console.log('== 周期性工作的房名相位：真的错开，不是全账号同 tick ==');
{
    const liveRooms = ['W33S7', 'W34S7', 'W35S7', 'W33S8', 'W31S8', 'W31S6', 'W31S5', 'W33S3', 'W32S4', 'W31S4'];
    for (const interval of [5, 11, 20]) {
        const phases = new Set(liveRooms.map((n) => utils.roomPhase(n, interval)));
        const oldPhases = new Set(liveRooms.map((n) => n.charCodeAt(3) % interval));
        assert(oldPhases.size === 1, `旧写法在 interval=${interval} 下确实只有一个相位（回归的前提）`);
        assert(phases.size >= Math.min(4, interval), `interval=${interval} 至少散成 ${Math.min(4, interval)} 个相位（得 ${phases.size}）`);
        for (const n of liveRooms) {
            const p = utils.roomPhase(n, interval);
            assert(p >= 0 && p < interval, `${n} 相位落在 [0,${interval})`);
        }
    }
    assert(utils.roomPhase('W33S7', 11) === utils.roomPhase('W33S7', 11), 'roomPhase 稳定');
    assert(utils.roomPhase('W1S1', 1) === 0 && utils.roomPhase('W1S1', 0) === 0, 'interval ≤ 1 时相位恒为 0');
    const savedTime = world.time;
    world.time = 110 + utils.roomPhase('W33S7', 11);
    assert(utils.isRoomPhaseTick('W33S7', 11), '轮到 W33S7 的那一 tick isRoomPhaseTick 为真');
    world.time += 1;
    assert(!utils.isRoomPhaseTick('W33S7', 11), '下一 tick 就不再轮到它');
    world.time = savedTime;
}

