assert(!siteTypes[C.STRUCTURE_ROAD], 'RCL1 不放道路工地（低于 roadsMinRcl）（得 ' + siteTypes[C.STRUCTURE_ROAD] + '）');
{
    const rtPlanned = plan.roads.all.split(';').map((s) => s.split('.'));
    let rtSeeded = 0;
    for (const p of rtPlanned) {
        if (rtSeeded >= 3) break;
        if (room.createConstructionSite(+p[0], +p[1], C.STRUCTURE_ROAD) === C.OK) rtSeeded++;
    }
    assert(rtSeeded === 3, '预置 3 条规划内的路工地（模拟改动前放下的存量）');
    const rtWithProgress = room.find(C.FIND_MY_CONSTRUCTION_SITES).filter((s) => s.structureType === C.STRUCTURE_ROAD)[0];
    rtWithProgress.progress = 120;
    world.time += 11;
    layout.run(room);
    const rtLeft = room.find(C.FIND_MY_CONSTRUCTION_SITES).filter((s) => s.structureType === C.STRUCTURE_ROAD);
    assert(rtLeft.length === 1 && rtLeft[0] === rtWithProgress,
        'RCL1：零进度的存量路工地清掉、有进度的保留（得 ' + rtLeft.length + ' 条，含有进度的 ' + rtLeft.includes(rtWithProgress) + '）');
    assert(Memory.rooms.W33S7.roadsTrimmed === 2, '遥测：roadsTrimmed 累计清掉的条数（得 ' + Memory.rooms.W33S7.roadsTrimmed + '）');
    rtWithProgress.remove();
}
room.controller.level = require('../src/config').roadsMinRcl;
layout.run(room);
assert(room.find(C.FIND_MY_CONSTRUCTION_SITES).some((s) => s.structureType === C.STRUCTURE_ROAD),
    'RCL 到 roadsMinRcl 后道路工地照放');
room.controller.level = 1;

console.log('== RCL2 回归：道路占满名额时 extension 工地仍能放下 ==');
room.controller.level = Math.max(2, require('../src/config').roadsMinRcl);
let extraRoads = room.find(C.FIND_MY_CONSTRUCTION_SITES).filter((s) => s.structureType === C.STRUCTURE_ROAD).length;
for (const p of plan.roads.all.split(';').map((s) => s.split('.'))) {
    if (extraRoads > require('../src/config').sitePace.roads) break;
    if (room.createConstructionSite(+p[0], +p[1], C.STRUCTURE_ROAD) === C.OK) extraRoads++;
}
assert(extraRoads > require('../src/config').sitePace.roads, '预置道路工地超过 sitePace.roads（得 ' + extraRoads + '）');
const roadsBefore = room.find(C.FIND_MY_CONSTRUCTION_SITES).filter((s) => s.structureType === C.STRUCTURE_ROAD).length;
assert(roadsBefore > require('../src/config').sitePace.roads, '前提：道路在建已超过 sitePace.roads（得 ' + roadsBefore + '）');
layout.run(room);
const st2 = room.find(C.FIND_MY_CONSTRUCTION_SITES).reduce((a, s) => (a[s.structureType] = (a[s.structureType] || 0) + 1, a), {});
console.log('  rcl2 sites:', JSON.stringify(st2));
assert((st2[C.STRUCTURE_ROAD] || 0) === roadsBefore, '道路在建 ≥ sitePace.roads 时不再新放道路，也不删规划内的道路工地（得 ' + st2[C.STRUCTURE_ROAD] + '）');
assert((st2[C.STRUCTURE_EXTENSION] || 0) >= 1, 'extension 工地已放置');
assert(room.find(C.FIND_MY_CONSTRUCTION_SITES).length <= require('../src/config').maxSites, '工地总数 ≤ maxSites');

