console.log('== 角色 run() 冒烟 ==');
const h = makeCreep(room, 'h.test', ['work', 'carry', 'move'], { home: 'W33S7', role: 'harvester', sourceIdx: 0 });
world.creeps.h = h;
for (const [rn, mod] of Object.entries(ROLES)) {
    const body = ROLE_SMOKE_BODIES[rn] || ['work', 'carry', 'move'];
    const c = makeCreep(room, 'c_' + rn, body, { home: 'W33S7', role: rn, remoteRoom: 'W33S6', srcIdx: 0, target: 'W33S6' });
    world.creeps['c_' + rn] = c;
    let ok = true;
    try {
        mod.run(c);
        c.store[C.RESOURCE_ENERGY] = 50;
        mod.run(c);
        c.store[C.RESOURCE_ENERGY] = 100;
        if (c.store.getFreeCapacity() === 0) mod.run(c);
    } catch (e) { ok = false; console.log('  ✗ ' + rn + ' throw: ' + e.stack.split('\n').slice(0, 3).join(' | ')); fails++; }
    if (ok) console.log('  ✓ role ' + rn);
}

console.log('== hybrid task broker：按 backlog/距离/收益/TTL/CPU 选择安全 fallback ==');
resetWorld(3170);
const brokerRoom = makeRoom('W33S7', { rcl: 2, energy: 0, cap: 550, ctrl: { x: 22, y: 31 } });
const brokerSource = makeSource(brokerRoom, 14, 6, 'tb0');
brokerRoom._sources = [brokerSource, makeSource(brokerRoom, 31, 12, 'tb1')];
const brokerSpawn = makeSpawn(brokerRoom, 23, 21);
brokerSpawn.store[RESOURCE_ENERGY] = 0;
const brokerExtension = makeStructure(brokerRoom, C.STRUCTURE_EXTENSION, 24, 21, { energy: 0, capacity: 50 });
const brokerContainer = makeStructure(brokerRoom, C.STRUCTURE_CONTAINER, 15, 6,
    { my: false, energy: 250, capacity: 2000 });
Memory.rooms.W33S7 = { sources: ['tb0', 'tb1'], state: { at: Game.time, recovering: false, emergencyHarvest: false } };
const brokerBuilder = makeCreep(brokerRoom, 'broker.builder', ['work', 'carry', 'move'], { home: 'W33S7', role: 'builder' });
world.creeps[brokerBuilder.name] = brokerBuilder;
taskBroker.beginTick();
const brokerTasks = taskBroker.roomTasks(brokerRoom);
const harvestTask = brokerTasks.find((task) => task.kind === 'harvest' && task.id === 'tb0');
assert(harvestTask && Number.isFinite(taskBroker.scoreTask(brokerBuilder, harvestTask)), '竞价分数包含可用 harvest 任务');
assert(brokerTasks.some((task) => task.kind === 'collect' && task.target === brokerContainer),
    '竞价任务池包含中立 source container');
brokerContainer.store[C.RESOURCE_ENERGY] = 0;
const brokerHaulerA = makeCreep(brokerRoom, 'broker.hauler.a', ['carry', 'carry', 'move'],
    { home: 'W33S7', role: 'hauler' });
const brokerHaulerB = makeCreep(brokerRoom, 'broker.hauler.b', ['carry', 'carry', 'move'],
    { home: 'W33S7', role: 'hauler' });
const brokerDeliverA = taskBroker.pickTask(brokerHaulerA, brokerRoom, (task) => task.kind === 'deliver', true);
const brokerDeliverB = taskBroker.pickTask(brokerHaulerB, brokerRoom, (task) => task.kind === 'deliver', true);
assert(brokerDeliverA && brokerDeliverB,
    '同 tick 的 hauler 竞价会为大 backlog 分配多个投递租约');
assert(taskBroker.taskSlots(brokerDeliverA) >= 2,
    '大 backlog 投递任务会按容量开放并发 slot');
const smallDeliver = brokerTasks.find((task) => task.kind === 'deliver' && task.target === brokerExtension);
assert(smallDeliver && taskBroker.taskSlots(smallDeliver) === 1,
    '小容量投递任务仍限制为单个并发 slot');
ROLES.builder.run(brokerBuilder);
assert(brokerBuilder.moveCalls.length > 0 && brokerBuilder.moveCalls[0].target &&
    brokerTasks.some((task) => task.kind === 'harvest' && task.target.pos.x === brokerBuilder.moveCalls[0].target.x &&
        task.target.pos.y === brokerBuilder.moveCalls[0].target.y),
    '无工地时 builder 按竞价前往高收益 source，不在基地空闲');
const brokerTarget = brokerTasks.find((task) => task.kind === 'harvest' && task.id === brokerBuilder.memory.brokerTask.id).target;
brokerBuilder.pos = new RoomPosition(brokerTarget.pos.x, brokerTarget.pos.y, 'W33S7');
brokerBuilder.moveCalls.length = 0;
ROLES.builder.run(brokerBuilder);
