console.log('== 主循环 3 tick 冒烟（RCL1→2 演进）==');
for (let i = 0; i < 3; i++) {
    world.time++;
    try { main.loop(); } catch (e) { fails++; console.log('  ✗ loop throw: ' + e.stack.split('\n').slice(0, 4).join(' | ')); break; }
}
assert((Memory.errors || []).length === 0, '无运行时错误: ' + JSON.stringify(Memory.errors || []));

{
    Memory.stats = [];
    const statsSavedTime = world.time;
    while (world.time % 30 !== 0) world.time++;
    try { main.sampleStats(); } catch (e) { fails++; console.log('  ✗ sampleStats throw: ' + e.message); }
    const stat = (Memory.stats || [])[Memory.stats.length - 1];
    assert(stat && stat.rooms && stat.rooms[room.name] && stat.rooms[room.name].length === 3,
        '每个己方房都记 [rcl, progress, storage]（得 ' + JSON.stringify(stat && stat.rooms) + '）');
    assert(stat && stat.rcl === undefined && stat.prog === undefined, '不再有 rooms[0] 那份顶层单房字段');
    assert(stat && stat.cpuBy && typeof stat.cpuBy === 'object' && stat.cpuRooms && typeof stat.cpuRooms === 'object' &&
        stat.cpuRoles && typeof stat.cpuRoles === 'object',
        'stats 带 cpuBy / cpuRooms / cpuRoles 三张 CPU 表');
    assert(stat && stat.cpuSpawn && typeof stat.cpuSpawn === 'object' && stat.cpuDispatch && typeof stat.cpuDispatch === 'object',
        'stats 另带 cpuSpawn / cpuDispatch 两张阶段表（cpuBy 里最大的两块要能拆开看）');
    assert(Memory.cpuLedger && Memory.cpuLedger.ticks > 0 && Memory.cpuLedger.room && Memory.cpuLedger.home && Memory.cpuLedger.remote,
        '10-18：按房/按外矿的 CPU 累计账 Memory.cpuLedger（room=房间调度，home=母房 creep，remote=外矿 creep）');
    const srcOrder = stat && stat.cache && stat.cache.srcOrder;
    assert(Array.isArray(srcOrder) && srcOrder.length === 2 && srcOrder[0] >= srcOrder[1] && srcOrder[1] >= 0,
        'stats.cache.srcOrder 记下窗口内源顺序缓存的 [调用, 命中]（得 ' + JSON.stringify(srcOrder) + '）');
    assert(!/cpuLap\(cpuProf\.room/.test(require('fs').readFileSync(require('path').join(__dirname, '..', 'src', 'main.js'), 'utf8')),
        '房级 CPU 不再用 cpuLap（那会被模块级打点吃掉，线上第一版 cpuRooms 全空）');
    assert(stat && typeof stat.cpu === 'number', 'cpu 字段是数字（整 tick 收尾时会被回填成含 flush/endTick 的值）');
    world.time = statsSavedTime;
}

