console.log('== harvester 不成对孵化：孵化中的替补也算在源上（2 spawn、RCL7、源 link + 容器）==');
function pairRoomSetup(time) {
    resetWorld(time);
    const room = makeRoom('W33S7', { rcl: 7, energy: 5600, cap: 5600, ctrl: { x: 22, y: 31 } });
    room._sources = [makeSource(room, 14, 6, 'pr0'), makeSource(room, 31, 12, 'pr1')];
    const spawns = [makeSpawn(room, 23, 21), makeSpawn(room, 24, 21)];
    makeStructure(room, C.STRUCTURE_CONTAINER, 15, 7, { capacity: 2000, energy: 0 });
    makeStructure(room, C.STRUCTURE_CONTAINER, 30, 13, { capacity: 2000, energy: 0 });
    makeStructure(room, C.STRUCTURE_LINK, 16, 7, { capacity: 800, energy: 0 });
    makeStructure(room, C.STRUCTURE_LINK, 30, 11, { capacity: 800, energy: 0 });
    Memory.rooms.W33S7 = { sources: ['pr0', 'pr1'] };
    const miner = ['work', 'work', 'work', 'work', 'work', 'carry', 'move', 'move', 'move'];
    world.creeps.prA = makeCreep(room, 'prA', miner, { home: 'W33S7', role: 'harvester', sourceId: 'pr0', sourceIdx: 0 }, { ticksToLive: 45 });
    world.creeps.prB = makeCreep(room, 'prB', miner, { home: 'W33S7', role: 'harvester', sourceId: 'pr1', sourceIdx: 1 });
    for (const name of ['prh0', 'prh1', 'prh2']) {
        world.creeps[name] = makeCreep(room, name, ['carry', 'carry', 'move'], { home: 'W33S7', role: 'hauler' });
    }
    return { room, spawns };
}
const pairHarvesters = () => Object.values(world.creeps).filter((c) => c.memory.role === 'harvester' && !['prA', 'prB'].includes(c.name));
let pair = pairRoomSetup(3710);
spawnMgr.run(pair.room);
const pairFirst = pairHarvesters();
assert(pairFirst.length === 1 && pairFirst[0].memory.sourceIdx === 0, '将死的源 0 矿工只预补一只（同 tick 两个空闲 spawn 也不成对）');
if (pairFirst[0]) {
    pairFirst[0].spawning = true;
    pair.spawns[0].spawning = { name: pairFirst[0].name, remainingTime: 20, needTime: 27 };
}
world.time++;
pair.room.energyAvailable = 5600;
spawnMgr.run(pair.room);
const pairSecond = pairHarvesters();
assert(pairSecond.length === 1, '孵化中的替补算在源 0 上：另一只空闲 spawn 不再孵第二只同源矿工');
const pairCover = Memory.rooms.W33S7.harvesterSpawnCover;
assert(pairCover && pairCover.src === 0 && pairCover.idle === 1 && pairCover.at === Game.time,
    '遥测 harvesterSpawnCover 记下"源只靠孵化中的矿工覆盖、另有空闲 spawn"（得 ' + JSON.stringify(pairCover) + '）');
const pairStats = Memory.rooms.W33S7.demand && Memory.rooms.W33S7.demand.targets;
assert(!pairStats || Number(pairStats.harvester) <= 2, '2 源各 1 只 5W 足额：矿工目标不超过源数（实际 ' + (pairStats && pairStats.harvester) + '）');
pair = pairRoomSetup(3720);
world.creeps.prA.ticksToLive = 1500;
world.creeps.prA2 = makeCreep(pair.room, 'prA2', ['work', 'work', 'work', 'work', 'work', 'carry', 'move', 'move', 'move'],
    { home: 'W33S7', role: 'harvester', sourceId: 'pr0', sourceIdx: 0 }, { ticksToLive: 45 });
spawnMgr.run(pair.room);
assert(!Object.values(world.creeps).some((c) => c.memory.role === 'harvester' && !['prA', 'prA2', 'prB'].includes(c.name)),
    '同源已有足额 5W 矿工：多余那只将死时不换代');

function chebyshev(a, b) {
    return Math.max(Math.abs(a.x - b.x), Math.abs(a.y - b.y));
}

