    [STRUCTURE_SPAWN]: [{ x: 25, y: 25 }, { x: 27, y: 25 }, { x: 28, y: 25 }],
    [STRUCTURE_EXTENSION]: [{ x: 26, y: 24 }],
    [STRUCTURE_CONTAINER]: [{ x: 16, y: 25 }, { x: 17, y: 16 }, { x: 22, y: 30 }],
    [STRUCTURE_LINK]: [{ x: 25, y: 24 }, { x: 16, y: 24 }, { x: 17, y: 15 }, { x: 23, y: 30 }, { x: 29, y: 25 }],
    [STRUCTURE_STORAGE]: [{ x: 25, y: 24 }],
