    [STRUCTURE_ROAD]: [{ x: 24, y: 25 }, { x: 24, y: 25 }, { x: 24, y: 24 }],
    [STRUCTURE_RAMPART]: [{ x: 25, y: 25 }, { x: 24, y: 25 }],
    [STRUCTURE_FACTORY]: [{ x: 27, y: 24 }],
