adoptRoom._sources = [adoptSourceB, adoptSourceA];
const adoptSpawn = makeSpawn(adoptRoom, 25, 25);
Memory.rooms.W33S7 = { sources: ['adoptA', 'adoptB'], plan: { anchor: { x: 25, y: 25 }, sourceIds: ['adoptA', 'adoptB'] } };
world.creeps.adoptLive = makeCreep(adoptRoom, 'adoptLive', ['work', 'carry', 'move'], { home: 'W33S7', role: 'harvester', sourceIdx: 0 });
Memory.creeps.adoptPending = { home: 'W33S7', role: 'harvester', sourceIdx: 1 };
adoptSpawn.spawning = { name: 'adoptPending' };
const wheelRaw = {
    [STRUCTURE_SPAWN]: [{ x: 25, y: 25 }],
    [STRUCTURE_STORAGE]: [{ x: 26, y: 25 }],
    [STRUCTURE_TERMINAL]: [{ x: 27, y: 25 }],
    [STRUCTURE_CONTAINER]: [{ x: 16, y: 25 }, { x: 17, y: 16 }, { x: 22, y: 30 }],
    [STRUCTURE_ROAD]: [{ x: 24, y: 25 }, { x: 24, y: 24 }],
    [STRUCTURE_RAMPART]: [{ x: 26, y: 25 }],
    work_pos: [{ x: 16, y: 25 }, { x: 17, y: 16 }, { x: 22, y: 30 }],
};
plannerState.cache.W33S7 = { layout: clone(wheelRaw) };
const conflict = makeStructure(adoptRoom, C.STRUCTURE_EXTENSION, 26, 25, { id: 'conflictExt', capacity: 50 });
const rejected = wheelLayout.validateExisting(adoptRoom, wheelLayout.normalize(adoptRoom, wheelRaw));
assert(rejected.ok === false && rejected.errors.some((item) => item.includes('conflicts with planned')), '冲突建筑会拒绝采用 wheel plan');
adoptRoom._structs.splice(adoptRoom._structs.indexOf(conflict), 1);
delete world.byId[conflict.id];
const outsideSpawn = makeStructure(adoptRoom, C.STRUCTURE_SPAWN, 24, 24, { id: 'outsideSpawn', capacity: 300, energy: 300 });
const outsideContainer = makeStructure(adoptRoom, C.STRUCTURE_CONTAINER, 24, 26, { id: 'outsideContainer', capacity: 2000, energy: 0 });
const rejectedOutside = wheelLayout.validateExisting(adoptRoom, wheelLayout.normalize(adoptRoom, wheelRaw));
assert(rejectedOutside.ok === false && rejectedOutside.errors.some((item) => item.includes('existing structure_spawn is outside wheel plan')) &&
    rejectedOutside.errors.some((item) => item.includes('existing structure_container is outside wheel plan')), 'wheel plan 外的既有 spawn/container 会被拒绝');
adoptRoom._structs.splice(adoptRoom._structs.indexOf(outsideSpawn), 1);
adoptRoom._structs.splice(adoptRoom._structs.indexOf(outsideContainer), 1);
delete world.byId[outsideSpawn.id];
delete world.byId[outsideContainer.id];
Game.flags.RP = { name: 'RP', pos: new RoomPosition(25, 25, 'W33S7'), remove() { delete Game.flags.RP; } };
Game.flags.SP = { name: 'SP', pos: new RoomPosition(25, 25, 'W33S7'), remove() { delete Game.flags.SP; } };
wheelLayout.autoPlannerByFlag();
assert(!Game.flags.RP && !Game.flags.SP, 'RP/SP flag 成功消费');
assert(plannerState.calls.some((call) => call.fn === 'runPlan' && call.roomName === 'W33S7'), 'RP 会触发 runPlan');
assert(plannerState.calls.some((call) => call.fn === 'visualizePlan' && call.roomName === 'W33S7'), 'RP 创建的 VP 会触发 visualize');
assert(plannerState.calls.some((call) => call.fn === 'savePlanToMemory' && call.roomName === 'W33S7'), 'SP 会先保存 planner cache');
assert(Memory.rooms.W33S7.wheelLayout && Memory.rooms.W33S7.plan.version === wheelLayout.VERSION, 'SP adopt 会写入标准化 wheel plan');
assert(!(Memory.rooms.W33S7.plan.rawLayout && Memory.rooms.W33S7.plan.rawLayout[STRUCTURE_ROAD]) ||
    Memory.rooms.W33S7.plan.rawLayout[STRUCTURE_ROAD].length === 2, 'adopted plan 不保留重复 rawLayout');
assert(world.creeps.adoptLive.memory.sourceId === 'adoptA' && world.creeps.adoptLive.memory.sourceIdx === 1, 'adopt 会 remap 活体 harvester 的 source 身份');
assert(Memory.creeps.adoptPending.sourceId === 'adoptB' && Memory.creeps.adoptPending.sourceIdx === 0, 'adopt 会 remap 孵化中 harvester 的 source 身份');
makeStructure(adoptRoom, C.STRUCTURE_TOWER, 28, 28, { store: mkStore(1000, 1000) });
layout.run(adoptRoom);
const adoptedSites = adoptRoom.find(C.FIND_MY_CONSTRUCTION_SITES).reduce((acc, site) => (acc[site.structureType] = (acc[site.structureType] || 0) + 1, acc), {});
assert(!(adoptedSites[C.STRUCTURE_ROAD] || 0), 'adopt 后 RCL2 不放道路工地（低于 roadsMinRcl）（得 ' + adoptedSites[C.STRUCTURE_ROAD] + '）');
assert(!(adoptedSites[C.STRUCTURE_RAMPART] || 0), 'adopt 后 RCL2 不放 rampart 工地：外环等 rampartRingMinRcl，核心建筑的 rampart RCL3 起');
adoptRoom.controller.level = Math.max(2, require('../src/config').roadsMinRcl);
world.time += 11;
layout.run(adoptRoom);
assert(adoptRoom.find(C.FIND_MY_CONSTRUCTION_SITES).some((site) => site.structureType === C.STRUCTURE_ROAD), 'adopt 的方案在 roadsMinRcl 后照放道路工地');
adoptRoom.controller.level = 2;

