const remoteContainer = makeStructure(remoteRoom, C.STRUCTURE_CONTAINER, 12, 10, { id: 'rcont0', capacity: 2000, energy: 400, hits: 2000, hitsMax: 2500 });
const remoteMiner = makeCreep(remoteRoom, 'rminer0', ['work', 'work', 'carry', 'move', 'move'], { home: 'W33S7', role: 'remoteMiner', remoteRoom: 'W33S6', sourceId: 'rr0', srcIdx: 0 });
