remoteContainer.store[C.RESOURCE_ENERGY] = 400;
remoteMiner.store[C.RESOURCE_ENERGY] = 50;

const remoteHauler = makeCreep(remoteRoom, 'rhaul0', ['work', 'carry', 'carry', 'move', 'move'], { home: 'W33S7', role: 'remoteHauler', remoteRoom: 'W33S6', sourceId: 'rr0', srcIdx: 0, state: 'collect' });
remoteHauler.pos.x = 12; remoteHauler.pos.y = 11;
world.creeps[remoteHauler.name] = remoteHauler;
ROLES.remoteHauler.run(remoteHauler);
assert(remoteHauler.actions.includes('withdraw'), 'remoteHauler collect 会从远矿容器 withdraw');
remoteHauler.room = remoteHome;
remoteHauler.pos = new RoomPosition(23, 21, 'W33S7');
remoteHauler.store[C.RESOURCE_ENERGY] = 100;
remoteHauler.memory.state = 'deliver';
makeStructure(remoteHome, C.STRUCTURE_STORAGE, 24, 21, { id: 'homeStorage', capacity: 1000000, energy: 50000 });
ROLES.remoteHauler.run(remoteHauler);
assert(remoteHauler.actions.includes('transfer'), 'remoteHauler deliver 会回家交能量');
Memory.rooms.W33S7.remotes.W33S6.suspendedUntil = Game.time + 50;
