src0Link6.cooldown = 5;
ctrlLink6.store[C.RESOURCE_ENERGY] = 300;
linksMod.run(rcl6Room);
assert(src1Link6.actions.length === 1 && src1Link6.actions[0].target === 'ctrlL6', 'RCL6 src1 也作为 sender：ctrl link 低于保留线时补能');
src0Link6.cooldown = 0;

console.log('== industry：低储备零消耗，observer 可运行，空 Memory 安全 ==');
resetWorld(4100);
const indRoom = makeRoom('W33S7', { rcl: 6, energy: 1800, cap: 1800, owner: 'me' });
indRoom._sources = [makeSource(indRoom, 14, 6, 'is0'), makeSource(indRoom, 31, 12, 'is1')];
makeSpawn(indRoom, 23, 21);
const indStorage = makeStructure(indRoom, C.STRUCTURE_STORAGE, 24, 21, { id: 'istore', capacity: 1000000, energy: 1000 });
const indTerminal = makeStructure(indRoom, C.STRUCTURE_TERMINAL, 25, 21, { id: 'iterm', capacity: 300000, energy: 1000 });
const observer = makeStructure(indRoom, C.STRUCTURE_OBSERVER, 26, 21, { id: 'iobs' });
const labA = makeStructure(indRoom, C.STRUCTURE_LAB, 27, 21, { id: 'labA', capacity: 3000, energy: 1000 });
const labB = makeStructure(indRoom, C.STRUCTURE_LAB, 28, 21, { id: 'labB', capacity: 3000, energy: 1000 });
const labOut = makeStructure(indRoom, C.STRUCTURE_LAB, 29, 21, { id: 'labOut', capacity: 3000, energy: 1000 });
const factory = makeStructure(indRoom, C.STRUCTURE_FACTORY, 30, 21, { id: 'ifac', capacity: 50000, energy: 1000 });
const powerSpawn = makeStructure(indRoom, C.STRUCTURE_POWER_SPAWN, 31, 21, {
    id: 'ips', capacity: 5000, energy: 500,
    extraStore: { [C.RESOURCE_POWER]: 5 },
});
Memory.rooms = {};
industry.run(indRoom);
assert(Memory.rooms.W33S7 && Memory.rooms.W33S7.industryState, '空 Memory 下 industry 会安全初始化状态');
Memory.rooms.W33S7.industry = {
    observe: ['W33S6'],
    reaction: { inputs: ['labA', 'labB'], outputs: ['labOut'] },
    product: { factoryId: 'ifac', resource: 'utrium_bar' },
};
industry.run(indRoom);
assert(observer.actions.length === 1, '低储备时 observer 仍可 observeRoom');
assert(labOut.actions.length === 0 && factory.actions.length === 0 && powerSpawn.actions.length === 0, '低储备时 lab/factory/powerSpawn 零消耗');
assert(Memory.rooms.W33S7.industryState && Memory.rooms.W33S7.industryState.spendingUnlocked === false, '低储备时 industryState 标记 spendingUnlocked=false');

{
    const ind = require('../src/industry');
    global.REACTIONS = { H: { O: 'OH' }, O: { H: 'OH' } };
    const at = (x, y, id, store) => ({ id, structureType: C.STRUCTURE_LAB, my: true, room: indRoom,
        pos: new RoomPosition(x, y, 'W33S7'), store: Object.assign({ [C.RESOURCE_ENERGY]: 1000 }, store || {}) });
    const inA = at(27, 21, 'dlA', { H: 1000 });
    const inB = at(28, 21, 'dlB', { O: 1000 });
    const outC = at(29, 21, 'dlC');
    const far = at(40, 40, 'dlFar', { H: 500 });
    assert(ind.deriveReaction([inA, inB, outC]).outputs[0] === 'dlC', '三连里挑出能收货的输出 lab');
    assert(ind.deriveReaction([inA, inB, outC]).product === 'OH', '产物按 REACTIONS 推导');
    assert(ind.deriveReaction([inA, far, outC]) === null, '输入距离超过 2 格 ⇒ 推不出（引擎会直接拒绝 runReaction）');
    assert(ind.deriveReaction([inA, inB, at(29, 21, 'dlBusy', { Z: 100 })]) === null, '输出 lab 里装着别的矿物 ⇒ 不能收');
    assert(ind.deriveReaction([inA, at(28, 21, 'dlSame', { H: 500 }), outC]) === null, '两个输入是同一种矿物 ⇒ 没有反应');
    assert(ind.deriveReaction([inA, outC]) === null, '不足三个 lab ⇒ 推不出');
    delete global.REACTIONS;
}

console.log('== 矿物链（2026-10-13，移植 overmind-absorb 7f4ab27 / 2d97ab4）：labTech 装货、反应链选下一步、lab 分工跨 tick 稳定 ==');
{
    const ind = require('../src/industry');
    const spawnLab = require('../src/spawn');
    const FULL_REACTIONS = {
        H: { O: 'OH', L: 'LH', K: 'KH', U: 'UH', Z: 'ZH', G: 'GH' },
        O: { H: 'OH', L: 'LO', K: 'KO', U: 'UO', Z: 'ZO', G: 'GO' },
        Z: { H: 'ZH', O: 'ZO', K: 'ZK' }, K: { H: 'KH', O: 'KO', Z: 'ZK' },
        U: { H: 'UH', O: 'UO', L: 'UL' }, L: { H: 'LH', O: 'LO', U: 'UL' },
        G: { H: 'GH', O: 'GO' },
        OH: { ZH: 'ZH2O', ZO: 'ZHO2', LH: 'LH2O', LO: 'LHO2', KH: 'KH2O', KO: 'KHO2', UH: 'UH2O', UO: 'UHO2', GH: 'GH2O', GO: 'GHO2' },
        ZH: { OH: 'ZH2O' }, ZO: { OH: 'ZHO2' }, LH: { OH: 'LH2O' }, LO: { OH: 'LHO2' },
        KH: { OH: 'KH2O' }, KO: { OH: 'KHO2' }, UH: { OH: 'UH2O' }, UO: { OH: 'UHO2' },
        GH: { OH: 'GH2O' }, GO: { OH: 'GHO2' },
        UL: { ZK: 'G' }, ZK: { UL: 'G' },
        X: { ZH2O: 'XZH2O', ZHO2: 'XZHO2', LH2O: 'XLH2O', LHO2: 'XLHO2', KH2O: 'XKH2O', KHO2: 'XKHO2',
            UH2O: 'XUH2O', UHO2: 'XUHO2', GH2O: 'XGH2O', GHO2: 'XGHO2' },
        ZH2O: { X: 'XZH2O' }, ZHO2: { X: 'XZHO2' }, LHO2: { X: 'XLHO2' }, KHO2: { X: 'XKHO2' },
        UH2O: { X: 'XUH2O' }, GH2O: { X: 'XGH2O' },
    };
    global.REACTIONS = FULL_REACTIONS;
    const base = { H: 5000, O: 5000, Z: 5000, K: 5000, U: 5000, L: 5000, X: 5000 };
    const first = ind.nextReactionFor('XZH2O', base, 500, 0);
    assert(first && first.product !== 'XZH2O' && [first.a, first.b].every((t) => base[t]),
        '目标做不了时先做链上更靠下的一步（得 ' + JSON.stringify(first) + '）');
    const walk = (target, stock) => {
        const steps = [];
        const have = Object.assign({}, stock);
        for (let i = 0; i < 10; i++) {
            const step = ind.nextReactionFor(target, have, 500, 0);
            if (!step) break;
            steps.push(step.product);
            have[step.product] = 5000;
            if (step.product === target) break;
        }
        return steps;
    };
    assert(walk('XZH2O', base).join(',') === 'OH,ZH,ZH2O,XZH2O', 'XZH2O 的链：OH → ZH → ZH2O → XZH2O（得 ' + walk('XZH2O', base).join(',') + '）');
    assert(walk('XGH2O', base).slice(-1)[0] === 'XGH2O' && walk('XGH2O', base).indexOf('G') >= 0, 'XGH2O 要先合成 G（得 ' + walk('XGH2O', base).join(',') + '）');
    assert(ind.nextReactionFor('XZH2O', { H: 5000, O: 5000, Z: 5000 }, 500, 0).product === 'OH', '没有 X 时仍然把 OH 这一步做掉（等调剂补 X）');
    assert(ind.nextReactionFor('XZH2O', { X: 5000 }, 500, 0) === null, '基础矿全缺 ⇒ 这一支做不了');
    assert(ind.nextReactionFor('H', base, 500, 0) === null, '基础矿本身没有反应能做出它');
    const tcfg = { boostTargets: ['XZH2O', 'XLHO2'], boostGoal: 3000 };
    assert(ind.wantedTarget({}, tcfg) === 'XZH2O', '目标清单从第一个开始');
    assert(ind.wantedTarget({ XZH2O: 3000 }, tcfg) === 'XLHO2', '攒够 boostGoal 就换下一个');
    assert(ind.wantedTarget({ XZH2O: 3000, XLHO2: 4000 }, tcfg) === null, '全攒够 ⇒ 没有目标（退回机会主义配对）');
    assert(JSON.stringify(ind.pickPair({ H: 600, O: 600, Z: 100 }, 500)) === JSON.stringify({ a: 'H', b: 'O', product: 'OH' }), '机会主义配对：两种各 ≥ minBatch');
    assert(ind.pickPair({ H: 600 }, 500) === null, '只有一种矿物 ⇒ 配不出');

    resetWorld(52000);
    Memory.rooms = {};
    const lr = makeRoom('W33S7', { rcl: 7, energy: 2300, cap: 2300, owner: 'me' });
    lr._sources = [makeSource(lr, 14, 6, 'lr0'), makeSource(lr, 31, 12, 'lr1')];
    makeSpawn(lr, 23, 21);
    const lrStorage = makeStructure(lr, C.STRUCTURE_STORAGE, 24, 22, { id: 'lrStore', capacity: 1000000, energy: 200000 });
    const lrTerminal = makeStructure(lr, C.STRUCTURE_TERMINAL, 25, 22, { id: 'lrTerm', capacity: 300000, energy: 20000, extraStore: { H: 3000, O: 3000 } });
    const mkLab = (x, y, id, store) => makeStructure(lr, C.STRUCTURE_LAB, x, y, { id, capacity: 5000, energy: 0, extraStore: store || {} });
    const la = mkLab(35, 21, 'lab1');
    const lb = mkLab(36, 21, 'lab2');
    const lc = mkLab(37, 21, 'lab3');
    const lfar = mkLab(10, 40, 'lab9');
    const plan0 = ind.labPlan(lr);
    const cheb = (a, b) => Math.max(Math.abs(a.x - b.x), Math.abs(a.y - b.y));
    assert(plan0 && plan0.product === 'OH' && plan0.target === 'XZH2O', '空 lab + terminal 里有 H/O：按目标 XZH2O 的链选出第一步 OH（得 ' + JSON.stringify(plan0 && { p: plan0.product, t: plan0.target }) + '）');
    assert(plan0.inputs.every((id) => cheb(Game.getObjectById(id).pos, Game.getObjectById(plan0.output).pos) <= 2),
        '输出 lab 与两个输入都在 2 格内（否则引擎直接拒绝 runReaction）');
    assert(plan0.inputs.indexOf('lab9') < 0 && plan0.output !== 'lab9' && plan0.boost === 'lab9', '孤立的 lab 不进三连，留作 boost lab');
    assert(plan0.wants.length === 2 && plan0.wants.map((w) => w.mineral).sort().join() === 'H,O' && plan0.wants.every((w) => w.amount === config.industry.labFill),
        '两个输入 lab 各要装 labFill 的 H / O（得 ' + JSON.stringify(plan0.wants) + '）');
    assert(Memory.rooms.W33S7.labRoles && Memory.rooms.W33S7.labRoles.output === undefined && Memory.rooms.W33S7.labRoles.outputs[0] === plan0.output,
        'lab 分工存进 Memory.rooms[房].labRoles');
    assert(ind.labPlan(lr) === plan0, '同一 tick 只算一次（labTech / spawn / industry 共用）');

    const tech = makeCreep(lr, 'lt0', Array(20).fill('carry').concat(Array(10).fill('move')), { home: 'W33S7', role: 'labTech' });
    world.creeps[tech.name] = tech;
    tech.pos = new RoomPosition(25, 23, 'W33S7');
    world.time++;
    ROLES.labTech.run(tech);
    const firstWant = plan0.wants[0];
    assert(tech.actions.includes('withdraw') && tech.store[firstWant.mineral] === config.industry.labFill, 'labTech 从 terminal 取一趟 labFill 的矿（得 ' + JSON.stringify(tech.store) + '）');
    assert(tech.memory.labId === firstWant.labId, '记下这批货要送去的 lab');
    world.time++;
    const midPlan = ind.labPlan(lr);
    assert(midPlan.product === 'OH' && midPlan.output === plan0.output, '搬运中的货也算库存：取完 terminal 里的这一种，计划仍是 OH（得 ' + midPlan.product + '）');
    tech.actions.length = 0;
    tech.pos = new RoomPosition(Game.getObjectById(firstWant.labId).pos.x, 22, 'W33S7');
    ROLES.labTech.run(tech);
    assert(tech.actions.includes('transfer') && Game.getObjectById(firstWant.labId).store[firstWant.mineral] === config.industry.labFill, '送进记下的 lab');
    assert(Memory.rooms.W33S7.labTech && Memory.rooms.W33S7.labTech.loaded === 1 && Memory.rooms.W33S7.labTech.loadedAmount === config.industry.labFill,
        '遥测 labTech.loaded（得 ' + JSON.stringify(Memory.rooms.W33S7.labTech) + '）');
    world.time++;
    const halfPlan = ind.labPlan(lr);
    assert(halfPlan.output === plan0.output && halfPlan.inputs.join() === plan0.inputs.join(), '一个输入有货时 lab 分工不翻（deriveReaction 不会换输出）');
    assert(halfPlan.wants.length === 1 && halfPlan.wants[0].labId !== firstWant.labId, '只剩另一个输入要装');
    tech.actions.length = 0;
    tech.pos = new RoomPosition(25, 23, 'W33S7');
    ROLES.labTech.run(tech);
    world.time++;
    tech.pos = new RoomPosition(Game.getObjectById(halfPlan.wants[0].labId).pos.x, 22, 'W33S7');
    ROLES.labTech.run(tech);
    world.time++;
    lrStorage.store[C.RESOURCE_ENERGY] = 1000;
    ind.run(lr);
    const out = Game.getObjectById(plan0.output);
    assert(out.actions.length === 0 && Memory.rooms.W33S7.industryState.labs.gated === true, '储备闸关着：两个输入都装好了也不发 runReaction（也不算取送计划）');
    assert(spawnLab.labTechTarget(lr, Memory.rooms.W33S7) === 0, '储备闸关着不孵 labTech');
    lrStorage.store[C.RESOURCE_ENERGY] = 200000;
    world.time++;
    ind.run(lr);
    const labsState = Memory.rooms.W33S7.industryState.labs;
    assert(out.actions.some((a) => a.action === 'runReaction') && labsState.active && labsState.target === 'XZH2O' && labsState.product === 'OH',
        '两个输入装好且储备闸开：反应跑起来，state 记下它为哪个目标服务（得 ' + JSON.stringify(labsState) + '）');
    assert(labsState.derived && labsState.derived.product === 'OH', '接着做 lab 里已装好的这一批（derived）');
    assert(ind.labPlan(lr).wants.length === 0 && spawnLab.labTechTarget(lr, Memory.rooms.W33S7) === 0, '都装满了：没有活，不孵 labTech');
    tech.actions.length = 0; tech.moveCalls.length = 0;
    ROLES.labTech.run(tech);
    assert(!tech.memory.retired && tech.memory.labIdleSince === Game.time, '没活先等，不立刻退役');
    world.time += config.industry.labTechIdleTicks;
    ROLES.labTech.run(tech);
    assert(tech.memory.retired === true, '空闲超过 labTechIdleTicks 退役回收');
    delete world.creeps[tech.name];
    world.time++;
    out.store.OH = config.industry.labMinBatch;
    let p = ind.labPlan(lr);
    assert(p.drains.length === 1 && p.drains[0].labId === out.id && p.drains[0].mineral === 'OH', '产物攒够 labMinBatch 收回');
    assert(spawnLab.labTechTarget(lr, Memory.rooms.W33S7) === 1, '有收回的活 ⇒ 孵 1 只 labTech');
    world.time++;
    out.store.OH = 0; out.store.ZK = 20;
    p = ind.labPlan(lr);
    assert(p.drains.some((d) => d.labId === out.id && d.mineral === 'ZK'), '输出 lab 装着别的产物（20 也清）：否则这一批永远开不了工');
    world.time++;
    const reactionsBefore = out.actions.filter((a) => a.action === 'runReaction').length;
    ind.run(lr);
    assert(out.actions.filter((a) => a.action === 'runReaction').length === reactionsBefore, '输出 lab 装着别的产物时不发 runReaction');
    out.store.ZK = 0;
    const tech2 = makeCreep(lr, 'lt1', Array(20).fill('carry').concat(Array(10).fill('move')), { home: 'W33S7', role: 'labTech' });
    world.creeps[tech2.name] = tech2;
    world.time++;
    out.store.OH = 800;
    tech2.pos = new RoomPosition(out.pos.x, 22, 'W33S7');
    ROLES.labTech.run(tech2);
    assert(tech2.store.OH === 800 && !tech2.memory.labId, '先把产物收回（不记 lab 目标）');
    world.time++;
    tech2.pos = new RoomPosition(25, 23, 'W33S7');
    ROLES.labTech.run(tech2);
    assert(lrTerminal.store.OH === 800 && Memory.rooms.W33S7.labTech.drained === 1, '产物送回 terminal（得 ' + lrTerminal.store.OH + '）');
    world.time++;
    for (const id of plan0.inputs) { const lab = Game.getObjectById(id); lab.store.H = 0; lab.store.O = 0; }
    Game.getObjectById(plan0.inputs[0]).store.H = 10;
    delete lrTerminal.store.H; delete lrTerminal.store.O;
    lrTerminal.store.Z = 3000; lrTerminal.store.K = 3000; lrTerminal.store.OH = 0;
    p = ind.labPlan(lr);
    assert(p.product === 'ZK' && p.drains.some((d) => d.labId === plan0.inputs[0] && d.mineral === 'H'),
        '库存换成 Z/K：选 ZK，装着 10 H 的输入先清（得 ' + JSON.stringify({ p: p.product, d: p.drains }) + '）');
    world.time++;
    for (const id of plan0.inputs) { const lab = Game.getObjectById(id); for (const k of Object.keys(lab.store)) if (k !== 'energy') lab.store[k] = 0; }
    Game.getObjectById(plan0.inputs[0]).store.K = 1000;
    Game.getObjectById(plan0.inputs[1]).store.Z = 4;
    delete lrTerminal.store.Z; delete lrTerminal.store.K;
    lrTerminal.store.ZK = 3000; lrTerminal.store.UL = 3000;
    p = ind.labPlan(lr);
    assert(p.product === 'G' && p.drains.some((d) => d.mineral === 'Z') && p.drains.some((d) => d.mineral === 'K'),
        '输入只剩零头：不再接着做 ZK，换成 G 并清掉 K/Z（得 ' + JSON.stringify({ p: p.product, d: p.drains }) + '）');
    world.time++;
    lrTerminal.store.Z = 500;
    p = ind.labPlan(lr);
    assert(p.product === 'ZK', 'terminal 里还有 Z：照旧接着做 ZK（得 ' + p.product + '）');
    delete lrTerminal.store.Z; delete lrTerminal.store.ZK; delete lrTerminal.store.UL;
    world.time++;
    for (const lab of [la, lb, lc, lfar].slice(1)) lr._structs.splice(lr._structs.indexOf(lab), 1);
    assert(ind.labPlan(lr) === null && spawnLab.labTechTarget(lr, Memory.rooms.W33S7) === 0, '不足 3 个 lab ⇒ 没有计划、不孵');
    delete world.creeps[tech2.name];
    const ltBody = spawnLab.labTechBody(2300);
    assert(utils.bodyPartCount(ltBody, 'carry') * 50 === config.industry.labFill && utils.bodyCost(ltBody) <= 2300, 'labTech 身体一趟装 labFill（得 ' + ltBody.length + ' 部件）');
    assert(utils.bodyCost(spawnLab.labTechBody(800)) <= 800 && utils.bodyPartCount(spawnLab.labTechBody(800), 'carry') >= 2, '预算不够就减 CARRY');
    delete global.REACTIONS;
}

console.log('== boost lab（2026-10-13，移植 overmind-absorb 019c5b1）：目标化合物攒够就装进三连之外的 lab，只给它补能量 ==');
{
    const ind = require('../src/industry');
    global.REACTIONS = { H: { O: 'OH' }, O: { H: 'OH' } };
    resetWorld(53000);
    Memory.rooms = {};
    const indCfg = config.industry;
    const br = makeRoom('W33S7', { rcl: 7, energy: 2300, cap: 2300, owner: 'me' });
    br._sources = [makeSource(br, 14, 6, 'br0'), makeSource(br, 31, 12, 'br1')];
    makeSpawn(br, 23, 21);
    const brStorage = makeStructure(br, C.STRUCTURE_STORAGE, 24, 22, { id: 'brStore', capacity: 1000000, energy: 200000 });
    const brTerminal = makeStructure(br, C.STRUCTURE_TERMINAL, 25, 22, { id: 'brTerm', capacity: 300000, energy: 20000,
        extraStore: { H: 3000, O: 3000, XZH2O: indCfg.labBoostStock + 500 } });
    const mk = (x, y, id, store) => makeStructure(br, C.STRUCTURE_LAB, x, y, { id, capacity: 5000, energy: 0, extraStore: store || {} });
    mk(35, 21, 'blab1'); mk(36, 21, 'blab2'); mk(37, 21, 'blab3');
    const boostLab = mk(10, 40, 'blab9');
    let bp = ind.labPlan(br);
    const bw = bp.wants.find((w) => w.boost);
    assert(bp.boost === 'blab9' && bw && bw.labId === 'blab9' && bw.mineral === 'XZH2O' && bw.amount === indCfg.labBoostStock,
        'XZH2O 库存 ≥ labBoostStock ⇒ 往三连之外的 boost lab 装一份（得 ' + JSON.stringify(bp.wants) + '）');
    assert(bp.wants.filter((w) => !w.boost).length === 2, '反应三连的装货需求照常');
    const bt = makeCreep(br, 'blt', Array(20).fill('carry').concat(Array(10).fill('move')), { home: 'W33S7', role: 'labTech' });
    world.creeps.blt = bt;
    for (const id of ['blab2', 'blab3']) { const lab = Game.getObjectById(id); lab.store[bp.need[id]] = indCfg.labFill; }
    brTerminal.store.H -= indCfg.labFill; brTerminal.store.O -= indCfg.labFill;
    world.time++;
    bt.pos = new RoomPosition(25, 23, 'W33S7');
    ROLES.labTech.run(bt);
    assert(bt.store.XZH2O === indCfg.labBoostStock && bt.memory.labId === 'blab9', '三连装满后 labTech 去取 XZH2O 送 boost lab（得 ' + JSON.stringify(bt.store) + '）');
    world.time++;
    bt.pos = new RoomPosition(10, 39, 'W33S7');
    ROLES.labTech.run(bt);
    assert(boostLab.store.XZH2O === indCfg.labBoostStock, 'boost lab 装上了 XZH2O');
    world.time++;
    bp = ind.labPlan(br);
    assert(!bp.wants.some((w) => w.boost), '已经装着、没用掉一半 ⇒ 不再补');
    world.time++;
    boostLab.store.XZH2O = Math.floor(indCfg.labBoostStock / 2) - 1;
    bp = ind.labPlan(br);
    assert(bp.wants.some((w) => w.boost && w.mineral === 'XZH2O' && w.amount === indCfg.labBoostStock - boostLab.store.XZH2O), '用掉一半以上 ⇒ 补回 labBoostStock');
    world.time++;
    boostLab.store.XZH2O = 0; boostLab.store.OH = 40;
    bp = ind.labPlan(br);
    assert(bp.drains.some((d) => d.labId === 'blab9' && d.mineral === 'OH'), 'boost lab 里装着不在 boostTargets 里的东西 ⇒ 先清掉');
    world.time++;
    boostLab.store.OH = 0; brTerminal.store.XZH2O = indCfg.labBoostStock - 1;
    bp = ind.labPlan(br);
    assert(!bp.wants.some((w) => w.boost), '目标化合物不到 labBoostStock ⇒ 先攒，不装');
    delete world.creeps.blt;
    world.time++;
    industry.run(br);
    assert(Memory.rooms.W33S7.industryState.labs.boostLab === 'blab9', 'industryState 记下 boost lab');
    Memory.rooms.W33S7.state = { at: Game.time, recovering: false, emergencyHarvest: false };
    const labTasks = () => {
        world.time++;
        taskBroker.beginTick();
        return taskBroker.roomTasks(br).filter((t) => t.kind === 'deliver' && t.target && t.target.structureType === C.STRUCTURE_LAB);
    };
    const lbConquest = require('../src/conquest');
    const lbCfg = require('../src/config');
    delete Memory.conquest;
    assert(!lbConquest.boostingEnabled(), '前提：默认 config.conquest.boosts 全空 ⇒ 强化关闭');
    delete Memory.rooms.W33S7.labEnergy;
    let lt = labTasks();
    assert(lt.length === 0, '强化关闭：boost lab 不出能量投递任务（得 ' + JSON.stringify(lt.map((t) => [t.id, t.backlog])) + '）');
    assert(!Memory.rooms.W33S7.labEnergy && Memory.rooms.W33S7.labEnergyHeld && Memory.rooms.W33S7.labEnergyHeld.lab === 'blab9' && Memory.rooms.W33S7.labEnergyHeld.want > 0,
        '强化关闭：记 labEnergyHeld、不记 labEnergy（得 ' + JSON.stringify({ held: Memory.rooms.W33S7.labEnergyHeld, energy: Memory.rooms.W33S7.labEnergy }) + '）');
    Memory.conquest = [{ target: 'W1N1', sponsors: ['W33S7'], dismantlers: 0, guards: 0, completed: true, boosts: { dismantler: ['XZH2O'] } },
        { target: 'W1N2', sponsors: ['W33S7'], dismantlers: 0, guards: 0, boosts: { dismantler: [], guard: [] } }];
    assert(!lbConquest.boostingEnabled() && labTasks().length === 0, '已完成 / boosts 全空的指令不打开强化');
    const lbPrevBoosts = lbCfg.conquest.boosts;
    delete Memory.conquest;
    lbCfg.conquest.boosts = { dismantler: ['XZH2O'], guard: [] };
    assert(lbConquest.boostingEnabled() && labTasks().length === 1, 'config.conquest.boosts 写了化合物 ⇒ 强化打开、boost lab 出补能任务');
    lbCfg.conquest.boosts = lbPrevBoosts;
    Memory.conquest = [{ target: 'W1N2', sponsors: ['W33S7'], dismantlers: 0, guards: 0, boosts: { dismantler: ['XZH2O'] } }];
    assert(lbConquest.boostingEnabled(), '指令 boosts 写了化合物 ⇒ 强化打开');
    lt = labTasks();
    assert(lt.length === 1 && lt[0].target === boostLab && lt[0].tier === 4 && lt[0].weight < 0.5 && lt[0].roles.join() === 'hauler' && lt[0].backlog === indCfg.labEnergyTarget,
        'storage 富余：只有 boost lab 有能量投递任务（第 4 层、权重低于 terminal、只给 hauler、补到 labEnergyTarget）（得 ' + JSON.stringify(lt.map((t) => [t.id, t.tier, t.weight, t.backlog])) + '）');
    assert(Memory.rooms.W33S7.labEnergy && Memory.rooms.W33S7.labEnergy.lab === 'blab9', '遥测 Memory.rooms[房].labEnergy');
    brTerminal.store[C.RESOURCE_ENERGY] = indCfg.terminalTarget;
    Memory.rooms.W33S7.sources = ['br0', 'br1'];
    Memory.rooms.W33S7.plan = { anchor: { x: 23, y: 21 }, containers: {}, workPositions: {}, roads: {}, links: {} };
    const bh = makeCreep(br, 'bha', utils.makeBody('hauler', 1800), { home: 'W33S7', role: 'hauler' });
    world.creeps.bha = bh;
    bh.pos = new RoomPosition(24, 23, 'W33S7');
    labTasks();
    ROLES.hauler.run(bh);
    assert(brStorage.store[C.RESOURCE_ENERGY] < 200000 && bh.store[C.RESOURCE_ENERGY] > 0, '空载 hauler 从富余 storage 取货去补 boost lab（手上 ' + bh.store[C.RESOURCE_ENERGY] + '）');
    delete world.creeps.bha;
    brStorage.store[C.RESOURCE_ENERGY] = 200000;
    boostLab.store[C.RESOURCE_ENERGY] = indCfg.labEnergyTarget;
    assert(labTasks().length === 0, '补满就不再补');
    boostLab.store[C.RESOURCE_ENERGY] = 0;
    brStorage.store[C.RESOURCE_ENERGY] = indCfg.terminalFillStorageAbove + 20000;
    world.time++;
    industry.run(br);
    const gatedLabs = Memory.rooms.W33S7.industryState.labs;
    assert(gatedLabs.gated === true && gatedLabs.boostLab === 'blab9',
        '储备闸关着：labs 记 gated，boostLab 照记（得 ' + JSON.stringify(gatedLabs) + '）');
    lt = labTasks();
    assert(lt.length === 1 && lt[0].target === boostLab, '储备闸关着、补能闸开着 ⇒ boost lab 照样有能量投递任务（得 ' + lt.length + '）');
    brStorage.store[C.RESOURCE_ENERGY] = 200000;
    world.time++;
    industry.run(br);
    boostLab.store[C.RESOURCE_ENERGY] = 0;
    brStorage.store[C.RESOURCE_ENERGY] = indCfg.terminalFillStorageAbove + 300;
    lt = labTasks();
    assert(lt.length === 1 && lt[0].backlog === 300, 'storage 只比门槛多 300 ⇒ 最多补 300（得 ' + (lt[0] && lt[0].backlog) + '）');
    if (SF_RICH < indCfg.terminalFillStorageAbove) {
        brStorage.store[C.RESOURCE_ENERGY] = indCfg.terminalFillStorageAbove - 1;
        assert(labTasks().length === 0, 'storage 富余但低于 terminalFillStorageAbove ⇒ 不补');
    }
    brStorage.store[C.RESOURCE_ENERGY] = 0;
    assert(labTasks().length === 0, 'storage 0 ⇒ 不补');
    delete Memory.conquest;
    delete global.REACTIONS;
}

console.log('== boost（2026-10-13，移植 overmind-absorb 79a5ee4/6dd5cbb）：攻城 creep 出发前到 industry 的 boost lab 旁强化，成功记 boostLog ==');
{
    const bo = require('../src/boost');
    const ind = require('../src/industry');
    const siegeRole = require('../src/roles/siegeDismantler');
    global.REACTIONS = { H: { O: 'OH' }, O: { H: 'OH' } };
    global.BOOSTS = { work: { XZH2O: { dismantle: 4 } }, heal: { XLHO2: { heal: 4 } } };
    resetWorld(54000);
    Memory.rooms = {};
    const br = makeRoom('W33S7', { rcl: 7, energy: 2300, cap: 2300, owner: 'me' });
    br._sources = [makeSource(br, 14, 6, 'bo0'), makeSource(br, 31, 12, 'bo1')];
    makeSpawn(br, 23, 21);
    makeStructure(br, C.STRUCTURE_STORAGE, 24, 22, { id: 'boStore', capacity: 1000000, energy: 200000 });
    makeStructure(br, C.STRUCTURE_TERMINAL, 25, 22, { id: 'boTerm', capacity: 300000, energy: 20000, extraStore: { H: 3000, O: 3000 } });
    const mkLab = (x, y, id, energy, store) => {
        const lab = makeStructure(br, C.STRUCTURE_LAB, x, y, { id, capacity: 5000, energy, extraStore: store || {} });
        lab.boosted = [];
        lab.boostCreep = (creep) => {
            if (Math.max(Math.abs(creep.pos.x - lab.pos.x), Math.abs(creep.pos.y - lab.pos.y)) > 1) return C.ERR_NOT_IN_RANGE;
            const type = Object.keys(lab.store).find((k) => typeof lab.store[k] === 'number' && k !== C.RESOURCE_ENERGY && lab.store[k] > 0);
            const partType = bo.partTypeFor(type);
            const parts = creep.body.filter((p) => p.type === partType && !p.boost);
            parts.forEach((p) => { p.boost = type; });
            lab.store[type] -= parts.length * bo.MINERAL_PER_PART;
            lab.store[C.RESOURCE_ENERGY] -= parts.length * bo.ENERGY_PER_PART;
            lab.boosted.push(creep.name);
            return C.OK;
        };
        return lab;
    };
    const input = mkLab(35, 21, 'sb1', 2000, { XZH2O: 900 });
    mkLab(36, 21, 'sb2', 0); mkLab(37, 21, 'sb3', 0);
    const boostLab = mkLab(10, 40, 'sb9', 2000, { XZH2O: 900 });
    ind.labPlan(br);
    assert(Memory.rooms.W33S7.labRoles && Memory.rooms.W33S7.labRoles.boost === 'sb9', 'industry 选出三连之外的 boost lab（得 ' + JSON.stringify(Memory.rooms.W33S7.labRoles) + '）');
    assert(bo.labFor(br, 'XZH2O', 3) === boostLab, '多个 lab 都有货时优先 labRoles.boost');
    const sd = makeCreep(br, 'boSd', ['work', 'work', 'work', 'move', 'move', 'move'],
        { role: 'siegeDismantler', home: 'W33S7', targetRoom: 'W31S4', staging: 'W32S5', squad: 1, boosts: ['XZH2O'] });
    world.creeps.boSd = sd;
    sd.pos = new RoomPosition(11, 40, 'W33S7');
    assert(bo.wanted(sd).length === 1 && bo.partTypeFor('XZH2O') === 'work', '还没上过的化合物算「想要」，BOOSTS 反查出 WORK');
    assert(bo.pending(sd) === true, 'boost lab 货与能量都够 ⇒ pending');
    siegeRole.run(sd);
    assert(boostLab.boosted.join() === 'boSd' && input.boosted.length === 0, '相邻 ⇒ 在 boost lab 强化（没碰三连里的 lab）');
    assert(sd.body.filter((p) => p.boost === 'XZH2O').length === 3 && boostLab.store.XZH2O === 900 - 90 && boostLab.store[C.RESOURCE_ENERGY] === 2000 - 60,
        '3 个 WORK 全上 XZH2O，lab 扣 90 化合物 + 60 能量');
    const log = Memory.rooms.W33S7.boostLog;
    assert(Array.isArray(log) && log.length === 1 && log[0].creep === 'boSd' && log[0].compound === 'XZH2O' && log[0].part === 'work' && log[0].parts === 3 && log[0].at === Game.time,
        '成功的强化记进母房 boostLog（得 ' + JSON.stringify(log) + '）');
    world.time++;
    assert(bo.wanted(sd).length === 0 && bo.pending(sd) === false && bo.run(sd) === false, '强化后不再想要，boost.run 放行');
    for (let i = 0; i < 12; i++) bo.noteBoost(sd, 'XZH2O', 'work', 1);
    assert(Memory.rooms.W33S7.boostLog.length === 10, 'boostLog 只留最近 10 条');
    const sd2 = makeCreep(br, 'boSd2', ['work', 'work', 'move', 'move'], { role: 'siegeDismantler', home: 'W33S7', targetRoom: 'W31S4', boosts: ['XZH2O'] });
    world.creeps.boSd2 = sd2;
    boostLab.store.XZH2O = 50; input.store.XZH2O = 50;
    assert(bo.labFor(br, 'XZH2O', 2) === null && bo.pending(sd2) === false, '货不够 ⇒ 跳过，不 pending');
    boostLab.store.XZH2O = 900; boostLab.store[C.RESOURCE_ENERGY] = 10; input.store[C.RESOURCE_ENERGY] = 10;
    assert(bo.pending(sd2) === false, 'lab 能量不够 ⇒ 也跳过');
    const sd3 = makeCreep(br, 'boSd3', ['work', 'move'], { role: 'siegeDismantler', home: 'W33S7', targetRoom: 'W31S4' });
    assert(bo.wanted(sd3).length === 0 && bo.pending(sd3) === false && bo.run(sd3) === false, '没配置 boosts 的 creep 不受影响');
    assert(Array.isArray(config.conquest.boosts.dismantler) && !config.conquest.boosts.dismantler.length && !config.conquest.boosts.guard.length,
        'config.conquest.boosts 默认空 = 关闭');
    delete world.creeps.boSd; delete world.creeps.boSd2;
    delete global.BOOSTS;
    delete global.REACTIONS;
}

console.log('== 实验室三连位：前三个 lab 必须能真的反应（切比雪夫 ≤ 2）==');
{
    const cheb = (a, b) => Math.max(Math.abs(a.x - b.x), Math.abs(a.y - b.y));
    const reactable = (list) => list.length >= 3 &&
        list.slice(0, 3).some((out, i) => list.slice(0, 3).every((other, k) => k === i || cheb(out, other) <= 2));
    let fixed = 0;
    for (const name of ['W33S7', 'W34S7', 'sample']) {
        const rawFile = JSON.parse(fs.readFileSync(path.join(__dirname, 'fixtures', 'wheel_layout_' + name + '.json'), 'utf8'));
        const labs = (rawFile.layout && rawFile.layout.lab) || [];
        if (labs.length < 3) continue;
        const plan = { labs: labs.map((p) => ({ x: p.x, y: p.y })) };
        const before = reactable(plan.labs);
        layout.normalizeLabPlan(plan);
        assert(reactable(plan.labs), name + ' 的前三个 lab 排序后可反应（原本 ' + before + '）');
        assert(plan.labs.length === labs.length, name + ' 只重排不丢位（' + plan.labs.length + '）');
        if (!before) fixed++;
    }
    assert(fixed >= 2, '三个固定件里至少两个原本不可反应、被这次排序修好（得 ' + fixed + '）');
    const okPlan = { labs: [{ x: 10, y: 10 }, { x: 11, y: 10 }, { x: 12, y: 10 }, { x: 30, y: 30 }] };
    const snapshot = JSON.stringify(okPlan.labs);
    layout.normalizeLabPlan(okPlan);
    assert(JSON.stringify(okPlan.labs) === snapshot, '前三个本来就能反应时保持原顺序');
    const nonePlan = { labs: [{ x: 1, y: 1 }, { x: 20, y: 20 }, { x: 40, y: 40 }] };
    const noneSnap = JSON.stringify(nonePlan.labs);
    layout.normalizeLabPlan(nonePlan);
    assert(JSON.stringify(nonePlan.labs) === noneSnap, '没有合法三连时保持原顺序');
}

