    world.exits.W33S7 = { '1': 'W33S6' };
    Memory.rooms = { W33S7: { sources: ['rv0', 'rv1'], plan: {}, remotes: {
        W33S6: { room: 'W33S6', enabled: true, sourceCount: 2, sources: [], reservation: { username: null, ticksToEnd: 0, seenAt: 0 } },
    } } };
