spawnMgr.run(ctrlLegRoom);
assert(Memory.rooms.W33S7.demand && Memory.rooms.W33S7.demand.targets.hauler === 3,
    '两源各 10/tick、controller 容器在 spawn 另一侧 12 格且无 storage 时 hauler 目标为 3');
