spawnMgr.run(ctrlLegRoom);
assert(Memory.rooms.W33S7.demand.targets.hauler === 3, '有 storage 但无 ctrl link 时 controller 容器仍靠 hauler 送，目标保持 3');
ctrlLegPlan.links = { ctrl: { x: 32, y: 24 } };
makeStructure(ctrlLegRoom, C.STRUCTURE_LINK, 32, 24, { energy: 0, capacity: 800 });
world.time++;
spawnMgr.run(ctrlLegRoom);
assert(Memory.rooms.W33S7.demand.targets.hauler === 2, '有 ctrl link 后 controller 段由 link 供给，hauler 目标回落为 2');
ctrlLegRoom.controller.level = 6;
const tenWork = ['work', 'work', 'work', 'work', 'work', 'work', 'work', 'work', 'work', 'work', 'carry', 'move'];
world.creeps['link.up0'] = makeCreep(ctrlLegRoom, 'link.up0', tenWork, { home: 'W33S7', role: 'upgrader' });
world.creeps['link.up1'] = makeCreep(ctrlLegRoom, 'link.up1', tenWork, { home: 'W33S7', role: 'upgrader' });
ctrlLegRoom.storage = makeStructure(ctrlLegRoom, C.STRUCTURE_STORAGE, 21, 20, { energy: SF_MID, capacity: 1000000 });
ctrlLegPlan.links = { ctrl: { x: 32, y: 24 }, src0: { x: 29, y: 13 }, src: { x: 29, y: 13 }, src1: { x: 16, y: 7 } };
makeStructure(ctrlLegRoom, C.STRUCTURE_LINK, 29, 13, { energy: 0, capacity: 800 });
world.time++;
spawnMgr.run(ctrlLegRoom);
assert(Memory.rooms.W33S7.demand.targets.hauler === 2, 'RCL6 一源 link 供能：底线 3 − 1 = 2（得 ' + Memory.rooms.W33S7.demand.targets.hauler + '）');
makeStructure(ctrlLegRoom, C.STRUCTURE_LINK, 16, 7, { energy: 0, capacity: 800 });
ctrlLegRoom.storage.store[C.RESOURCE_ENERGY] = SF_RICH;
world.time++;
spawnMgr.run(ctrlLegRoom);
assert(Memory.rooms.W33S7.demand.targets.hauler === 2 && Memory.rooms.W33S7.haulModel && Memory.rooms.W33S7.haulModel.linkFed === 2 &&
    Memory.rooms.W33S7.haulModel.floor === 2,
    'RCL6 两源都由 link 供能：底线不低于 linkFloorMin 2，haulModel 记 linkFed/floor（得 ' + JSON.stringify(Memory.rooms.W33S7.haulModel) + '）');
config.hauling.linkFloorDrop = 0;
world.time++;
spawnMgr.run(ctrlLegRoom);
assert(Memory.rooms.W33S7.demand.targets.hauler === 3, 'linkFloorDrop 为 0 时退回 RCL 底线 3（得 ' + Memory.rooms.W33S7.demand.targets.hauler + '）');
config.hauling.linkFloorDrop = 1;
delete world.creeps['link.up0'];
world.creeps['link.up1'].body = ['work', 'work', 'work', 'work', 'work', 'carry', 'move'].map((p) => ({ type: p }));
world.time++;
spawnMgr.run(ctrlLegRoom);
assert(Memory.rooms.W33S7.haulModel.linkFed === 0 && Memory.rooms.W33S7.haulModel.linkDrain === 5 && Memory.rooms.W33S7.haulModel.floor === 3 &&
    Memory.rooms.W33S7.haulModel.production === 15 && Memory.rooms.W33S7.demand.targets.hauler >= 3,
    'RCL6 升级者只有 5 WORK：link 只搬走 5/tick，其余 15/tick 仍计入运量、底线 3（得 ' + JSON.stringify(Memory.rooms.W33S7.haulModel) + '）');
ctrlLegRoom.controller.level = 7;
ctrlLegPlan.links.store = { x: 22, y: 19 };
makeStructure(ctrlLegRoom, C.STRUCTURE_LINK, 22, 19, { energy: 0, capacity: 800 });
ctrlLegRoom.storage.store[C.RESOURCE_ENERGY] = SF_UNDER;
world.time++;
spawnMgr.run(ctrlLegRoom);
assert(Memory.rooms.W33S7.demand.targets.hauler === 2 && Memory.rooms.W33S7.haulModel.linkFed === 2 && Memory.rooms.W33S7.haulModel.floor === 2,
    'RCL7 有 store link：两源都算 link 供能（不看升级者 WORK）、底线 linkFloorMinStore 2（得 ' + JSON.stringify(Memory.rooms.W33S7.haulModel) + '）');
assert(Memory.rooms.W33S7.demand.targets.operator === 1, 'RCL7 store link 贴着 storage：operator 编制 1（得 ' + Memory.rooms.W33S7.demand.targets.operator + '）');
world.time++;
taskBroker.beginTick();
const hubTasks = taskBroker.roomTasks(ctrlLegRoom);
const hubSrcCollect = hubTasks.filter((task) => task.kind === 'collect' && task.target && task.target.structureType === C.STRUCTURE_CONTAINER &&
    (task.target.pos.x === 30 && task.target.pos.y === 13 || task.target.pos.x === 15 && task.target.pos.y === 7));
const hubStorageCollect = hubTasks.find((task) => task.kind === 'collect' && task.target === ctrlLegRoom.storage);
assert(hubSrcCollect.length === 0, 'hub 模式：已接入 store 链的源容器不进 collect（得 ' + hubSrcCollect.length + '）');
assert(hubStorageCollect && hubStorageCollect.hub === true && hubStorageCollect.weight >= 8,
    'hub 模式：storage 取货不看富余、权重 8（得 ' + JSON.stringify(hubStorageCollect && [hubStorageCollect.weight, hubStorageCollect.hub, hubStorageCollect.rich]) + '）');
config.hauling.linkFloorMinStore = 1;
world.time++;
spawnMgr.run(ctrlLegRoom);
assert(Memory.rooms.W33S7.demand.targets.hauler === 1 && Memory.rooms.W33S7.haulModel.floor === 1,
    'linkFloorMinStore 调到 1 时底线才降到 1（留作"最后一只 hauler 零空窗"做出来后重试）（得 ' + Memory.rooms.W33S7.demand.targets.hauler + '）');
config.hauling.linkFloorMinStore = 2;
delete world.creeps['link.up1'];
ctrlLegRoom.controller.level = 3;
delete ctrlLegRoom.storage;

console.log('== operator：store link → storage 站桩倒能 ==');
