makeSpawn(stanceRoom, 23, 21);
const stanceContainer = makeStructure(stanceRoom, C.STRUCTURE_CONTAINER, 33, 25, { my: false, energy: 1000, capacity: 2000 });
Memory.rooms.W33S7 = {
    sources: [],
    plan: { anchor: { x: 23, y: 21 }, containers: { ctrl: { x: 33, y: 25 } }, workPositions: { ctrl: { x: 33, y: 25 } }, links: {}, roads: {} },
    state: { at: Game.time, recovering: false, emergencyHarvest: false },
};
const stanceBody = ['work', 'work', 'carry', 'carry', 'move'];
const upgraderOnContainer = makeCreep(stanceRoom, 'up.on', stanceBody, { home: 'W33S7', role: 'upgrader' });
const upgraderBeside = makeCreep(stanceRoom, 'up.beside', stanceBody, { home: 'W33S7', role: 'upgrader' });
world.creeps[upgraderOnContainer.name] = upgraderOnContainer;
world.creeps[upgraderBeside.name] = upgraderBeside;
upgraderOnContainer.pos = new RoomPosition(33, 25, 'W33S7');
upgraderOnContainer.store[RESOURCE_ENERGY] = 100;
upgraderBeside.pos = new RoomPosition(32, 25, 'W33S7');
upgraderBeside.store[RESOURCE_ENERGY] = 100;
ROLES.upgrader.run(upgraderBeside);
assert(upgraderBeside.actions.includes('upgradeController') && upgraderBeside.moveCalls.length === 0,
    '第二个 upgrader 在容器相邻且 controller 3 格内时直接升级，不抢容器格');
{
    const before = stanceContainer.hits;
    stanceContainer.hits = Math.floor(stanceContainer.hitsMax * 0.5);
    upgraderBeside.actions.length = 0;
    upgraderBeside.store[C.RESOURCE_ENERGY] = 100;
    world.time++;
    ROLES.upgrader.run(upgraderBeside);
    assert(upgraderBeside.actions.includes('repair') && !upgraderBeside.actions.includes('upgradeController'),
        '站位容器破损：升级者这一 tick 修容器而不是升级（得 ' + JSON.stringify(upgraderBeside.actions) + '）');
    stanceContainer.hits = stanceContainer.hitsMax;
    upgraderBeside.actions.length = 0;
    upgraderBeside.store[C.RESOURCE_ENERGY] = 100;
    world.time++;
    ROLES.upgrader.run(upgraderBeside);
    assert(upgraderBeside.actions.includes('upgradeController') && !upgraderBeside.actions.includes('repair'),
        '容器满血：照常升级（得 ' + JSON.stringify(upgraderBeside.actions) + '）');
    const savedBelow = config.upgraderRepairStationBelow;
    config.upgraderRepairStationBelow = 0;
    stanceContainer.hits = Math.floor(stanceContainer.hitsMax * 0.5);
    upgraderBeside.actions.length = 0;
    upgraderBeside.store[C.RESOURCE_ENERGY] = 100;
    world.time++;
    ROLES.upgrader.run(upgraderBeside);
    assert(!upgraderBeside.actions.includes('repair') && upgraderBeside.actions.includes('upgradeController'),
        'upgraderRepairStationBelow 设 0 时不修（得 ' + JSON.stringify(upgraderBeside.actions) + '）');
    config.upgraderRepairStationBelow = savedBelow;
    stanceContainer.hits = before;
}
upgraderBeside.store[RESOURCE_ENERGY] = 0;
upgraderBeside.actions.length = 0;
upgraderBeside.moveCalls.length = 0;
world.time++;
ROLES.upgrader.run(upgraderBeside);
assert(upgraderBeside.actions.includes('withdraw') && stanceContainer.store[RESOURCE_ENERGY] < 1000,
    '空仓 upgrader 从相邻 controller 容器取能');

world.time++;
stanceContainer.store[RESOURCE_ENERGY] = 0;
const stanceHauler = makeCreep(stanceRoom, 'hauler.stance', ['carry', 'carry', 'move'], { home: 'W33S7', role: 'hauler' });
world.creeps[stanceHauler.name] = stanceHauler;
upgraderBeside.store[RESOURCE_ENERGY] = 0;
upgraderBeside.actions.length = 0;
upgraderBeside.moveCalls.length = 0;
ROLES.upgrader.run(upgraderBeside);
assert(!upgraderBeside.actions.includes('withdraw') &&
    !upgraderBeside.moveCalls.some((m) => m.target && m.target.x === 23 && m.target.y === 21),
    '控制器容器暂空但 hauler 在岗时 upgrader 原地等待，不徒步去 spawn 取能');
delete world.creeps[stanceHauler.name];
world.time++;
upgraderBeside.actions.length = 0;
upgraderBeside.moveCalls.length = 0;
ROLES.upgrader.run(upgraderBeside);
assert(upgraderBeside.moveCalls.some((m) => m.target && m.target.x === 23 && m.target.y === 21),
    '没有 hauler 时 upgrader 仍会自己去 spawn 取能');

