console.log('== spawn 安静房降频：spawn 空闲、上轮全量推导无任何请求 ⇒ 错峰重算；恢复期/敌人/到期一律照常 ==');
{
    resetWorld(3301);
    const qRoom = makeRoom('W33S7', { rcl: 3, energy: 1050, cap: 1050, ctrl: { x: 34, y: 24 } });
    qRoom._sources = [makeSource(qRoom, 31, 12, 'qu0'), makeSource(qRoom, 14, 6, 'qu1')];
    makeSpawn(qRoom, 23, 21);
    const qPlan = { anchor: { x: 23, y: 21 },
        containers: { src0: { x: 30, y: 13 }, src1: { x: 15, y: 7 }, ctrl: { x: 33, y: 25 } },
        roads: { src0: road(10, 24, 20), src1: road(10, 22, 20), ctrl: road(12, 24, 22) }, links: {} };
    Memory.rooms.W33S7 = { sources: ['qu0', 'qu1'], plan: qPlan, state: { at: Game.time, recovering: false, emergencyHarvest: false } };
    for (const key of ['src0', 'src1', 'ctrl']) {
        const pos = qPlan.containers[key];
        qRoom._structs.push({ structureType: C.STRUCTURE_CONTAINER, pos: new RoomPosition(pos.x, pos.y, 'W33S7'), store: mkStore(200, 2000) });
    }
    world.creeps.quH0 = makeCreep(qRoom, 'quH0', utils.makeBody('staticHarvester', 1050), { home: 'W33S7', role: 'harvester', sourceIdx: 0, sourceId: 'qu0', staticMiner: true });
    world.creeps.quH1 = makeCreep(qRoom, 'quH1', utils.makeBody('staticHarvester', 1050), { home: 'W33S7', role: 'harvester', sourceIdx: 1, sourceId: 'qu1', staticMiner: true });
    world.creeps.quUp0 = makeCreep(qRoom, 'quUp0', utils.makeBody('upgrader', 1050), { home: 'W33S7', role: 'upgrader' });
    world.creeps.quUp1 = makeCreep(qRoom, 'quUp1', utils.makeBody('upgrader', 1050), { home: 'W33S7', role: 'upgrader' });
    world.creeps.quBu = makeCreep(qRoom, 'quBu', utils.makeBody('builder', 1050), { home: 'W33S7', role: 'builder' });
    for (const n of ['quHa0', 'quHa1', 'quHa2']) world.creeps[n] = makeCreep(qRoom, n, utils.makeBody('hauler', 800), { home: 'W33S7', role: 'hauler' }, { ticksToLive: 1400 });
    const qInterval = require('../src/config').spawnQueue.quietDemandInterval;
    assert(qInterval > 1, 'quietDemandInterval 默认开启（得 ' + qInterval + '）');
    const mem = () => Memory.rooms.W33S7;
    const nextTick = (phase) => { world.time++; while (utils.isRoomPhaseTick('W33S7', qInterval) !== phase) world.time++; qRoom.energyAvailable = 1050; };
    nextTick(true);
    spawnMgr.run(qRoom);
    assert(mem().spawnQuiet && mem().spawnQuiet.at === Game.time, '全量推导无请求 ⇒ 记下安静期（得 ' + JSON.stringify(mem().spawnQuiet) + '）');
    const fullAt = mem().demand.at;
    nextTick(false);
    spawnMgr.run(qRoom);
    assert(mem().demand.at === fullAt && mem().demand.quietSkipped >= 1, '安静期内的非刷新 tick：不重算编制并计数（得 at=' + mem().demand.at + '，跳过 ' + mem().demand.quietSkipped + '）');
    assert(mem().spawnQueue.quiet === true && mem().spawnQueue.at === Game.time, '跳过时 spawnQueue 仍每 tick 刷新 at 并标 quiet');
    qRoom._hostiles = [{ id: 'quEnemy', owner: { username: 'Invader' }, body: [{ type: 'attack', hits: 100 }], pos: new RoomPosition(10, 10, 'W33S7') }];
    nextTick(false);
    spawnMgr.run(qRoom);
    assert(mem().demand.at === Game.time && !mem().spawnQueue.quiet, '房里有敌人：不跳过，当 tick 全量推导');
    qRoom._hostiles = [];
    nextTick(true);
    spawnMgr.run(qRoom);
    assert(mem().demand.at === Game.time, '刷新 tick 全量推导');
    delete world.creeps.quH0; delete world.creeps.quH1;
    nextTick(false);
    mem().state = { at: -1 };
    spawnMgr.run(qRoom);
    assert(mem().demand.at === Game.time && mem().spawnQuiet === null, '恢复期不降频、安静期被清除（得 ' + JSON.stringify(mem().spawnQuiet) + '）');
    require('../src/config').spawnQueue.quietDemandInterval = 1;
    try {
        world.creeps.quH0 = makeCreep(qRoom, 'quH0', utils.makeBody('staticHarvester', 1050), { home: 'W33S7', role: 'harvester', sourceIdx: 0, sourceId: 'qu0', staticMiner: true });
        world.creeps.quH1 = makeCreep(qRoom, 'quH1', utils.makeBody('staticHarvester', 1050), { home: 'W33S7', role: 'harvester', sourceIdx: 1, sourceId: 'qu1', staticMiner: true });
        world.time++; mem().state = { at: -1 }; qRoom.energyAvailable = 1050;
        spawnMgr.run(qRoom);
        world.time++; mem().state = { at: -1 }; qRoom.energyAvailable = 1050;
        spawnMgr.run(qRoom);
        assert(mem().demand.at === Game.time, 'quietDemandInterval=1 时每 tick 全量推导');
    } finally { require('../src/config').spawnQueue.quietDemandInterval = qInterval; }
}

console.log('== broker 分层投递：ctrl 容器成为 hauler 的正式投递目标，且 spawn/ext 优先、tower 只在缺口≥300 时补 ==');
resetWorld(3310);
const tierRoom = makeRoom('W33S7', { rcl: 3, energy: 800, cap: 800, ctrl: { x: 34, y: 24 } });
tierRoom._sources = [makeSource(tierRoom, 14, 6, 'tr0'), makeSource(tierRoom, 31, 12, 'tr1')];
const tierSpawn = makeSpawn(tierRoom, 23, 21);
const tierTower = makeStructure(tierRoom, C.STRUCTURE_TOWER, 23, 19, { store: mkStore(990, 1000) });
const tierCtrlContainer = makeStructure(tierRoom, C.STRUCTURE_CONTAINER, 33, 25, { my: false, energy: 0, capacity: 2000 });
const tierSrcContainer = makeStructure(tierRoom, C.STRUCTURE_CONTAINER, 15, 6, { my: false, energy: 1500, capacity: 2000 });
Memory.rooms.W33S7 = {
    sources: ['tr0', 'tr1'],
    plan: { anchor: { x: 23, y: 21 }, containers: { ctrl: { x: 33, y: 25 }, src0: { x: 15, y: 6 } }, workPositions: { ctrl: { x: 33, y: 25 } }, links: {}, roads: {} },
    state: { at: Game.time, recovering: false, emergencyHarvest: false },
};
taskBroker.beginTick();
const tierTasks = taskBroker.roomTasks(tierRoom);
const tierCtrlTask = tierTasks.find((task) => task.kind === 'deliver' && task.target === tierCtrlContainer);
assert(tierCtrlTask && tierCtrlTask.backlog === 2000, 'ctrl 容器缺能时出现在 broker deliver 任务池');
assert(!tierTasks.some((task) => task.kind === 'deliver' && task.target === tierTower), 'tower 缺口 <300 且无敌人时不发布 deliver 任务');
assert(!tierTasks.some((task) => task.kind === 'deliver' && task.target === tierSrcContainer), 'source 容器不是投递目标');
const tierHauler = makeCreep(tierRoom, 'tier.hauler', utils.makeBody('hauler', 800), { home: 'W33S7', role: 'hauler' });
world.creeps[tierHauler.name] = tierHauler;
tierHauler.pos = new RoomPosition(32, 24, 'W33S7');
tierHauler.store[RESOURCE_ENERGY] = 500;
ROLES.hauler.run(tierHauler);
assert(tierCtrlContainer.store[RESOURCE_ENERGY] === 500 && tierTower.store[RESOURCE_ENERGY] === 990,
    'spawn/ext 已满时 hauler 把能量送到 ctrl 容器而非给 tower 补 10 能量');
const tierBuilder = makeCreep(tierRoom, 'tier.builder', ['work', 'carry', 'move'], { home: 'W33S7', role: 'builder' });
world.creeps[tierBuilder.name] = tierBuilder;
tierBuilder.store[RESOURCE_ENERGY] = 50;
assert(taskBroker.pickTask(tierBuilder, tierRoom, (task) => task.kind === 'deliver' && task.target === tierCtrlContainer, false) == null,
    'ctrl 容器投递任务只对 hauler 开放，builder 不会被吸去搬运');
world.time += 3;
tierSpawn.store[RESOURCE_ENERGY] = 100;
tierRoom.energyAvailable = 600;
tierHauler.store[RESOURCE_ENERGY] = 500;
tierHauler.pos = new RoomPosition(24, 22, 'W33S7');
tierHauler.moveCalls.length = 0;
tierHauler.actions.length = 0;
ROLES.hauler.run(tierHauler);
assert(tierSpawn.store[RESOURCE_ENERGY] > 100 && tierCtrlContainer.store[RESOURCE_ENERGY] === 500,
    'spawn 缺能时 hauler 优先回补 spawn（即便手里还握着 ctrl 容器租约）');
world.time++;
tierSpawn.store[RESOURCE_ENERGY] = 300;
tierRoom.energyAvailable = 800;
assert(taskBroker.pickTask(tierHauler, tierRoom, (task) => task.kind === 'deliver' && task.tier === 1, false) == null,
    '重算间隔内 spawn 被填满后，deliver 任务用当前 tick 对象刷新并退出池子');
world.time += 3;
tierTower.store[RESOURCE_ENERGY] = 600;
taskBroker.beginTick();
const tierTasks2 = taskBroker.roomTasks(tierRoom);
assert(tierTasks2.some((task) => task.kind === 'deliver' && task.target === tierTower), 'tower 缺口 ≥300 时发布 deliver 任务');
tierHauler.memory.brokerTask = { kind: 'deliver', id: tierCtrlContainer.id, until: Game.time - 1 };
taskBroker.pickTask(tierHauler, tierRoom, (task) => task.kind === 'deliver', true);
