console.log('== 外部大脑指令：校验、情报合并、访问器与回执 ==');
resetWorld(3400);
const brainRoom = makeRoom('W33S7', { rcl: 3, energy: 800, cap: 800, ctrl: { x: 34, y: 24 } });
makeSpawn(brainRoom, 23, 21);
Memory.rooms.W33S7 = { sources: [], plan: {}, state: { at: Game.time, recovering: false, emergencyHarvest: false } };
Memory.map = { W33S6: { at: 100, sources: 1, owner: null, source: 'scout' } };
Memory.errors = [];
const brainMod = require('brain');
Memory.brain = {
    version: 1,
    issuedAt: Date.now() - 1000,
    ttlMs: 1800000,
    intel: {
        W34S7: { at: 3000, sources: 2, sourceData: [{ id: 'a', x: 19, y: 19, energyCapacity: 3000 }, { id: 'b', x: 36, y: 40, energyCapacity: 3000 }], owner: null, reservation: null, lairs: 0, mineral: 'L', hostiles: 0, armedHostiles: 0, invaderCore: false, threat: false, controllerPos: { x: 31, y: 41 } },
        W33S6: { at: 50, sources: 1, owner: null },
    },
    rooms: { W33S7: { remotes: ['W34S7'], claim: { room: 'W34S7', priority: 1 } } },
};
brainMod.run();
assert(Memory.map.W34S7 && Memory.map.W34S7.source === 'external' && Memory.map.W34S7.sources === 2,
    '外部情报合并进 Memory.map 并标记来源');
assert(Memory.map.W33S6.source === 'scout' && Memory.map.W33S6.at === 100,
    '比现有条目更旧的外部情报不会覆盖 scout 的记录');
assert(Memory.brain.ack && Memory.brain.ack.tick === Game.time && Memory.brain.ack.issuedAt === Memory.brain.issuedAt,
    '游戏内写回 ack（tick 与 issuedAt）');
const brainDirective = brainMod.directive('W33S7');
assert(brainDirective && brainDirective.claim && brainDirective.claim.room === 'W34S7' && brainDirective.remotes[0] === 'W34S7',
    'directive(room) 返回该房间的指令');
assert(brainMod.directive('W99S99') == null, '无指令的房间返回 null');
assert(Memory.errors.length === 0, '有效指令不产生错误记录');

world.time++;
Memory.brain.issuedAt = Date.now() - 3600000;
brainMod.run();
assert(brainMod.directive('W33S7') != null && Memory.brain.stale === true && brainMod.isStale(),
    '超过 ttl 但在 6 小时宽限内：指令继续提供并标记 stale（得 ' + JSON.stringify(brainMod.directive('W33S7')) + ' stale=' + Memory.brain.stale + '）');
world.time++;
Memory.brain.issuedAt = Date.now() - 1800000 - brainMod.STALE_GRACE_MS - 1000;
config.brain = { retired: false };
Memory.brainRetiredAlert = { at: Game.time };
assert(brainMod.directive('W33S7') == null, '超过 ttl + 宽限的指令视为过期，访问器返回 null');
assert(brainMod.offlineMs() > 0, '过期后算掉线（offlineMs > 0）');
config.brain = { retired: true };
world.time++;
assert(brainMod.directive('W33S7') != null && Memory.brain.frozen === true && brainMod.offlineMs() === 0,
    'config.brain.retired：过期指令冻结沿用、不算掉线（得 ' + JSON.stringify(brainMod.directive('W33S7')) + ' offline=' + brainMod.offlineMs() + '）');
config.brain = { retired: false };
Memory.brainRetiredAlert = { at: Game.time };
world.time++;
assert(Memory.map.W34S7.source === 'external', '过期只影响指令，已合并的情报保留');

world.time++;
Memory.brain = { version: 99, issuedAt: Date.now(), ttlMs: 1000000, rooms: { W33S7: { remotes: ['W33S8'] } } };
brainMod.run();
assert(brainMod.directive('W33S7') == null && Memory.errors.length === 1 && /brain/.test(Memory.errors[0].where || Memory.errors[0].msg || JSON.stringify(Memory.errors[0])),
    '版本不匹配的指令整份忽略并记一条错误');
world.time++;
brainMod.run();
assert(Memory.errors.length === 1, '同一份坏指令不会每 tick 重复记错');

world.time++;
delete Memory.brain;
brainMod.run();
assert(brainMod.directive('W33S7') == null && Memory.errors.length === 1, '没有指令时静默退回自治');

