assert(!(90 in RawMemory.segments), '读完后从 RawMemory.segments 删掉 90：引擎只写回对象上存在的键，避免把大脑刚写的指令原样覆盖');
assert(Memory.brain && Memory.brain.issuedAt === segDirective.issuedAt && Memory.map.W33S8 && Memory.map.W33S8.source === 'external',
    'segment 里的指令被解析进 Memory.brain 并合并情报');
