RawMemory.segments[90] = JSON.stringify(segDirective);
segBrain.run();
assert(Memory.brain.rooms.W33S7.remotes[0] === 'changed-in-game', 'segment 内容未变时不重复解析，不覆盖游戏内状态');
world.time++;
const segDirective2 = Object.assign({}, segDirective, { issuedAt: segDirective.issuedAt + 5, rooms: { W33S7: { remotes: ['W32S7'] } } });
