segBrain.run();
assert(Memory.brain.issuedAt === segDirective2.issuedAt && segBrain.directive('W33S7').remotes[0] === 'W32S7', '新 issuedAt 的 segment 内容替换旧指令');
world.time++;
RawMemory.segments[90] = '{not json';
segBrain.run();
assert(Memory.brain.issuedAt === segDirective2.issuedAt && Memory.errors.length === 1, '坏 JSON 只记一次错误，保留上一份有效指令');
world.time++;
segBrain.run();
assert(Memory.errors.length === 1, '同样的坏 JSON 不重复记错');
delete global.RawMemory;

