['ex0', 'ex1'].forEach((id, index) => { world.creeps['exH' + index] = makeCreep(expHome, 'exH' + index, utils.makeBody('harvester', 800), { home: 'W33S7', role: 'harvester', sourceIdx: index, sourceId: id }); });
for (let i = 0; i < 4; i++) world.creeps['exHa' + i] = makeCreep(expHome, 'exHa' + i, utils.makeBody('hauler', 800), { home: 'W33S7', role: 'hauler' });
for (let i = 0; i < 2; i++) world.creeps['exUp' + i] = makeCreep(expHome, 'exUp' + i, utils.makeBody('upgrader', 800), { home: 'W33S7', role: 'upgrader' });
