Game.gcl = { level: 2, progress: 0, progressTotal: 1 };
Memory.brain = {
    version: 1, issuedAt: Date.now(), ttlMs: 1800000,
    intel: { W34S7: { at: Game.time, sources: 2, owner: null, controllerPos: { x: 31, y: 41 } } },
    rooms: { W33S7: { remotes: [], scouts: 0, claim: { room: 'W34S7', priority: 1, spawnPos: { x: 24, y: 36 } } } },
};
require('brain').run();
const expansionMod = require('expansion');
const expDemands = expansionMod.getDemands(expHome);
assert(expDemands.length >= 1 && expDemands[0].role === 'claimer' && expDemands[0].body.join() === 'claim,move' &&
    expDemands[0].memory.targetRoom === 'W34S7' && !expDemands[0].memory.spawnPos,
    'claim 指令 + GCL 余量 → 先要一个 [CLAIM,MOVE] claimer，带目标房；指令里的 spawnPos 不采用（布局只认轮子）');
