function waitScene(seed, sinceAgo, energy) {
    resetWorld(seed);
    const room = makeRoom('W33S7', { rcl: 5, energy: energy == null ? 1015 : energy, cap: 1600, ctrl: { x: 34, y: 24 }, owner: 'me' });
    room._sources = [makeSource(room, 31, 12, 'wt0'), makeSource(room, 14, 6, 'wt1')];
    makeSpawn(room, 23, 21);
    const plan = {
        anchor: { x: 23, y: 21 },
        containers: { src0: { x: 30, y: 13 }, src1: { x: 15, y: 7 }, ctrl: { x: 33, y: 25 } },
        roads: { src0: road(10, 24, 20), src1: road(10, 22, 20), ctrl: road(12, 24, 22) },
        links: {},
    };
    Memory.rooms.W33S7 = { sources: ['wt0', 'wt1'], plan, state: { at: Game.time, recovering: false, emergencyHarvest: false },
        spawnSince: sinceAgo == null ? {} : { 'core:hauler:1': Game.time - sinceAgo } };
    for (const key of ['src0', 'src1', 'ctrl']) {
        const pos = plan.containers[key];
        room._structs.push({ structureType: C.STRUCTURE_CONTAINER, pos: new RoomPosition(pos.x, pos.y, 'W33S7'), store: mkStore(1500, 2000) });
    }
    Memory.map = {};
    ['wt0', 'wt1'].forEach((id, index) => { world.creeps['wtH' + index] = makeCreep(room, 'wtH' + index, utils.makeBody('staticHarvester', 1600), { home: 'W33S7', role: 'harvester', sourceIdx: index, sourceId: id, staticMiner: true }); });
    world.creeps.wtHa = makeCreep(room, 'wtHa', utils.makeBody('hauler', 1000), { home: 'W33S7', role: 'hauler' });
    world.creeps.wtUp = makeCreep(room, 'wtUp', utils.makeBody('upgrader', 1600), { home: 'W33S7', role: 'upgrader' });
    world.creeps.wtBu = makeCreep(room, 'wtBu', utils.makeBody('builder', 1600), { home: 'W33S7', role: 'builder' });
    Memory.brain = { version: 1, issuedAt: Date.now(), ttlMs: 1800000, intel: {}, rooms: { W33S7: { remotes: [], scouts: 0, claim: null } } };
    require('brain').run();
    return room;
}
const wtFullCost = utils.bodyCost(utils.makeBody('hauler', 1600));
assert(wtFullCost === 1600, '前提：1600 容量的满配 hauler 成本恰好等于容量（得 ' + wtFullCost + '）');
