console.log('== spawn 队列调度器（纯函数）：等待 / 缩身 / 紧急态 / strategic 穿越 / jumpable / opportunistic ==');
const sq = require('spawn_queue');
const fixed = (cost) => Array.from({ length: cost / 50 }, () => 'move');
const scalable = (key, priority, grace, extra) => Object.assign({
    key, role: 'hauler', priority, grace,
    body: (budget) => (budget >= 150 ? fixed(Math.min(1000, Math.floor(budget / 100) * 100)) : []),
}, extra || {});
const fixedReq = (key, priority, cost, extra) => Object.assign({ key, role: 'x', priority, grace: 300, ordered: true, body: (budget) => (budget >= cost ? fixed(cost) : []) }, extra || {});
let sqRes = sq.schedule([scalable('a', 1, 100)], { now: 1000, energy: 600, capacity: 1000, income: 10, spawnsFree: 1, since: {} });
assert(sqRes.actions.length === 0 && sqRes.waiting && sqRes.waiting.cost === 1000 && sqRes.waiting.eta === 40, '缺 400、收入 10：40 tick 内攒够、宽限 100 → 等（得 ' + JSON.stringify(sqRes.waiting) + '）');
sqRes = sq.schedule([scalable('a', 1, 100)], { now: 1000, energy: 600, capacity: 1000, income: 10, spawnsFree: 1, since: { a: 880 } });
assert(sqRes.actions.length === 1 && sqRes.actions[0].scaled && sqRes.actions[0].cost === 600, '宽限已过：缩身到 600（得 ' + JSON.stringify(sqRes.actions.map((x) => x.cost)) + '）');
sqRes = sq.schedule([scalable('a', 1, 100)], { now: 1000, energy: 300, capacity: 1000, income: 10, spawnsFree: 1, since: { a: 500 } });
assert(sqRes.actions.length === 0 && sqRes.waiting, '收入 > 0 时缩身下限是容量一半：300 不孵（得 ' + JSON.stringify(sqRes.actions) + '）');
sqRes = sq.schedule([scalable('a', 1, 100, { vital: true })], { now: 1000, energy: 300, capacity: 1000, income: 0, spawnsFree: 1, since: {} });
assert(sqRes.actions.length === 1 && sqRes.actions[0].cost === 300, '收入 0 是紧急态：vital 请求刚出现也立刻用 300 孵（得 ' + JSON.stringify(sqRes.actions.map((x) => x.cost)) + '）');
sqRes = sq.schedule([scalable('b', 4, 100)], { now: 1000, energy: 300, capacity: 1000, income: 0, spawnsFree: 1, since: { b: 500 } });
assert(sqRes.actions.length === 0 && sqRes.waiting && sqRes.waiting.key === 'b', '收入 0 时非 vital 请求守正常下限（容量一半），300 不孵（得 ' + JSON.stringify(sqRes.actions.map((x) => x.cost)) + '）');
sqRes = sq.schedule([scalable('core', 1, 100), fixedReq('claim', 3, 650, { strategic: true }), fixedReq('remote', 5, 400)],
    { now: 1000, energy: 700, capacity: 1000, income: 10, spawnsFree: 2, since: {} });
assert(sqRes.actions.length === 1 && sqRes.actions[0].request.key === 'claim' && sqRes.blocked.join() === 'remote',
    '核心角色等能量：strategic 的占领穿过去，外矿被挡（得 ' + JSON.stringify(sqRes.actions.map((x) => x.request.key)) + ' blocked ' + sqRes.blocked + '）');
sqRes = sq.schedule([fixedReq('reserver', 5, 1300, { jumpable: true }), fixedReq('miner', 5, 700, { jumpable: true }), fixedReq('extra', 6, 100, { opportunistic: true })],
    { now: 1000, energy: 800, capacity: 1300, income: 10, spawnsFree: 2, since: {} });
assert(sqRes.actions.length === 1 && sqRes.actions[0].request.key === 'miner' && sqRes.blocked.join() === 'extra' && sqRes.waiting.key === 'reserver',
    'jumpable：买不起的 reserver 不挡同级矿工，只挡更低的富余请求（得 ' + JSON.stringify(sqRes.actions.map((x) => x.request.key)) + ' blocked ' + sqRes.blocked + '）');
sqRes = sq.schedule([fixedReq('extra', 6, 1000, { opportunistic: true })], { now: 1000, energy: 800, capacity: 1000, income: 10, spawnsFree: 1, since: {} });
assert(sqRes.actions.length === 0 && !sqRes.waiting, 'opportunistic 买不起就跳过，不等待（得 ' + JSON.stringify(sqRes) + '）');
sqRes = sq.schedule([fixedReq('defender', 0, 1300, { strategic: true, blocking: false }), scalable('core', 1, 100)],
    { now: 1000, energy: 1000, capacity: 1300, income: 10, spawnsFree: 1, since: {} });
assert(sqRes.actions.length === 1 && sqRes.actions[0].request.key === 'core', '防御买不起不为自己保留能量：核心角色照常孵（得 ' + JSON.stringify(sqRes.actions.map((x) => x.request.key)) + '）');
sqRes = sq.schedule([scalable('builder', 2, 150, { blocking: false }), fixedReq('remote', 5, 400, { jumpable: true })],
    { now: 1000, energy: 700, capacity: 1000, income: 10, spawnsFree: 2, since: {} });
assert(sqRes.actions.length === 1 && sqRes.actions[0].request.key === 'remote' && sqRes.waiting && sqRes.waiting.key === 'builder',
    'blocking=false 的 builder 等能量不挡外矿（得 ' + JSON.stringify(sqRes.actions.map((x) => x.request.key)) + '）');
sqRes = sq.schedule([scalable('h0', 1, 100), scalable('h1', 1, 100)], { now: 1000, energy: 2000, capacity: 1000, income: 10, spawnsFree: 2, since: {} });
assert(sqRes.actions.length === 2 && sqRes.actions.every((x) => x.cost === 1000), '两个空闲 spawn 共用同一预算（得 ' + JSON.stringify(sqRes.actions.map((x) => x.cost)) + '）');

