console.log('== 新房没有 spawn 时也由轮子规划：spawn1 取轮子的第一个 spawn 位并可视化 ==');
resetWorld(3510);
const anRoom = makeRoom('W34S7', { rcl: 1, my: true, ctrl: { x: 31, y: 41 } });
anRoom._sources = [makeSource(anRoom, 36, 40, 'an0'), makeSource(anRoom, 19, 19, 'an1')];
Memory.rooms.W34S7 = {};
Memory.errors = [];
plannerState.cache.W34S7 = { layout: wheelFixture('W34S7') };
layout.run(anRoom);
const anPlan = Memory.rooms.W34S7.plan;
const anFixture = wheelFixture('W34S7');
assert(anPlan && anPlan.wheel && anPlan.spawns[0].x === anFixture[C.STRUCTURE_SPAWN][0].x && anPlan.spawns[0].y === anFixture[C.STRUCTURE_SPAWN][0].y, '无 spawn 的新房也采用轮子方案，spawn1 = 轮子给的第一个 spawn 位');
assert(anPlan.containers && anPlan.containers.src0 && anPlan.roads && anPlan.roads.all, '有了容器位与道路规划');
assert(require('visuals').render(anRoom) === true, '有规划后 RoomVisual 会绘制');
assert(Memory.errors.length === 0, '无 spawn 房间规划不报错');

console.log('== RoomVisual 顺序：唯一/高价值结构先画，extension 其次，路网与 rampart 最后；已建成的不画 ==');
{
    const anBuiltSpawn = makeSpawn(anRoom, anPlan.spawns[0].x, anPlan.spawns[0].y);
    const anRoadTile = anPlan.roads.all.split(';')[0].split('.').map(Number);
    makeStructure(anRoom, C.STRUCTURE_ROAD, anRoadTile[0], anRoadTile[1]);
    const drawn = [];
    const texts = [];
    const OrigVisual = global.RoomVisual;
    global.RoomVisual = class extends OrigVisual {
        structure(x, y, type) { drawn.push({ type, x, y }); return this; }
        text(s) { texts.push(String(s)); return this; }
    };
    try { require('visuals').render(anRoom); } finally { global.RoomVisual = OrigVisual; }
    assert(texts.some((s) => s.startsWith('规划 ') && s.includes('未建 ')), '始终画方案标签（版本 + 未建数量）：' + JSON.stringify(texts.slice(0, 2)));
    {
        const fullTexts = [];
        const fullDrawn = [];
        global.RoomVisual = class extends OrigVisual {
            structure(x, y, type) { fullDrawn.push(type); return this; }
            text(s) { fullTexts.push(String(s)); return this; }
        };
        const fullRoom = makeRoom('W35S7', { rcl: 8, owner: 'me' });
        makeStructure(fullRoom, C.STRUCTURE_STORAGE, 20, 20);
        makeStructure(fullRoom, C.STRUCTURE_TERMINAL, 21, 20);
        Memory.rooms.W35S7 = { plan: { wheel: true, version: 'test', storage: { x: 20, y: 20 }, terminal: { x: 21, y: 20 } } };
        try { require('visuals').render(fullRoom); } finally { global.RoomVisual = OrigVisual; }
        assert(fullDrawn.length === 0 && fullTexts.length === 1 && fullTexts[0].endsWith('未建 0'), '方案全部建成时不画结构、只画标签（得 ' + JSON.stringify({ fullDrawn, fullTexts }) + '）');
    }
    const firstOf = (type) => drawn.findIndex((d) => d.type === type);
    const drawnCounts = drawn.reduce((a, d) => (a[d.type] = (a[d.type] || 0) + 1, a), {});
    assert([C.STRUCTURE_TERMINAL, C.STRUCTURE_FACTORY, C.STRUCTURE_NUKER, C.STRUCTURE_POWER_SPAWN, C.STRUCTURE_STORAGE].every((t) => firstOf(t) >= 0),
        'terminal/factory/nuker/powerSpawn/storage 都在绘制列表里（得 ' + JSON.stringify(drawnCounts) + '）');
    assert(firstOf(C.STRUCTURE_NUKER) < firstOf(C.STRUCTURE_EXTENSION) && firstOf(C.STRUCTURE_EXTENSION) < firstOf(C.STRUCTURE_ROAD) &&
        firstOf(C.STRUCTURE_ROAD) < firstOf(C.STRUCTURE_RAMPART), '绘制顺序：nuker 等唯一结构 < extension < 道路 < rampart');
    assert(!drawn.some((d) => d.type === C.STRUCTURE_SPAWN && d.x === anBuiltSpawn.pos.x && d.y === anBuiltSpawn.pos.y), '已建成的 spawn 不再画');
    assert(!drawn.some((d) => d.type === C.STRUCTURE_ROAD && d.x === anRoadTile[0] && d.y === anRoadTile[1]), '已建成的道路不再画');
    assert(drawnCounts[C.STRUCTURE_RAMPART] === anPlan.ramparts.length, '整条 rampart 环都画，不再被结构条目上限截掉（得 ' + drawnCounts[C.STRUCTURE_RAMPART] + '/' + anPlan.ramparts.length + '）');
}

