assert(dfCore.some((d) => d.role === 'defender' && d.slot === 'core:W33S8' && d.memory.targetRoom === 'W33S8' && d.body.filter((p) => p === 'attack').length >= 5),
    '外矿被 InvaderCore 占据 → 要一只纯 ATTACK 的清核心队');
