console.log('== 身体按敌情选：会冲上来的（带 ATTACK）Invader 用最便宜能赢的近战；风筝型（只有远程）只用远程，低容量就出一组 ==');
resetWorld(4900);
const ldHome = makeRoom('W34S7', { rcl: 2, energy: 550, cap: 550, ctrl: { x: 31, y: 41 }, owner: 'me' });
ldHome._sources = [makeSource(ldHome, 19, 19, 'ld0'), makeSource(ldHome, 35, 39, 'ld1')];
makeSpawn(ldHome, 27, 18);
Memory.rooms.W34S7 = { sources: ['ld0', 'ld1'], plan: {}, state: { at: Game.time, recovering: false, emergencyHarvest: false }, remotes: {} };
Memory.map = {};
delete Memory.brain;
makeHostile(ldHome, 24, 17, ['tough', 'tough', 'move', 'move', 'move', 'move', 'ranged_attack', 'work', 'attack', 'move'], { owner: 'Invader', hits: 776 });
const ldDemands = require('defense').getDemands(ldHome);
assert(ldDemands.length === 1 && ldDemands[0].memory.style === 'melee' &&
    ldDemands[0].body.filter((p) => p === 'attack').length === 3,
    '容量 550 遇 1R1A 的近战型 Invader（776 血、40 伤害）：最便宜能赢的近战 3A3M（得 ' + JSON.stringify(ldDemands[0] && [ldDemands[0].memory.style, ldDemands[0].body.join(',')]) + '）');
ldHome.energyCapacityAvailable = 1300;
const ldDemands2 = require('defense').getDemands(ldHome);
assert(ldDemands2.length === 1 && ldDemands2[0].memory.style === 'melee' && ldDemands2[0].body.filter((p) => p === 'attack').length === 3,
    '容量 1300 对同一只近战型仍是 3A3M：不为容量大就买贵的（得 ' + JSON.stringify(ldDemands2[0] && [ldDemands2[0].memory.style, ldDemands2[0].body.join(',')]) + '）');
ldHome._hostiles.length = 0;
world.time++;
makeHostile(ldHome, 24, 17, ['tough', 'tough', 'move', 'move', 'move', 'move', 'ranged_attack', 'ranged_attack', 'ranged_attack', 'move'], { owner: 'Invader', hits: 1000 });
ldHome.energyCapacityAvailable = 550;
const ldKite = require('defense').getDemands(ldHome);
assert(ldKite.length >= 2 && ldKite.every((d) => d.memory.style === 'ranged' && d.memory.squad === ldKite.length && !d.body.includes('attack')) &&
    require('defense').canBeat(ldKite.map((d) => d.body), require('defense').hostileProfile(ldHome._hostiles)) &&
    !require('defense').canBeat([ldKite[0].body], require('defense').hostileProfile(ldHome._hostiles)),
    '容量 550 遇风筝型（3R，1000 血）：单只打不过就出一组远程（得 ' + JSON.stringify(ldKite.map((d) => d.body.join(''))) + '）');
ldHome.energyCapacityAvailable = 1300;
const ldKite2 = require('defense').getDemands(ldHome);
assert(ldKite2.length === 1 && ldKite2[0].memory.style === 'ranged' && !ldKite2[0].body.includes('attack') &&
    require('defense').canBeat([ldKite2[0].body], require('defense').hostileProfile(ldHome._hostiles)),
    '容量 1300 对同一只风筝型：一只就够（得 ' + JSON.stringify(ldKite2.map((d) => d.body.join(''))) + '）');

