console.log('== 迁移提速：extension 允许 batch 个替代工地同时在建；塔在 safe mode 可用时直接替换；方案内容器建成后旧容器拆除 ==');
const mbRoom = demoRoom(6400, 4);
const mbPlan = Memory.rooms.W33S7.plan;
const mbCfg = require('../src/config').demolition;
makeSpawn(mbRoom, 23, 21);
['src0', 'src1', 'ctrl'].forEach((k) => { const c = mbPlan.containers[k]; makeStructure(mbRoom, C.STRUCTURE_CONTAINER, c.x, c.y, { capacity: 2000, energy: 0 }); });
const mbExts = [];
for (let i = 0; i < 20; i++) mbExts.push(makeStructure(mbRoom, C.STRUCTURE_EXTENSION, 3 + i, 45, { capacity: 50, energy: 0 }));
const mbOldTower = makeStructure(mbRoom, C.STRUCTURE_TOWER, 20, 20, { capacity: 1000, energy: 500 });
const mbOldCont = makeStructure(mbRoom, C.STRUCTURE_CONTAINER, 7, 7, { capacity: 2000, energy: 0 });
mbRoom.controller.safeModeAvailable = 1;
const mbInterval = mbCfg.interval;
function mbTick() { while (!utils.isRoomPhaseTick(mbRoom.name, mbInterval)) world.time++; demolition.run(mbRoom); world.time++; }
assert(mbInterval <= 25, '拆迁评估间隔 ≤25 tick（得 ' + mbInterval + '）');
let mbDestroyedExt = 0;
for (let i = 0; i < 10; i++) {
    mbTick();
    layout.run(mbRoom);
    mbDestroyedExt = mbExts.filter((e) => e.actions.includes('destroy')).length;
}
const mbExtSites = mbRoom.find(C.FIND_MY_CONSTRUCTION_SITES).filter((x) => x.structureType === C.STRUCTURE_EXTENSION).length;
assert(mbDestroyedExt >= mbCfg.batch && mbExtSites >= mbCfg.batch && mbDestroyedExt <= mbCfg.batch + 1,
    '替代工地在建数达到 batch(' + mbCfg.batch + ') 前持续替换 extension（拆 ' + mbDestroyedExt + '，在建 ' + mbExtSites + '）');
assert(mbOldTower.actions.includes('destroy'), 'safe mode 可用时唯一的方案外塔也直接替换');
assert(mbOldCont.actions.includes('destroy'), '方案内容器都建成后，方案外旧容器拆除');
const mbRoom2 = demoRoom(6500, 4);
makeSpawn(mbRoom2, 23, 21);
const mbTower2 = makeStructure(mbRoom2, C.STRUCTURE_TOWER, 20, 20, { capacity: 1000, energy: 500 });
mbRoom2.controller.safeModeAvailable = 0;
for (let i = 0; i < 3; i++) { while (!utils.isRoomPhaseTick(mbRoom2.name, mbInterval)) world.time++; demolition.run(mbRoom2); world.time++; }
assert(!mbTower2.actions.includes('destroy'), 'safe mode 不可用时唯一的塔保留到方案位的塔建成');

