world.creeps.scHa = makeCreep(scHome, 'scHa', utils.makeBody('hauler', 1100), { home: 'W33S7', role: 'hauler' });
world.creeps.scHb = makeCreep(scHome, 'scHb', utils.makeBody('hauler', 1100), { home: 'W33S7', role: 'hauler' });
world.creeps.scUp = makeCreep(scHome, 'scUp', utils.makeBody('upgrader', 1100), { home: 'W33S7', role: 'upgrader' });
