assert(lrBuilder.actions.includes('moveTo') || lrBuilder.actions.includes('withdraw'), '等投递超过 builderFeedMaxWait：不再干等，自己去源容器取能（得 ' + lrBuilder.actions.join(',') + '）');
delete world.creeps[lrHauler.name];
delete lrBuilder.memory.waitSince;
lrBuilder.store[C.RESOURCE_ENERGY] = 0;
lrBuilder.actions.length = 0;
ROLES.builder.run(lrBuilder);
assert(lrBuilder.actions.includes('withdraw') || lrBuilder.actions.includes('moveTo') || lrBuilder.actions.includes('harvest'), '没有 hauler 时 builder 自己去取能');

