makeSpawn(aidWeak, 27, 36);
aidWeak.createConstructionSite(25, 34, C.STRUCTURE_EXTENSION);
Memory.rooms.W34S7 = { sources: ['aw0', 'aw1'], plan: { containers: { src0: { x: 11, y: 10 }, src1: { x: 39, y: 40 }, ctrl: { x: 21, y: 31 } } }, state: { at: Game.time, recovering: false } };
world.creeps.awH0 = makeCreep(aidWeak, 'awH0', ['work', 'work', 'move'], { home: 'W34S7', role: 'harvester', sourceIdx: 0, sourceId: 'aw0', staticMiner: true });
world.creeps.awHa = makeCreep(aidWeak, 'awHa', ['carry', 'carry', 'move'], { home: 'W34S7', role: 'hauler' });
Memory.brain = { version: 1, issuedAt: Date.now() + 3, ttlMs: 1800000, intel: {}, rooms: { W33S7: { remotes: ['W32S7'], scouts: 0, claim: null } } };
require('brain').run();
const aidMod = require('aid');
