assert(aidDemands.length === 4 && aidDemands[0].slot === 'aid:harvester:W34S7:0' && aidDemands[1].slot === 'aid:harvester:W34S7:1' &&
    aidDemands[2].role === 'hauler' && aidDemands[3].role === 'builder',
    '弱房两个源都不足 5 WORK、hauler 运力小、有工地 ⇒ 2 矿工 + hauler + builder（得 ' + aidDemands.map((d) => d.slot).join(',') + '）');
assert(aidDemands[0].memory.home === 'W34S7' && aidDemands[0].memory.sourceId === 'aw0' && utils.bodyPartCount(aidDemands[0].body, 'work') === 5,
    '援建矿工 home=弱房、绑定源、5 WORK（得 ' + JSON.stringify({ home: aidDemands[0].memory.home, work: utils.bodyPartCount(aidDemands[0].body, 'work') }) + '）');
spawnMgr.run(aidHome);
const aidSpawned = Object.values(world.creeps).filter((c) => !c.name.startsWith('ai') && !c.name.startsWith('aw'));
assert(aidSpawned.length === 1 && aidSpawned[0].memory.home === 'W34S7' && aidSpawned[0].memory.role === 'harvester' && aidSpawned[0].memory.slotKey === 'aid:harvester:W34S7:0',
    '母房编制齐时先孵援建矿工（home=W34S7），排在外矿 W32S7 之前（得 ' + aidSpawned.map((c) => c.memory.role + '@' + c.memory.home).join(',') + '）');
aidSpawned[0].room = aidWeak;
aidSpawned[0].pos = new RoomPosition(11, 10, 'W34S7');
const aidDemands2 = aidMod.getDemands(aidHome);
assert(!aidDemands2.some((d) => d.slot === 'aid:harvester:W34S7:0'), '源 0 已有 5 WORK 后不再要援建矿工');
{
    const cfgAid = require('../src/config').aid;
    const lv = utils.aidExportLevels(cfgAid, require('../src/config').upgrading);
    const aidStore = makeStructure(aidHome, C.STRUCTURE_STORAGE, 24, 21, { id: 'aidStore', capacity: 1000000, energy: 80000 });
    const withCourier = aidMod.getDemands(aidHome);
    assert(withCourier.some((d) => d.role === 'courier'),
        'storage 8 万（远高于导出线 ' + lv.above + '）⇒ 出 courier（得 ' + withCourier.map((d) => d.role).join(',') + '）');
    aidStore.store[C.RESOURCE_ENERGY] = lv.above - 1;
    assert(!aidMod.getDemands(aidHome).some((d) => d.role === 'courier'),
        '低于导出线时不派 courier（storage ' + (lv.above - 1) + '）');
    aidStore.store[C.RESOURCE_ENERGY] = 80000;
    aidHome._structs.splice(aidHome._structs.indexOf(aidStore), 1);
}
aidWeak.energyCapacityAvailable = 1300;
assert(aidMod.getDemands(aidHome).length === 0, '弱房容量到 untilCapacity 1300 后停止援建');
aidWeak.energyCapacityAvailable = 400;
aidWeak.storage = { my: true, store: mkStore(12000, 1000000), structureType: C.STRUCTURE_STORAGE, pos: new RoomPosition(30, 30, 'W34S7') };
assert(aidMod.getDemands(aidHome).length === 0, '弱房 storage 已有 ≥ storageBelow 的能量时不援建');
delete aidWeak.storage;
assert(aidMod.linearDistance('W33S7', 'W34S7') === 1 && aidMod.linearDistance('W33S7', 'W36S9') === 3, '房间距离按坐标算');
{
    const movementMod = require('movement');
    const savedMap = Game.map;
    Game.map = Object.assign({}, savedMap, { findRoute: (from, to, opts) => {
        const via = opts && typeof opts.routeCallback === 'function' ? opts.routeCallback('W34S8', from) : 1;
        return via === Infinity ? -2 : [{ exit: 5, room: 'W34S8' }, { exit: 1, room: to }];
    } });
    Memory.map.W34S8 = { class: 'sk', lairs: 3, at: Game.time };
    movementMod.resetSafeRoutes();
    world.time += 1;
    const blocked = aidMod.getDemands(aidHome);
    assert(blocked.length === 0 && Memory.rooms.W33S7.aidNoRoute && Memory.rooms.W33S7.aidNoRoute.room === 'W34S7',
        '母房到弱房只能穿 SK 房 ⇒ 不援、记 aidNoRoute（得 ' + blocked.map((d) => d.slot).join(',') + ' / ' + JSON.stringify(Memory.rooms.W33S7.aidNoRoute) + '）');
    const stranded = makeCreep(aidHome, 'aiStranded', utils.makeBody('hauler', 800), { home: 'W34S7', role: 'hauler', aid: 'W33S7' });
    const local = makeCreep(aidHome, 'aiLocal', utils.makeBody('hauler', 800), { home: 'W33S7', role: 'hauler' });
    assert(aidMod.markStranded(stranded) === true && stranded.memory.bodyUpgradeRetiring === true &&
        Memory.rooms.W34S7.aidStranded && Memory.rooms.W34S7.aidStranded.name === 'aiStranded' && Memory.rooms.W34S7.aidStranded.from === 'W33S7',
        '回不了弱房的援建 creep 标记退役并记 aidStranded（得 ' + JSON.stringify(Memory.rooms.W34S7.aidStranded) + '）');
    assert(aidMod.markStranded(stranded) === false, '已在退役的不重复标记');
    assert(aidMod.markStranded(local) === false && !local.memory.bodyUpgradeRetiring, '不是援建 creep 不碰');
    const arrived = makeCreep(aidWeak, 'aiArrived', utils.makeBody('hauler', 800), { home: aidWeak.name, role: 'hauler', aid: aidHome.name });
    assert(aidMod.markStranded(arrived) === false && !utils.isRetiring(arrived.memory), '已到弱房的援建 creep 不因母房路线阻断而退役');
    {
        const throwing = Game.map;
        Game.map = Object.assign({}, savedMap, { findRoute: () => { throw new Error('map down'); } });
        movementMod.resetSafeRoutes();
        const errorsBefore = (Memory.errors || []).length;
        const probe = makeCreep(aidHome, 'aiProbe', utils.makeBody('hauler', 800), { home: 'W34S7', role: 'hauler', aid: 'W33S7' });
        assert(aidMod.needsAid(aidHome, aidWeak) === true && aidMod.markStranded(probe) === false && !probe.memory.bodyUpgradeRetiring &&
            (Memory.errors || []).length > errorsBefore, 'findRoute 抛错时援建放行、不退役、记错误');
        Memory.errors.length = errorsBefore;
        Game.map = throwing;
        movementMod.resetSafeRoutes();
    }
    const strandedMiner = makeCreep(aidHome, 'aiStrandedMiner', utils.makeBody('staticHarvester', 800), {
        home: aidWeak.name, role: 'harvester', aid: aidHome.name, staticMiner: true,
        sourceId: 'aw1', sourceIdx: 1, slotKey: 'aid:harvester:W34S7:1',
    });
    strandedMiner.id = 'aid-stranded-miner-id';
    strandedMiner.pos = new RoomPosition(22, 21, aidHome.name);
    world.creeps[strandedMiner.name] = strandedMiner;
    Memory.creeps[strandedMiner.name] = strandedMiner.memory;
    const minerDemand = { role: 'harvester', slot: strandedMiner.memory.slotKey, memory: strandedMiner.memory, lead: 200 };
    world.time += 1;
    assert(spawnMgr.countPlannedDemand(aidHome, minerDemand) === 1, '未标退役的搁浅矿工仍占援建槽位');
    const readyBeforeRetirement = spawnMgr.countReadyRole(aidWeak, 'harvester');
    main.loop();
    assert(strandedMiner.memory.bodyUpgradeRetiring === true && strandedMiner.actions.includes('recycled') &&
        aidHome.find(C.FIND_MY_SPAWNS).some((spawn) => spawn.actions.some((action) => action.action === 'recycleCreep' && action.target === strandedMiner.name)),
        '主循环把无路援建矿工交给 retireReplaced，并向相邻 spawn 发出回收意图（得 ' + strandedMiner.actions.join(',') + '）');
    assert(!strandedMiner.actions.includes('harvest'), '回收接管后该 tick 不再派矿工采集动作');
    assert(spawnMgr.countPlannedDemand(aidHome, minerDemand) === 0 &&
        spawnMgr.countReadyRole(aidWeak, 'harvester') === readyBeforeRetirement - 1,
        '回收尚未结算时已释放援建槽位与 spawn 就绪矿工计数');
    assert((Memory.errors || []).length === 0, '援建退役主循环无异常: ' + JSON.stringify(Memory.errors || []));
    const reachableDonor = makeRoom('W35S7', { rcl: 4, energy: 1100, cap: 1100, owner: 'me', ctrl: { x: 20, y: 30 } });
    makeSpawn(reachableDonor, 23, 21);
    const blockedMap = Game.map;
    Game.map = Object.assign({}, blockedMap, { findRoute: (from, to, options) => from === reachableDonor.name
        ? [{ exit: 7, room: to }] : blockedMap.findRoute(from, to, options) });
    movementMod.resetSafeRoutes();
    assert(aidMod.getDemands(reachableDonor).some((item) => item.role === 'harvester' && item.memory.home === aidWeak.name && item.memory.sourceId === 'aw1'),
        '其它可达母房不再被退役矿工的 WORK 占位，可以接手该源援助');
    delete world.rooms[reachableDonor.name];
    delete world.creeps[strandedMiner.name];
    delete Memory.creeps[strandedMiner.name];
    Game.map = blockedMap;
    delete Memory.map.W34S8;
    world.time += 1;
    const walker = makeCreep(aidHome, 'aiWalker', utils.makeBody('hauler', 800), { home: 'W34S7', role: 'hauler', aid: 'W33S7' });
    assert(aidMod.markStranded(walker) === false && !walker.memory.bodyUpgradeRetiring, '危险房清掉后在途援建 creep 不退役（缓存随危险房集合失效）');
    const reopened = aidMod.getDemands(aidHome);
    assert(reopened.length > 0, '危险房清掉、路线恢复后照常援建（得 ' + reopened.length + '）');
    let routeCalls = 0;
    Game.map = Object.assign({}, savedMap, { findRoute: () => { routeCalls++; return []; } });
    movementMod.resetSafeRoutes();
    movementMod.safeRouteExists('W33S7', 'W34S7', 1000);
    world.time += 999;
    movementMod.safeRouteExists('W33S7', 'W34S7', 1000);
    const cachedCalls = routeCalls;
    world.time += 1;
    movementMod.safeRouteExists('W33S7', 'W34S7', 1000);
    assert(cachedCalls === 1 && routeCalls === 2, '安全路线结果缓存 routeCacheTicks，过期才重算（得 ' + cachedCalls + '/' + routeCalls + '）');
    movementMod.resetSafeRoutes();
    Game.map = savedMap;
}
delete Memory.brain;

