console.log('== creep 取名：每个 role 都登记了东方人物名，同 role 的多只靠前缀/后缀区分且永不撞名 ==');
{
    Memory.creeps = {};
    for (const name of Object.keys(world.creeps)) delete world.creeps[name];
    global.Game.creeps = world.creeps;
    const bases = {};
    for (const role of Object.keys(ROLES)) bases[role] = utils.creepName(role);
    const unnamed = Object.keys(bases).filter((role) => bases[role].includes('妖精'));
    assert(unnamed.length === 0, 'main.js 的 ROLES 全部登记了人物名（未登记的会落到妖精：' + (unnamed.join(',') || '无') + '）');
    assert(new Set(Object.values(bases)).size === Object.keys(bases).length, Object.keys(bases).length + ' 个角色的本名两两不同');

    const issued = [];
    const collided = [];
    for (const role of Object.keys(ROLES)) {
        for (let i = 0; i < 12; i++) {
            const name = utils.creepName(role, i === 3 ? 'upgrade' : undefined);
            if (Memory.creeps[name]) collided.push(name);
            Memory.creeps[name] = { role };
            issued.push({ role, name });
        }
    }
    assert(collided.length === 0 && new Set(issued.map((c) => c.name)).size === issued.length,
        Object.keys(ROLES).length + ' 角色 × 12 只 = ' + issued.length + ' 只同 tick 连发全部唯一（撞名: ' + (collided.join(',') || '无') + '）');
    assert(issued.every((c) => c.name.split('.')[0].includes(bases[c.role])),
        '每只的名字都含本角色的人物名，看名字就能认出 role');
    assert(issued.filter((c) => c.name.endsWith('.upgrade')).length === Object.keys(ROLES).length,
        'tag 仍作后缀保留（换代/弹性/应急孵化路径靠它区分）');

    const victim = issued[0].name;
    delete Memory.creeps[victim];
    assert(utils.creepName(issued[0].role) === victim, '死掉的 ' + victim + ' 被下一只顶回同一个名字');
    Memory.creeps = {};
    for (const name of Object.keys(world.creeps)) delete world.creeps[name];
}

