console.log('== 外矿队列头一条买不起时跳到后面买得起的一条；一次性的战略需求（pioneer）买不起仍等它 ==');
resetWorld(7350);
const skHome = makeRoom('W33S7', { rcl: 5, energy: 800, cap: 1800, ctrl: { x: 22, y: 31 }, owner: 'me' });
skHome._sources = [makeSource(skHome, 14, 6, 'sk0'), makeSource(skHome, 31, 12, 'sk1')];
makeSpawn(skHome, 23, 21);
makeStructure(skHome, C.STRUCTURE_CONTAINER, 15, 6, { capacity: 2000, energy: 300 });
makeStructure(skHome, C.STRUCTURE_CONTAINER, 32, 13, { capacity: 2000, energy: 300 });
makeStructure(skHome, C.STRUCTURE_CONTAINER, 22, 30, { capacity: 2000, energy: 300 });
Memory.rooms.W33S7 = { sources: ['sk0', 'sk1'], plan: { containers: { src0: { x: 15, y: 6 }, src1: { x: 32, y: 13 }, ctrl: { x: 22, y: 30 } } },
    state: { at: Game.time, recovering: false, emergencyHarvest: false }, remotes: {
        W33S6: { room: 'W33S6', enabled: true, sourceCount: 1, controllerDistance: 59, suspendedUntil: 0,
            reservation: { username: null, ticksToEnd: 0, seenAt: Game.time }, sources: [] },
        W32S7: { room: 'W32S7', enabled: true, sourceCount: 1, controllerDistance: 50, suspendedUntil: 0,
            reservation: { username: 'me', ticksToEnd: 3000, seenAt: Game.time },
            sources: [{ id: 'sks0', pos: { x: 16, y: 13 }, spot: { x: 15, y: 12 }, distance: 48, energyCapacity: 3000, road: '', roadComplete: true, containerId: null }] },
    } };
Memory.map = {};
['sk0', 'sk1'].forEach((id, index) => { world.creeps['skH' + index] = makeCreep(skHome, 'skH' + index, utils.makeBody('staticHarvester', 1800), { home: 'W33S7', role: 'harvester', sourceIdx: index, sourceId: id, staticMiner: true }); });
for (let i = 0; i < 5; i++) world.creeps['skHa' + i] = makeCreep(skHome, 'skHa' + i, utils.makeBody('hauler', 1800), { home: 'W33S7', role: 'hauler' });
for (let i = 0; i < 2; i++) world.creeps['skUp' + i] = makeCreep(skHome, 'skUp' + i, utils.makeBody('upgrader', 1800), { home: 'W33S7', role: 'upgrader' });
for (let i = 0; i < 2; i++) world.creeps['skBu' + i] = makeCreep(skHome, 'skBu' + i, utils.makeBody('builder', 1800), { home: 'W33S7', role: 'builder' });
Memory.brain = { version: 1, issuedAt: Date.now(), ttlMs: 1800000, intel: {}, rooms: { W33S7: { remotes: ['W33S6', 'W32S7'], scouts: 0, claim: null } } };
require('brain').run();
const skSavedAssign = config.remote.assign;
config.remote.assign = Object.assign({}, skSavedAssign, { W33S7: ['W33S6', 'W32S7'] });
const skDemands = remoteMod.getDemands(skHome);
assert(skDemands.length === 2 && skDemands[0].slot === 'reserver:W33S6' && utils.bodyCost(skDemands[0].body) === 1300 &&
    skDemands[1].role === 'remoteMiner' && utils.bodyCost(skDemands[1].body) <= 800,
    '前提：队列 = [W33S6 reserver 1300, W32S7 miner ≤800]（得 ' + skDemands.map((d) => d.slot + '@' + utils.bodyCost(d.body)).join(',') + '）');
spawnMgr.run(skHome);
const skNew = Object.values(world.creeps).filter((c) => !c.name.startsWith('sk'));
assert(skNew.length === 1 && skNew[0].memory.role === 'remoteMiner' && skNew[0].memory.remoteRoom === 'W32S7',
    '头一条 reserver 买不起 ⇒ 跳过去孵 W32S7 的 miner（得 ' + skNew.map((c) => c.memory.role + ':' + c.memory.remoteRoom).join(',') + '）');
assert(Memory.rooms.W33S7.spawnWaiting && Memory.rooms.W33S7.spawnWaiting.cost === 1300, '被跳过的 1300 仍记入 spawnWaiting，让 hauler 优先喂 spawn（得 ' + JSON.stringify(Memory.rooms.W33S7.spawnWaiting) + '）');
world.time++;
skHome.energyAvailable = 700;
Game.gcl = { level: 5, progress: 0, progressTotal: 1 };
const skNewRoom = makeRoom('W34S7', { rcl: 1, my: true, ctrl: { x: 31, y: 41 } });
skNewRoom._sources = [makeSource(skNewRoom, 19, 19, 'skn0')];
Memory.rooms.W33S7.expansion = { target: 'W34S7', spawnPos: { x: 24, y: 36 }, since: Game.time };
Memory.rooms.W33S7.remotes.W32S7.sources.push({ id: 'sks1', pos: { x: 30, y: 30 }, spot: { x: 31, y: 30 }, distance: 50, energyCapacity: 3000, road: '', roadComplete: true, containerId: null });
const skPioneer = require('expansion').getDemands(skHome)[0];
const skMinerCost = utils.bodyCost(remoteMod.remoteMinerBody(1800));
assert(skPioneer && skPioneer.role === 'pioneer' && utils.bodyCost(skPioneer.body) > 700 && skMinerCost <= 700,
    '前提：pioneer 买不起（>700）而第二个 miner 买得起（得 pioneer ' + (skPioneer && utils.bodyCost(skPioneer.body)) + ' miner ' + skMinerCost + '）');
spawnMgr.run(skHome);
const skNew2 = Object.values(world.creeps).filter((c) => !c.name.startsWith('sk') && c.memory.role !== 'remoteMiner' || (c.memory.role === 'remoteMiner' && c.memory.sourceId === 'sks1'));
assert(skNew2.length === 0, 'pioneer 在队头买不起 ⇒ 不跳过它去孵 miner（得 ' + skNew2.map((c) => c.memory.role).join(',') + '）');
assert(Memory.rooms.W33S7.spawnWaiting && Memory.rooms.W33S7.spawnWaiting.cost === utils.bodyCost(skPioneer.body), 'spawnWaiting 记的是 pioneer 的成本');
config.remote.assign = skSavedAssign;
delete Memory.brain;

console.log('== upgrader 站位：storage 建成后站到 storage 相邻格直接取能，hauler 不再喂控制器容器（向 Kalgen 学：升级者静止在 storage 旁）==');
{
    const ssRoom = demoRoom(6100, 5);
    const ssPlan = Memory.rooms.W33S7.plan;
    makeSpawn(ssRoom, 23, 21);
    const ssCtrlCont = makeStructure(ssRoom, C.STRUCTURE_CONTAINER, ssPlan.containers.ctrl.x, ssPlan.containers.ctrl.y, { my: false, energy: 0, capacity: 2000 });
    assert(layout.upgraderStorageStations(ssRoom, ssPlan).length === 0 && !layout.controllerFedByStorage(ssRoom, ssPlan), 'storage 未建成时没有 storage 站位');
    const ssStorage = makeStructure(ssRoom, C.STRUCTURE_STORAGE, ssPlan.storage.x, ssPlan.storage.y, { energy: 5000, capacity: 1000000 });
    world.time++;
    const ssSpots = layout.upgraderStorageStations(ssRoom, ssPlan);
    assert(ssSpots.length >= 2 && ssSpots.every((s) => Math.max(Math.abs(s.x - ssPlan.storage.x), Math.abs(s.y - ssPlan.storage.y)) === 1 &&
        Math.max(Math.abs(s.x - 34), Math.abs(s.y - 24)) <= 3),
        'storage 站位都与 storage 相邻且在控制器射程 3 内（得 ' + JSON.stringify(ssSpots.map((s) => [s.x, s.y])) + '）');
    assert(ssSpots[0].x === 32 && ssSpots[0].y === 26, 'W33S7 首选站位 (32,26)：贴 store link、离控制器 2 格（得 ' + ssSpots[0].x + ',' + ssSpots[0].y + '）');
    assert(!ssSpots.some((s) => (s.x === ssPlan.terminal.x && s.y === ssPlan.terminal.y) || (s.x === ssPlan.links.store.x && s.y === ssPlan.links.store.y)),
        'terminal 位与 store link 位不是站位');
    assert(layout.controllerFedByStorage(ssRoom, ssPlan) === true, '有 storage 站位 ⇒ 升级者由 storage 供能');
    const ssUp1 = makeCreep(ssRoom, 'up.ss1', utils.makeBody('upgrader', 1800), { home: 'W33S7', role: 'upgrader' });
    world.creeps[ssUp1.name] = ssUp1;
    ssUp1.pos = new RoomPosition(23, 22, 'W33S7');
    ssUp1.store[RESOURCE_ENERGY] = 100;
    ROLES.upgrader.run(ssUp1);
    assert(ssUp1.moveCalls.some((m) => m.target && m.target.x === 32 && m.target.y === 26) && !ssUp1.actions.includes('upgradeController'),
        '带能量的 upgrader 先走向 storage 站位 (32,26)（得 ' + JSON.stringify(ssUp1.moveCalls.map((m) => m.target && [m.target.x, m.target.y])) + '）');
    ssUp1.pos = new RoomPosition(32, 26, 'W33S7');
    ssUp1.store[RESOURCE_ENERGY] = 10;
    ssUp1.moveCalls.length = 0;
    ssUp1.actions.length = 0;
    world.time++;
    ROLES.upgrader.run(ssUp1);
    assert(ssUp1.actions.includes('upgradeController') && ssUp1.actions.includes('withdraw') && ssStorage.store[C.RESOURCE_ENERGY] < 5000 && ssUp1.moveCalls.length === 0,
        'storage 站位上的 upgrader 同 tick 从 storage 取能并升级，不移动（storage=' + ssStorage.store[C.RESOURCE_ENERGY] + ' 动作 ' + ssUp1.actions.join(',') + '）');
    ssUp1.store[RESOURCE_ENERGY] = 0;
    ssUp1.actions.length = 0;
    world.time++;
    ROLES.upgrader.run(ssUp1);
    assert(ssUp1.actions.includes('withdraw') && ssUp1.moveCalls.length === 0, '空仓 upgrader 就地从 storage 取能');
    const ssUp2 = makeCreep(ssRoom, 'up.ss2', utils.makeBody('upgrader', 1800), { home: 'W33S7', role: 'upgrader' });
    world.creeps[ssUp2.name] = ssUp2;
    ssUp2.pos = new RoomPosition(23, 22, 'W33S7');
    ssUp2.store[RESOURCE_ENERGY] = 100;
    world.time++;
    ROLES.upgrader.run(ssUp2);
    const ssMove2 = ssUp2.moveCalls.find((m) => m.target && m.target.x != null);
    assert(ssMove2 && !(ssMove2.target.x === 32 && ssMove2.target.y === 26) && ssSpots.some((s) => s.x === ssMove2.target.x && s.y === ssMove2.target.y),
        '第二个 upgrader 走向下一个空闲的 storage 站位（得 ' + JSON.stringify(ssMove2 && [ssMove2.target.x, ssMove2.target.y]) + '）');
    ssStorage.store[C.RESOURCE_ENERGY] = 1000;
    world.time += 3;
    let ssTasks = taskBroker.roomTasks(ssRoom);
    assert(!ssTasks.some((t) => t.kind === 'deliver' && t.id === ssCtrlCont.id), 'storage 供能时控制器容器不再是投递目标');
    let ssFeed = ssTasks.find((t) => t.kind === 'deliver' && t.id === ssStorage.id + ':ctrlFeed');
    assert(ssFeed && ssFeed.tier === 3 && ssFeed.weight === 4 && ssFeed.backlog === 2000 && ssFeed.target === ssStorage,
        'storage 1000 < 地板线 3000（reserve 2000 + band 1000）：第三层补 storage，backlog 补到地板（得 ' + JSON.stringify(ssFeed && { tier: ssFeed.tier, w: ssFeed.weight, b: ssFeed.backlog }) + '）');
    ssStorage.store[C.RESOURCE_ENERGY] = 100;
    world.time += 3;
    ssFeed = taskBroker.roomTasks(ssRoom).find((t) => t.kind === 'deliver' && t.id === ssStorage.id + ':ctrlFeed');
    assert(ssFeed && ssFeed.tier === 1 && ssFeed.weight === 20, 'storage 见底且 spawn 能量过半：先送 storage（公平规则）（得 ' + JSON.stringify(ssFeed && { tier: ssFeed.tier, w: ssFeed.weight }) + '）');
    Memory.rooms.W33S7.spawnWaiting = { cost: 1800, at: Game.time };
    world.time += 3;
    ssFeed = taskBroker.roomTasks(ssRoom).find((t) => t.kind === 'deliver' && t.id === ssStorage.id + ':ctrlFeed');
    assert(ssFeed && ssFeed.tier === 3, 'spawn 等能量时 storage 不提到第一层（得 ' + JSON.stringify(ssFeed && { tier: ssFeed.tier }) + '）');
    Memory.rooms.W33S7.spawnWaiting = null;
    ssStorage.store[C.RESOURCE_ENERGY] = 30000;
    world.time += 3;
    assert(!taskBroker.roomTasks(ssRoom).some((t) => t.id === ssStorage.id + ':ctrlFeed'), 'storage 高于地板线时没有补 storage 的控制器供能任务');
    ssStorage.store[C.RESOURCE_ENERGY] = 100;
    ssRoom.find(C.FIND_MY_STRUCTURES).forEach((st) => { if (st.store && (st.structureType === C.STRUCTURE_SPAWN || st.structureType === C.STRUCTURE_EXTENSION)) st.store[C.RESOURCE_ENERGY] = st.store.getCapacity(C.RESOURCE_ENERGY); });
    const ssRh = makeCreep(ssRoom, 'rh.ss', ['carry', 'carry', 'move'], { home: 'W33S7', role: 'remoteHauler', remoteRoom: 'W32S7' });
    world.creeps[ssRh.name] = ssRh;
    ssRh.pos = new RoomPosition(31, 25, 'W33S7');
    ssRh.store[RESOURCE_ENERGY] = 100;
    world.time++;
    ROLES.remoteHauler.run(ssRh);
    assert(ssRh.actions.includes('transfer') && ssStorage.store[C.RESOURCE_ENERGY] === 200 && ssCtrlCont.store[C.RESOURCE_ENERGY] === 0,
        'remoteHauler 回家把能量交给见底的 storage，不进控制器容器（storage=' + ssStorage.store[C.RESOURCE_ENERGY] + ' ctrl=' + ssCtrlCont.store[C.RESOURCE_ENERGY] + '）');
    delete world.creeps[ssUp1.name];
    delete world.creeps[ssUp2.name];
    delete world.creeps[ssRh.name];
    ssRoom._sources.forEach((src, i) => { world.creeps['ssh' + i] = makeCreep(ssRoom, 'ssh' + i, utils.makeBody('staticHarvester', 1800), { home: 'W33S7', role: 'harvester', sourceIdx: i, sourceId: src.id, staticMiner: true }); });
    ssStorage.store[C.RESOURCE_ENERGY] = 30000;
    delete Memory.rooms.W33S7.upgradeSupply;
    world.time++;
    spawnMgr.run(ssRoom);
    const ssHaulerFed = Memory.rooms.W33S7.demand.targets.hauler;
    assert(Memory.rooms.W33S7.demand.targets.upgrader === 2, 'storage 3 万且房间能量满：EMA 立刻加到 RCL5 上限 2 个 upgrader（得 ' + Memory.rooms.W33S7.demand.targets.upgrader + '）');
    ssStorage.store[C.RESOURCE_ENERGY] = 500;
    const ssInterval = require('../src/config').upgrading.changeInterval;
    require('../src/config').upgrading.changeInterval = 20;
    for (let i = 0; i < 120; i++) { world.time++; spawnMgr.run(ssRoom); }
    require('../src/config').upgrading.changeInterval = ssInterval;
    assert(Memory.rooms.W33S7.demand.targets.upgrader === 1, 'storage 掉到 500 后 EMA 回落，upgrader 目标回到底线 1（得 ' + Memory.rooms.W33S7.demand.targets.upgrader + ' ema=' + JSON.stringify(Memory.rooms.W33S7.upgradeSupply) + '）');
    ssRoom.energyCapacityAvailable = 800;
    ssRoom.energyAvailable = 800;
    world.time++;
    spawnMgr.run(ssRoom);
    const ssHaulerFedSmall = Memory.rooms.W33S7.demand.targets.hauler;
    delete ssRoom.storage;
    ssRoom._structs.splice(ssRoom._structs.indexOf(ssStorage), 1);
    const ssFarStorage = makeStructure(ssRoom, C.STRUCTURE_STORAGE, 21, 20, { energy: 30000, capacity: 1000000 });
    world.time++;
    assert(!layout.controllerFedByStorage(ssRoom, ssPlan), 'storage 离控制器 >3 格时没有 storage 站位');
    assert(taskBroker.roomTasks(ssRoom).some((t) => t.kind === 'deliver' && t.id === ssCtrlCont.id), '没有站位时控制器容器照旧登记投递');
    spawnMgr.run(ssRoom);
    assert(Memory.rooms.W33S7.demand.targets.hauler > ssHaulerFedSmall,
        'storage 供能时 hauler 往返不算控制器段：目标 ' + ssHaulerFedSmall + ' < 容器供能时的 ' + Memory.rooms.W33S7.demand.targets.hauler + '（1300 容量时 ' + ssHaulerFed + '）');
    void ssFarStorage;
}

console.log('== storage 供能房的补给地板必须高出升级者取用底线：两者相等时可取量恒为 0，升级速率归零 ==');
{
    const cfg = require('../src/config');
    const reserve = cfg.upgrading.reserve;
    const band = cfg.controllerFeedStorageBand;
    assert(band > 0, '前提：配置了工作带 controllerFeedStorageBand（得 ' + band + '）');
    const bandRoom = demoRoom(6600, 5);
    const bandPlan = Memory.rooms.W33S7.plan;
    makeSpawn(bandRoom, 23, 21);
    const bandStorage = makeStructure(bandRoom, C.STRUCTURE_STORAGE, bandPlan.storage.x, bandPlan.storage.y, { energy: 0, capacity: 1000000 });
    world.time++;
    assert(layout.controllerFedByStorage(bandRoom, bandPlan) === true, '前提：这是 storage 供能的房');
    bandStorage.store[C.RESOURCE_ENERGY] = reserve;
    world.time += 3;
    const bandFeed = taskBroker.roomTasks(bandRoom).find((t) => t.id === bandStorage.id + ':ctrlFeed');
    assert(bandFeed && bandFeed.tier === 3 && bandFeed.backlog === band,
        'storage 恰在 reserve ' + reserve + ' 上时仍按第三层补，backlog 正好一个工作带 ' + band + '（得 ' + JSON.stringify(bandFeed && { tier: bandFeed.tier, b: bandFeed.backlog }) + '）');
    assert(taskBroker.controllerFeedStorage(bandRoom) !== null, 'controllerFeedStorage 与 roomTasks 判定一致');
    assert(Memory.rooms.W33S7.ctrlFeedBand && Memory.rooms.W33S7.ctrlFeedBand.n > 0 && Memory.rooms.W33S7.ctrlFeedBand.floor === reserve + band,
        '工作带里的补给决策记进 ctrlFeedBand（私服生效断言看它，不看末态快照）（得 ' + JSON.stringify(Memory.rooms.W33S7.ctrlFeedBand) + '）');
    delete Memory.rooms.W33S7.ctrlFeedBand;
    bandStorage.store[C.RESOURCE_ENERGY] = reserve - 1;
    world.time += 3;
    taskBroker.roomTasks(bandRoom);
    assert(!Memory.rooms.W33S7.ctrlFeedBand, 'storage 在取用底线以下时不记 ctrlFeedBand：旧代码也会补这一段，不能用来区分新旧');
    bandStorage.store[C.RESOURCE_ENERGY] = reserve + band;
    world.time += 3;
    assert(!taskBroker.roomTasks(bandRoom).some((t) => t.id === bandStorage.id + ':ctrlFeed'),
        'storage 达到 reserve + band = ' + (reserve + band) + ' 后不再按控制器供能补');
    bandStorage.store[C.RESOURCE_ENERGY] = reserve + band;
    const bandUp = makeCreep(bandRoom, 'up.band', utils.makeBody('upgrader', 1800), { home: 'W33S7', role: 'upgrader' });
    world.creeps[bandUp.name] = bandUp;
    bandUp.pos = new RoomPosition(bandPlan.storage.x, bandPlan.storage.y + 1, 'W33S7');
    bandUp.store[RESOURCE_ENERGY] = 0;
    world.time++;
    ROLES.upgrader.run(bandUp);
    assert(bandUp.store[RESOURCE_ENERGY] > 0 && bandStorage.store[C.RESOURCE_ENERGY] < reserve + band,
        '补给收敛点上升级者取得到能量（取了 ' + bandUp.store[RESOURCE_ENERGY] + '，storage 剩 ' + bandStorage.store[C.RESOURCE_ENERGY] + '）');
    bandStorage.store[C.RESOURCE_ENERGY] = reserve;
    bandUp.store[RESOURCE_ENERGY] = 0;
    bandUp.actions.length = 0;
    world.time++;
    ROLES.upgrader.run(bandUp);
    assert(bandUp.store[RESOURCE_ENERGY] === 0 && bandStorage.store[C.RESOURCE_ENERGY] === reserve,
        '反例：storage 恰在 reserve 上时升级者取不到任何能量——所以补给地板不能停在这里');
    delete world.creeps[bandUp.name];
}

