Memory.creeps['dead-def-2'] = { role: 'defender', home: 'W33S7', targetRoom: 'W33S6' };
fmRemote._hostiles.length = 0;
try { main.loop(); } catch (e) { fails++; console.log('  ✗ loop throw: ' + e.stack.split('\n').slice(0, 3).join(' | ')); }
