const fmOwn = makeRoom('W33S7', { rcl: 4, energy: 1300, cap: 1300, ctrl: { x: 22, y: 31 }, owner: 'me' });
fmOwn._sources = [makeSource(fmOwn, 14, 6, 'fo0')];
makeSpawn(fmOwn, 23, 21);
Memory.rooms.W33S7 = { sources: ['fo0'], plan: {}, state: { at: Game.time, recovering: false, emergencyHarvest: false }, remotes: {} };
Memory.map = {};
const fmNew = makeRoom('W34S7', { rcl: 1, my: true, ctrl: { x: 31, y: 41 } });
makeHostile(fmNew, 20, 20, SMALL_MELEE, { owner: 'Invader', hits: 1000 });
