console.log('== defender 成组出发：组没齐在家等，齐了再走；等的时候威胁消失就退役；进目标房后先集结再推进 ==');
resetWorld(11150);
const sqHome = makeRoom('W33S7', { rcl: 5, energy: 1800, cap: 1800, owner: 'me', ctrl: { x: 34, y: 24 } });
makeSpawn(sqHome, 23, 21);
world.exits.W33S7 = { '1': 'W33S6' };
const sqRemote = makeRoom('W33S6', { my: false, rcl: 0, ctrl: { x: 21, y: 12 }, exits: { '5': 'W33S7' } });
makeHostile(sqRemote, 27, 43, SMALL_MELEE, { owner: 'Invader', hits: 1000 });
Memory.rooms.W33S7 = { sources: [], plan: {}, state: { at: Game.time }, remotes: { W33S6: { room: 'W33S6', enabled: true, suspendedUntil: Game.time + 150, suspendReason: 'hostileCreep', sources: [] } } };
Memory.map = {};
const sqBody = ['move', 'move', 'move', 'ranged_attack', 'ranged_attack', 'heal'];
const sqA = makeCreep(sqHome, 'sq-a', sqBody, { home: 'W33S7', role: 'defender', targetRoom: 'W33S6', style: 'ranged', squad: 2, slotKey: 'defender:W33S6' });
sqA.pos = new RoomPosition(23, 24, 'W33S7');
world.creeps[sqA.name] = sqA;
ROLES.defender.run(sqA);
assert(!sqA.moveCalls.some((m) => m.target && m.target.roomName === 'W33S6') && !sqA.actions.includes('suicide'), '组只有 1/2：在家等，不单独出发');
const sqB = makeCreep(sqHome, 'sq-b', sqBody, { home: 'W33S7', role: 'defender', targetRoom: 'W33S6', style: 'ranged', squad: 2, slotKey: 'defender:W33S6:1' });
sqB.spawning = true;
world.creeps[sqB.name] = sqB;
sqA.moveCalls.length = 0;
ROLES.defender.run(sqA);
assert(!sqA.moveCalls.some((m) => m.target && m.target.roomName === 'W33S6'), '队友还在孵化：继续等');
sqB.spawning = false;
sqB.pos = new RoomPosition(24, 24, 'W33S7');
sqA.moveCalls.length = 0;
ROLES.defender.run(sqA);
assert(sqA.moveCalls.some((m) => m.target && m.target.roomName === 'W33S6'), '组齐了：出发去目标房（得 ' + JSON.stringify(sqA.moveCalls.map((m) => m.target && m.target.roomName)) + '）');
sqA.room = sqRemote; sqA.pos = new RoomPosition(25, 48, 'W33S6');
sqA.moveCalls.length = 0; sqA.actions.length = 0;
ROLES.defender.run(sqA);
assert(!sqA.moveCalls.some((m) => m.target && m.target.roomName === 'W33S6' && m.target.y < 40), '队友没进房：不朝敌人推进（得 ' + JSON.stringify(sqA.moveCalls.map((m) => m.target && [m.target.x, m.target.y])) + '）');
sqB.room = sqRemote; sqB.pos = new RoomPosition(26, 48, 'W33S6');
sqA.moveCalls.length = 0; sqA.actions.length = 0;
ROLES.defender.run(sqA);
assert(sqA.moveCalls.some((m) => m.target && m.target.roomName === 'W33S6'), '队友到齐：向敌人推进');
const sqC = makeCreep(sqHome, 'sq-c', sqBody, { home: 'W33S7', role: 'defender', targetRoom: 'W33S6', style: 'ranged', squad: 2, slotKey: 'defender:W33S6' });
sqC.pos = new RoomPosition(23, 24, 'W33S7');
delete world.creeps['sq-a']; delete world.creeps['sq-b'];
world.creeps[sqC.name] = sqC;
sqRemote._hostiles.length = 0;
Memory.rooms.W33S7.remotes.W33S6.suspendedUntil = 0; Memory.rooms.W33S7.remotes.W33S6.suspendReason = null;
ROLES.defender.run(sqC);
assert(retiring(sqC) && !sqC.actions.includes('suicide') && sqC.memory.retired === true, '组没齐且威胁已消失：在家走向 spawn 回收（retired 标记，不算阵亡）（得 ' + sqC.actions.join(',') + '）');

console.log('== 外矿观察：看到武装敌人就记敌情画像与到期；再看到已清场立刻解除 hostileCreep 停用；reserver 停用时间超过寿命就退役 ==');
resetWorld(11200);
const obHome = makeRoom('W33S7', { rcl: 5, energy: 1800, cap: 1800, owner: 'me', ctrl: { x: 34, y: 24 } });
obHome._sources = [makeSource(obHome, 14, 6, 'ob0')];
makeSpawn(obHome, 23, 21);
world.exits.W33S7 = { '1': 'W33S6' };
const obRemote = makeRoom('W33S6', { my: false, rcl: 0, ctrl: { x: 21, y: 12 }, exits: { '5': 'W33S7' } });
obRemote._sources = [makeSource(obRemote, 30, 45, 'ob6')];
Memory.rooms.W33S7 = { sources: ['ob0'], plan: {}, state: { at: Game.time }, remotes: { W33S6: { room: 'W33S6', enabled: true, sourceCount: 1, suspendedUntil: 0, suspendReason: null, sources: [] } } };
Memory.map = {};
const obInv = makeHostile(obRemote, 27, 43, SMALL_RANGED, { owner: 'Invader', hits: 1000 });
obInv.ticksToLive = 900;
remoteMod.observe(obHome, obRemote);
const obRec = Memory.rooms.W33S7.remotes.W33S6;
assert(obRec.suspendReason === 'hostileCreep' && obRec.threat && obRec.threat.count === 1 && obRec.threat.kiters === true && obRec.threat.until === Game.time + 900,
    '看到武装敌人：停用 + 敌情画像（风筝型、到期 +900）（得 ' + JSON.stringify(obRec.threat) + '）');
obRemote._hostiles.length = 0; world.time++;
remoteMod.observe(obHome, obRemote);
assert(obRec.suspendedUntil === 0 && !obRec.suspendReason && !obRec.threat, '再看到已清场：立刻解除停用、清画像，不必等 150 tick 冷却（得 ' + JSON.stringify([obRec.suspendedUntil, obRec.suspendReason, obRec.threat]) + '）');
obRec.suspendedUntil = Game.time + 1000; obRec.suspendReason = 'hostileCreep';
const obRes = makeCreep(obHome, 'ob-res', ['claim', 'claim', 'move', 'move'], { home: 'W33S7', role: 'reserver', remoteRoom: 'W33S6' }, { ticksToLive: 300 });
obRes.pos = new RoomPosition(22, 17, 'W33S7');
world.creeps[obRes.name] = obRes;
ROLES.reserver.run(obRes);
assert(retiring(obRes) && !obRes.actions.includes('suicide'), '停用还剩 1000 tick、reserver 只剩 300：在家走向 spawn 回收而不是站着挂机（得 ' + obRes.actions.join(',') + '）');
const obRes2 = makeCreep(obHome, 'ob-res2', ['claim', 'claim', 'move', 'move'], { home: 'W33S7', role: 'reserver', remoteRoom: 'W33S6' }, { ticksToLive: 1400 });
obRes2.pos = new RoomPosition(22, 17, 'W33S7');
world.creeps[obRes2.name] = obRes2;
ROLES.reserver.run(obRes2);
assert(!retiring(obRes2), '寿命够等到停用结束：不退役');

console.log('== 外部大脑的防御指令与敌情画像：avoid 就停到入侵者到期、fight 按指令编组；没视野时用情报里的 hostileProfile ==');
resetWorld(11300);
const bdHome = makeRoom('W33S7', { rcl: 5, energy: 1800, cap: 1800, owner: 'me', ctrl: { x: 34, y: 24 } });
bdHome._sources = [makeSource(bdHome, 14, 6, 'bd0')];
makeSpawn(bdHome, 23, 21);
world.exits.W33S7 = { '1': 'W33S6', '7': 'W32S7' };
Memory.rooms.W33S7 = { sources: ['bd0'], plan: {}, state: { at: Game.time }, remotes: {
    W33S6: { room: 'W33S6', enabled: true, sourceCount: 1, suspendedUntil: Game.time + 100, suspendReason: 'hostileCreep', sources: [] },
    W32S7: { room: 'W32S7', enabled: true, sourceCount: 1, suspendedUntil: Game.time + 100, suspendReason: 'hostileCreep', sources: [] } } };
const bdProfile = (count, dps, hits, until) => ({ at: Game.time, count, hits, dps, heal: 0, kiters: false, boosted: false, until });
Memory.map = {
    W33S6: { at: Game.time, source: 'external', armedHostiles: 2, threat: true, hostileProfile: bdProfile(2, 80, 2000, Game.time + 1300) },
    W32S7: { at: Game.time, source: 'external', armedHostiles: 3, threat: true, hostileProfile: bdProfile(3, 600, 12000, Game.time + 900) },
};
delete Memory.brain;
let bdDemands = require('defense').getDemands(bdHome);
assert(bdDemands.length === 1 && bdDemands[0].memory.targetRoom === 'W33S6' && bdDemands[0].memory.style === 'melee',
    '没有指令：按情报画像自己评估，W33S6 出一只近战、W32S7 打不过不出（得 ' + JSON.stringify(bdDemands.map((d) => [d.memory.targetRoom, d.memory.style])) + '）');
assert(Memory.rooms.W33S7.remotes.W32S7.suspendedUntil === Game.time + 900, '打不过的 W32S7 停到画像里的到期 tick（得 +' + (Memory.rooms.W33S7.remotes.W32S7.suspendedUntil - Game.time) + '）');
Memory.brain = { version: 1, issuedAt: Date.now(), ttlMs: 1800000, intel: {}, rooms: { W33S7: { remotes: ['W33S6', 'W32S7'], scouts: 0, claim: null,
    defense: { W33S6: { action: 'avoid', until: Game.time + 1300, reason: 'notWorth' },
        W32S7: { action: 'fight', until: Game.time + 900, reason: 'winnable', squad: { count: 2, style: 'melee', body: ['move', 'move', 'move', 'attack', 'attack', 'attack'], cost: 390, total: 780 } } } } } };
require('brain').run();
world.time++;
bdDemands = require('defense').getDemands(bdHome);
assert(bdDemands.length === 2 && bdDemands.every((d) => d.memory.targetRoom === 'W32S7' && d.memory.squad === 2 && d.body.join('') === 'movemovemoveattackattackattack'),
    '有指令：W33S6 按 avoid 不出、W32S7 按 fight 出 2 只指定身体（得 ' + JSON.stringify(bdDemands.map((d) => [d.memory.targetRoom, d.memory.squad, d.body.join('')])) + '）');
assert(Memory.rooms.W33S7.remotes.W33S6.suspendedUntil === Game.time - 1 + 1300 && Memory.rooms.W33S7.defenseLog.skipped.reason === 'brain:notWorth',
    'avoid 指令：外矿停到指令的 until，skipped 记录原因（得 ' + JSON.stringify([Memory.rooms.W33S7.remotes.W33S6.suspendedUntil - Game.time, Memory.rooms.W33S7.defenseLog.skipped]) + '）');
world.time += 1300;
Memory.map.W33S6.at = Game.time; Memory.map.W33S6.hostileProfile = bdProfile(2, 80, 2000, Game.time + 1000);
Memory.map.W32S7.at = Game.time; Memory.map.W32S7.hostileProfile = bdProfile(3, 600, 12000, Game.time + 1000);
Memory.rooms.W33S7.remotes.W33S6.suspendedUntil = Game.time + 100;
Memory.rooms.W33S7.remotes.W32S7.suspendedUntil = Game.time + 100;
bdDemands = require('defense').getDemands(bdHome);
assert(bdDemands.length === 1 && bdDemands[0].memory.targetRoom === 'W33S6', '指令 until 已过：退回游戏内评估（得 ' + JSON.stringify(bdDemands.map((d) => d.memory.targetRoom)) + '）');
delete Memory.brain;

console.log('== 静态矿工有 link 没容器：link 满了就把能量拿去建容器工地；集结中的 defender 在大脑改成 avoid 时退役 ==');
resetWorld(11400);
const lsRoom = makeRoom('W33S7', { rcl: 5, energy: 200, cap: 1800, owner: 'me', ctrl: { x: 34, y: 24 } });
lsRoom._sources = [makeSource(lsRoom, 14, 6, 'ls0')];
makeSpawn(lsRoom, 23, 21);
Memory.rooms.W33S7 = { sources: ['ls0'], plan: { containers: { src0: { x: 15, y: 7 } }, workPositions: { src0: { x: 15, y: 7 } }, links: { src0: { x: 16, y: 8 }, src: { x: 16, y: 8 } } },
    state: { at: Game.time, recovering: false, emergencyHarvest: false } };
const lsLink = makeStructure(lsRoom, C.STRUCTURE_LINK, 16, 8, { capacity: 800, energy: 800 });
lsRoom.createConstructionSite(15, 7, C.STRUCTURE_CONTAINER);
const lsMiner = makeCreep(lsRoom, 'ls-m', ['work', 'work', 'work', 'work', 'work', 'carry', 'move'], { home: 'W33S7', role: 'harvester', sourceIdx: 0, sourceId: 'ls0' });
lsMiner.pos = new RoomPosition(15, 7, 'W33S7');
lsMiner.store[C.RESOURCE_ENERGY] = 50;
world.creeps[lsMiner.name] = lsMiner;
ROLES.harvester.run(lsMiner);
assert(lsMiner.actions.includes('build') && !lsMiner.actions.includes('transfer') && !lsMiner.actions.includes('harvest'),
    'link 800/800 满、容器工地在脚下：用能量建容器（得 ' + lsMiner.actions.join(',') + '）');
lsLink.store[C.RESOURCE_ENERGY] = 300;
lsMiner.store[C.RESOURCE_ENERGY] = 50;
lsMiner.actions.length = 0;
ROLES.harvester.run(lsMiner);
assert(lsMiner.actions.includes('transfer') && lsMiner.actions.includes('harvest') && !lsMiner.actions.includes('build'),
    'link 有空位：照常喂 link 并采集（得 ' + lsMiner.actions.join(',') + '）');
world.exits.W33S7 = { '1': 'W33S6' };
Memory.rooms.W33S7.remotes = { W33S6: { room: 'W33S6', enabled: true, sourceCount: 1, suspendedUntil: Game.time + 150, suspendReason: 'hostileCreep', sources: [],
    threat: { at: Game.time, count: 2, hits: 2000, dps: 80, heal: 0, kiters: false, boosted: false, until: Game.time + 1200 } } };
delete Memory.brain;
Memory.map = {};
const lsDef = makeCreep(lsRoom, 'ls-d', ['move', 'move', 'attack', 'attack'], { home: 'W33S7', role: 'defender', targetRoom: 'W33S6', style: 'melee', squad: 2, slotKey: 'defender:W33S6' });
lsDef.pos = new RoomPosition(23, 24, 'W33S7');
world.creeps[lsDef.name] = lsDef;
assert(require('defense').planFor(lsRoom, 'W33S6') && require('defense').planFor(lsRoom, 'W33S6').count >= 1, '前提：母房还想为 W33S6 出兵');
ROLES.defender.run(lsDef);
assert(!retiring(lsDef), '组没齐但母房仍想出兵：在家等');
Memory.brain = { version: 1, issuedAt: Date.now(), ttlMs: 1800000, intel: {}, rooms: { W33S7: { remotes: ['W33S6'], scouts: 0, claim: null,
    defense: { W33S6: { action: 'avoid', until: Game.time + 1200, reason: 'notWorth' } } } } };
require('brain').run();
world.time++;
assert(!require('defense').planFor(lsRoom, 'W33S6'), '大脑改成 avoid：planFor 为空');
lsDef.actions.length = 0;
ROLES.defender.run(lsDef);
assert(retiring(lsDef) && !lsDef.actions.includes('suicide') && lsDef.memory.retired === true, '集结中的 defender 在大脑改成 avoid 后走向 spawn 回收（得 ' + lsDef.actions.join(',') + '）');
delete Memory.brain;

