world.creeps.awH0 = makeCreep(ahWeak, 'awH0', ['work', 'work', 'carry', 'move'], { home: 'W35S7', role: 'harvester', sourceIdx: 0, sourceId: 'aw0' });
world.creeps.awH1 = makeCreep(ahWeak, 'awH1', ['work', 'work', 'carry', 'move'], { home: 'W35S7', role: 'harvester', sourceIdx: 1, sourceId: 'aw1' });
world.creeps.awHa = makeCreep(ahWeak, 'awHa', ['carry', 'carry', 'move', 'move'], { home: 'W35S7', role: 'hauler' });
const aidMod2 = require('aid');
let ahAid = aidMod2.getDemands(ahHome);
assert(ahAid.length >= 2 && ahAid.every((d) => d.strategic === false), '弱房两个源都有小矿工、有小 hauler：援建需求存在但不是 strategic（得 ' + JSON.stringify(ahAid.map((d) => [d.slot, d.strategic])) + '）');
assert(spawnMgr.builderTarget(ahHome) >= 2, '前提：母房 builder 目标 ≥ 2（得 ' + spawnMgr.builderTarget(ahHome) + '）');
spawnMgr.run(ahHome);
let ahSpawned = Object.values(world.creeps).filter((c) => c.memory.aid);
const ahQueue = Memory.rooms.W33S7.spawnQueue;
assert(ahSpawned.length === 0 && ahQueue.waiting && ahQueue.waiting.key.startsWith('core:builder'),
    '母房 builder（发展档）等能量：援建不插队，队头是 builder（得 ' + JSON.stringify([ahSpawned.map((c) => c.memory.role), ahQueue.waiting]) + '）');
delete world.creeps.awHa;
world.time++;
ahAid = aidMod2.getDemands(ahHome);
assert(ahAid.some((d) => d.role === 'hauler' && d.strategic === true) && ahAid.filter((d) => d.role === 'harvester').every((d) => d.strategic === false), '弱房没 hauler：只有援建 hauler 是 strategic，有小矿工的源的援建矿工仍不是（得 ' + JSON.stringify(ahAid.map((d) => [d.role, d.strategic])) + '）');
Memory.rooms.W33S7.spawnSince = Object.assign(Memory.rooms.W33S7.spawnSince || {}, { 'core:builder:1': Game.time, 'aid:aid:hauler:W35S7': Game.time - 400 });
spawnMgr.run(ahHome);
ahSpawned = Object.values(world.creeps).filter((c) => c.memory.aid);
assert(ahSpawned.length === 1 && ahSpawned[0].memory.role === 'hauler' && ahSpawned[0].memory.home === 'W35S7',
    '弱房缺 hauler：援建 hauler 越过等能量的 builder 孵出（得 ' + JSON.stringify(ahSpawned.map((c) => c.memory.role + '@' + c.memory.home)) + '）');

console.log('== 无 storage 的房：storage 工地排在道路前（builder 工地顺序与 broker 建造权重），有 storage 后道路照旧在前 ==');
resetWorld(11600);
const sbrRoom = makeRoom('W33S7', { rcl: 5, energy: 1000, cap: 1800, owner: 'me', ctrl: { x: 34, y: 24 } });
sbrRoom._sources = [makeSource(sbrRoom, 14, 6, 'sbr0')];
makeSpawn(sbrRoom, 23, 21);
Memory.rooms.W33S7 = { sources: ['sbr0'], plan: { containers: {} }, state: { at: Game.time, recovering: false, emergencyHarvest: false } };
sbrRoom.createConstructionSite(26, 25, C.STRUCTURE_ROAD);
sbrRoom.createConstructionSite(25, 26, C.STRUCTURE_STORAGE);
const sbrRoad = sbrRoom._sites.find((s) => s.structureType === C.STRUCTURE_ROAD);
const sbrStorage = sbrRoom._sites.find((s) => s.structureType === C.STRUCTURE_STORAGE);
sbrStorage.progressTotal = 30000; sbrStorage.progress = 10834;
const sbrBuilder = makeCreep(sbrRoom, 'sbr-b', ['work', 'work', 'carry', 'carry', 'move', 'move'], { home: 'W33S7', role: 'builder' });
sbrBuilder.pos = new RoomPosition(25, 25, 'W33S7');
sbrBuilder.store[C.RESOURCE_ENERGY] = 100;
world.creeps[sbrBuilder.name] = sbrBuilder;
ROLES.builder.run(sbrBuilder);
assert(sbrBuilder.actions.includes('build') && sbrBuilder.memory.siteId === sbrStorage.id, '无 storage：builder 先建 storage 工地而不是道路（得 siteId=' + sbrBuilder.memory.siteId + '，storage=' + sbrStorage.id + '）');
taskBroker.beginTick();
const sbrTasks = taskBroker.roomTasks(sbrRoom).filter((t) => t.kind === 'build');
const sbrW = Object.fromEntries(sbrTasks.map((t) => [t.target.structureType, t.weight]));
assert(sbrW[C.STRUCTURE_STORAGE] > sbrW[C.STRUCTURE_ROAD], 'broker 建造权重：无 storage 时 storage 工地 > 道路（得 ' + JSON.stringify(sbrW) + '）');
sbrRoom.storage = makeStructure(sbrRoom, C.STRUCTURE_STORAGE, 31, 26, { capacity: 1000000, energy: 0 });
sbrBuilder.actions.length = 0; sbrBuilder.memory.siteId = null; sbrBuilder.store[C.RESOURCE_ENERGY] = 100;
ROLES.builder.run(sbrBuilder);
assert(sbrBuilder.memory.siteId === sbrRoad.id, '有 storage 后（比如第二个 storage 工地不存在的情形）道路照旧排在其它结构前（得 siteId=' + sbrBuilder.memory.siteId + '）');
world.time += 3;
taskBroker.beginTick();
const sbrTasks2 = taskBroker.roomTasks(sbrRoom).filter((t) => t.kind === 'build');
const sbrW2 = Object.fromEntries(sbrTasks2.map((t) => [t.target.structureType, t.weight]));
assert(sbrW2[C.STRUCTURE_ROAD] > sbrW2[C.STRUCTURE_STORAGE], '有 storage 时 broker 权重道路 > storage 工地（得 ' + JSON.stringify(sbrW2) + '）');

