assert(Memory.rooms.W34S7.towerFirstAt === Game.time, '遥测：紧急塔压过有缺口的 spawn 的 tick 记在 towerFirstAt（得 ' + Memory.rooms.W34S7.towerFirstAt + '）');
assert(ROLES.remoteHauler.homeTarget(ptRoom, ptRemote) === ptTower || ptTower.store[RESOURCE_ENERGY] >= 500, 'remoteHauler 同样先补塔');
