console.log('== builder 取能点按距离选最近（容器/storage/收货 link）：不再"先容器、容器没有才 storage"，也不再空等投递 ==');
{
    resetWorld(4800);
    const esRoom = makeRoom('W48S48', { rcl: 6, energy: 300, cap: 2300, ctrl: { x: 34, y: 24 }, owner: 'me' });
    makeSpawn(esRoom, 23, 21);
    const esStorage = makeStructure(esRoom, C.STRUCTURE_STORAGE, 31, 26, { energy: 500, capacity: 1000000 });
    esRoom.storage = esStorage;
    const farContainer = makeStructure(esRoom, C.STRUCTURE_CONTAINER, 15, 7, { energy: 500, capacity: 2000, my: false });
    const ctrlLink = makeStructure(esRoom, C.STRUCTURE_LINK, 32, 24, { energy: 800, capacity: 800 });
    const src0Link = makeStructure(esRoom, C.STRUCTURE_LINK, 16, 8, { energy: 800, capacity: 800 });
    esRoom.createConstructionSite(30, 26, C.STRUCTURE_ROAD);
    Memory.rooms.W48S48 = { sources: [], plan: { wheel: true, anchor: { x: 23, y: 21 }, containers: {}, links: { ctrl: { x: 32, y: 24 }, src0: { x: 16, y: 8 } }, roads: { all: '30.26' } },
        state: { at: world.time, recovering: false, emergencyHarvest: false } };
    const esBuilder = makeCreep(esRoom, 'builder.energySource', ['work', 'work', 'carry', 'move'], { home: 'W48S48', role: 'builder' });
    esBuilder.pos = new RoomPosition(30, 27, esRoom.name);
    world.creeps[esBuilder.name] = esBuilder;
    world.time++;
    ROLES.builder.run(esBuilder);
    assert(esBuilder.actions.includes('withdraw') && esStorage.store.energy < 500,
        '取能点选最近的 storage（2 格），不是 16 格外的源容器（得 ' + JSON.stringify(esBuilder.actions) + '）');
    assert(farContainer.store.energy === 500 && ctrlLink.store.energy === 800, '没动远处的容器与 link');
    esStorage.store.energy = 0;
    esBuilder.store[C.RESOURCE_ENERGY] = 0;
    esBuilder.actions.length = 0;
    world.time++;
    ROLES.builder.run(esBuilder);
    assert(esBuilder.actions.includes('withdraw') && ctrlLink.store.energy < 800 && src0Link.store.energy === 800,
        'storage 空时从控制器 link 借能，不动源 link（得 ' + JSON.stringify(esBuilder.actions) + '，ctrlLink ' + ctrlLink.store.energy + '）');
    ctrlLink.store.energy = 500;
    esBuilder.store[C.RESOURCE_ENERGY] = 0;
    esBuilder.actions.length = 0;
    world.time++;
    ROLES.builder.run(esBuilder);
    assert(ctrlLink.store.energy === 500, 'link 低于 keep + margin 时不借（得 ' + ctrlLink.store.energy + '）');
    const hauler = makeCreep(esRoom, 'hauler.selfFetch', ['carry', 'carry', 'move'], { home: 'W48S48', role: 'hauler' });
    hauler.pos = new RoomPosition(23, 21, esRoom.name);
    world.creeps[hauler.name] = hauler;
    esStorage.store.energy = 500;
    esBuilder.store[C.RESOURCE_ENERGY] = 0;
    esBuilder.actions.length = 0;
    esBuilder.memory.feedAt = world.time;
    esBuilder.pos = new RoomPosition(30, 27, esRoom.name);
    world.time++;
    ROLES.builder.run(esBuilder);
    assert(esBuilder.actions.includes('withdraw') || esBuilder.moveCalls.length > 0,
        '取能点在 8 格内时不等投递、自己去取（得 ' + JSON.stringify(esBuilder.actions) + ' move ' + esBuilder.moveCalls.length + '）');
}

console.log('== 奢侈建筑（lab/factory…）等 storage 过门槛再建，terminal 不设门槛：线上 W33S7 在 storage 0 时把升级限流让出的能量全灌进 terminal，后改为 terminal 开绿灯 ==');
{
    resetWorld(4810);
    const lxRoom = makeRoom('W48S47', { rcl: 6, energy: 2300, cap: 2300, ctrl: { x: 34, y: 24 }, owner: 'me' });
    makeSpawn(lxRoom, 23, 21);
    const lxStorage = makeStructure(lxRoom, C.STRUCTURE_STORAGE, 31, 26, { energy: 0, capacity: 1000000 });
    lxRoom.storage = lxStorage;
    Memory.rooms.W48S47 = { sources: [], builderSeenAt: world.time,
        plan: { wheel: true, version: 'lux', anchor: { x: 23, y: 21 }, storage: { x: 31, y: 26 }, terminal: { x: 32, y: 25 },
            labs: [{ x: 28, y: 30 }, { x: 29, y: 30 }, { x: 28, y: 31 }], containers: {}, links: {}, roads: { all: '' }, ext: [], towers: [] },
        state: { at: world.time, recovering: false, emergencyHarvest: false } };
    world.creeps.lxB = makeCreep(lxRoom, 'lxB', ['work', 'carry', 'move'], { home: 'W48S47', role: 'builder' });
    const sitesOf = (type) => lxRoom.find(FIND_MY_CONSTRUCTION_SITES).filter((s) => s.structureType === type);
    world.time++;
    layout.run(lxRoom);
    assert(sitesOf(C.STRUCTURE_LAB).length === 0, 'storage 0：layout 不放 lab 工地（得 ' + sitesOf(C.STRUCTURE_LAB).length + '）');
    assert(sitesOf(C.STRUCTURE_TERMINAL).length === 1, 'storage 0：terminal 不受门槛约束，layout 照常放（得 ' + sitesOf(C.STRUCTURE_TERMINAL).length + '）');
    assert(Memory.rooms.W48S47.luxuryHeld, 'lab 被门槛挡住时记下 luxuryHeld 遥测');
    assert(utils.siteWanted(lxRoom, sitesOf(C.STRUCTURE_TERMINAL)[0]), 'storage 0：terminal 工地算 wanted');
    const lxTerminalBacklog = spawnMgr.constructionBacklog(lxRoom);
    assert((lxTerminalBacklog.byType[C.STRUCTURE_TERMINAL] || lxTerminalBacklog.byType.terminal) > 0, 'storage 0：terminal 进 builder 编制的 backlog（得 ' + JSON.stringify(lxTerminalBacklog) + '）');
    sitesOf(C.STRUCTURE_TERMINAL).forEach((site) => site.remove && site.remove());
    lxRoom.createConstructionSite(28, 30, C.STRUCTURE_LAB);
    world.time++;
    assert(!ROLES.builder.nextSite(lxRoom), '门槛之下 builder 不选已有的 lab 工地');
    const lxBacklog = spawnMgr.constructionBacklog(lxRoom);
    assert(!(lxBacklog.byType && (lxBacklog.byType[C.STRUCTURE_LAB] || lxBacklog.byType.lab)) && lxBacklog.raw === 0,
        '门槛之下 lab 不进 builder 编制的 backlog（得 ' + JSON.stringify(lxBacklog) + '）');
    lxRoom.createConstructionSite(27, 27, C.STRUCTURE_ROAD);
    world.time++;
    const lxNext = ROLES.builder.nextSite(lxRoom);
    assert(lxNext && lxNext.structureType === C.STRUCTURE_ROAD, '门槛之下 builder 照常建道路（得 ' + (lxNext && lxNext.structureType) + '）');
    lxStorage.store.energy = 9000;
    world.time++;
    layout.run(lxRoom);
    assert(sitesOf(C.STRUCTURE_LAB).length === 1, 'storage 9000 < 1 万：不新增 lab 工地（得 ' + sitesOf(C.STRUCTURE_LAB).length + '）');
    lxStorage.store.energy = 12000;
    world.time++;
    layout.run(lxRoom);
    assert(sitesOf(C.STRUCTURE_LAB).length > 1, 'storage 过门槛后 layout 接着放 lab 工地（得 ' + sitesOf(C.STRUCTURE_LAB).length + '）');
    const lxRich = spawnMgr.constructionBacklog(lxRoom);
    assert(lxRich.raw > 0 && (lxRich.byType[C.STRUCTURE_LAB] || lxRich.byType.lab) > 0, '过门槛后 lab 计入 backlog（得 ' + JSON.stringify(lxRich) + '）');
    delete world.creeps.lxB;
}

console.log('== spawn 为队头攒能量时 builder/升级者不跟它抢（线上 2026-09-11 W33S7：队头 builder 1350 等 400+ tick，builder 同时从 ctrl link / 源容器 / spawn 余量取能建 terminal）==');
