console.log('== 外矿相邻满载掉落优先于容器，不为零碎掉落绕路 ==');
{
    resetWorld(9900);
    const home = makeRoom('W33S7', { rcl: 4, energy: 1300, cap: 1300, owner: 'me' });
    const room = makeRoom('W33S6', { my: false, rcl: 0 });
    room._sources = [makeSource(room, 10, 10, 'salvage-source')];
    const container = makeStructure(room, C.STRUCTURE_CONTAINER, 11, 10, { id: 'salvage-container', capacity: 2000, energy: 2000 });
    Memory.rooms.W33S7 = { remotes: { W33S6: { room: 'W33S6', enabled: true, sources: [{ id: 'salvage-source', pos: {x:10,y:10}, spot: {x:11,y:10}, containerId:container.id }] } } };
    const creep = makeCreep(room, 'salvage-hauler', ['carry','carry','move'], { home:'W33S7',remoteRoom:'W33S6',role:'remoteHauler',sourceId:'salvage-source',state:'collect' });
    creep.pos = new RoomPosition(11, 11, room.name);
    const drop = makeDropped(room, 11, 10, 3000);
    creep.pos.findClosestByRange = (items) => items[0] || null;
    creep.pickup = (target) => { const n = Math.min(target.amount, creep.store.getFreeCapacity()); creep.store.energy += n; target.amount -= n; return C.OK; };

    ROLES.remoteHauler.run(creep);
    assert(drop.amount === 2900 && container.store.energy === 2000, '大堆掉落先拾取，容器不动');
    world.time++;
    ROLES.remoteHauler.run(creep);
    assert(Memory.rooms.W33S7.remoteEnergySalvaged && Memory.rooms.W33S7.remoteEnergySalvaged.amount === 100, '下一 tick 实际到账才记录救回能量');
    creep.store.energy = 0; creep.memory.state = 'collect'; drop.amount = 1;
    ROLES.remoteHauler.run(creep);
    assert(drop.amount === 0 && container.store.energy === 1901, '零碎掉落不足装满时同 tick 捡掉落 + 容器补差，一次装满');
}

console.log('== RCL5 controller link receives sub-rich storage surplus ==');
{
 resetWorld(20000);
 const room=makeRoom('W33S7',{rcl:5,energy:1800,cap:1800,ctrl:{x:35,y:20}});
 room._sources=[makeSource(room,10,10,'cl-source')];
 const storage=makeStructure(room,C.STRUCTURE_STORAGE,25,20,{energy:7600,capacity:1000000});
 const ctrl=makeStructure(room,C.STRUCTURE_LINK,34,20,{energy:0,capacity:800});
 const spawn=makeSpawn(room,25,22);spawn.store.energy=300;
 Memory.rooms.W33S7={plan:{links:{ctrl:{x:34,y:20}},containers:{}}};
 const up=makeCreep(room,'cl-up',['work','carry','move'],{home:room.name,role:'upgrader'});
 up.pos=new RoomPosition(34,21,room.name);world.creeps[up.name]=up;
 const h=makeCreep(room,'cl-haul',['carry','carry','move'],{home:room.name,role:'hauler'});
 h.pos=new RoomPosition(25,21,room.name);world.creeps[h.name]=h;
 let task=taskBroker.roomTasks(room).find(t=>t.kind==='deliver'&&t.target===ctrl);
 assert(task&&task.tier===1,'empty controller link gets fair delivery before storage is rich');
 ROLES.hauler.run(h);
 assert(h.store.energy===100&&storage.store.energy===7500,'idle hauler uses bounded storage surplus for controller link');
 world.time++;taskBroker.beginTick();h.pos=new RoomPosition(34,21,room.name);ROLES.hauler.run(h);
 assert(ctrl.store.energy===100,'storage cargo reaches controller link');
 room.energyAvailable=1000;Memory.rooms.W33S7.spawnWaiting={at:Game.time,cost:1500};ctrl.store.energy=0;
 task=taskBroker.roomTasks(room).find(t=>t.kind==='deliver'&&t.target===ctrl);
 assert(task&&task.tier===3,'pending spawn keeps controller link in normal delivery tier');
 delete Memory.rooms.W33S7.spawnWaiting;room.energyAvailable=1800;ctrl.store.energy=400;
 assert(!taskBroker.roomTasks(room).some(t=>t.kind==='deliver'&&t.target===ctrl),'buffered controller link no longer demands surplus');
 ctrl.store.energy=0;storage.store.energy=2000;h.store.energy=0;h.pos=new RoomPosition(25,21,room.name);h.actions.length=0;
 world.time++;taskBroker.beginTick();ROLES.hauler.run(h);
 assert(!h.actions.includes('withdraw')&&storage.store.energy===2000,'storage reserve is never spent');
 const container = makeStructure(room, C.STRUCTURE_CONTAINER, 10, 11, {energy: 500, capacity: 2000, my: false});
 Memory.rooms.W33S7.plan.containers.src0 = {x: 10, y: 11};
 storage.store.energy = 7600; h.pos = new RoomPosition(10, 12, room.name);
 world.time++; taskBroker.forceReplan(); taskBroker.beginTick(); ROLES.hauler.run(h);
 assert(container.store.energy === 400 && storage.store.energy === 7600, 'source container collection still precedes storage fallback');
 room.controller.level = 7;
 const storeLink = makeStructure(room, C.STRUCTURE_LINK, 25, 19, {energy: 0, capacity: 800});
 Memory.rooms.W33S7.plan.links.store = {x: 25, y: 19};
 assert(!taskBroker.controllerFeedLink(room), 'ready storage hub retains existing controller routing');
 room.controller.level = 5;
 delete Memory.rooms.W33S7.plan.links.store;
 delete world.creeps[up.name];
 assert(!taskBroker.roomTasks(room).some(t=>t.kind==='deliver'&&t.target===ctrl),'no upgrader means no controller-link consumer task');
}

