    Memory.rooms.W33S7 = { sources: [pSrc.id],
        plan: { wheel: true, anchor: { x: 23, y: 21 }, containers: { src0: { x: 15, y: 7 } }, links: {}, roads: { all: '25.25' } },
        state: { at: world.time, recovering: false, emergencyHarvest: false } };
