    makeSpawn(rcRoom, 23, 21);
    const rcPlan = { anchor: { x: 23, y: 21 }, containers: { src0: { x: 30, y: 13 }, src1: { x: 15, y: 7 } },
        roads: { src0: road(6, 24, 20), src1: road(6, 22, 20) }, links: {} };
    for (const key of ['src0', 'src1']) rcRoom._structs.push({ structureType: C.STRUCTURE_CONTAINER, pos: new RoomPosition(rcPlan.containers[key].x, rcPlan.containers[key].y, 'W33S7'), store: mkStore(500, 2000) });
    Memory.rooms.W33S7 = { sources: ['rc0', 'rc1'], plan: rcPlan, state: { at: Game.time, recovering: false, emergencyHarvest: false }, spawnSpend: { ema: 5, at: Game.time, n: 10 } };
    ['rc0', 'rc1'].forEach((id, index) => { world.creeps['rcH' + index] = makeCreep(rcRoom, 'rcH' + index, utils.makeBody('staticHarvester', 800), { home: 'W33S7', role: 'harvester', sourceIdx: index, sourceId: id, staticMiner: true }); });
    spawnMgr.run(rcRoom);
