const engineLike = (c) => {
    c.calls = [];
    c.transfer = (target, type, amount) => { c.actions.push('transfer'); c.calls.push({ a: 'transfer', id: target && target.id, amount }); return C.OK; };
    c.withdraw = (target, type, amount) => { c.actions.push('withdraw'); c.calls.push({ a: 'withdraw', id: target && target.id, amount }); return C.OK; };
    c.pickup = (target) => { c.actions.push('pickup'); c.calls.push({ a: 'pickup', id: target && target.id }); return C.OK; };
    return c;
};
const rhCreep = (room, name, carry, memory, x, y, energy, ttl, extraBody) => {
    const body = (extraBody || []).concat(Array(carry).fill('carry'), Array(Math.max(1, Math.ceil(carry / 2))).fill('move'));
    const c = makeCreep(room, name, body, Object.assign({ home: 'W33S7', role: 'remoteHauler', remoteRoom: 'W33S6', sourceId: 'rhs0', srcIdx: 0 }, memory || {}),
        { ticksToLive: ttl == null ? 1500 : ttl });
    c.pos = new RoomPosition(x, y, room.name);
    c.store[C.RESOURCE_ENERGY] = energy || 0;
    world.creeps[name] = c;
    return engineLike(c);
};
const rhMiner = (room, name, work, x, y) => {
    const m = makeCreep(room, name, Array(work).fill('work').concat(['carry', 'move']), { home: 'W33S7', role: 'remoteMiner', remoteRoom: 'W33S6', sourceId: 'rhs0' });
    m.pos = new RoomPosition(x, y, room.name);
    world.creeps[name] = m;
    return m;
};
const rhCore = (room, name, energy, x, y) => {
    const c = makeCreep(room, name, utils.makeBody('hauler', 1300), { home: room.name, role: 'hauler' });
    c.pos = new RoomPosition(x, y, room.name);
    c.store[C.RESOURCE_ENERGY] = energy || 0;
    world.creeps[name] = c;
    return c;
};
