console.log('\n== 外矿运输编制：投递停靠按卸货房实测（remoteStop EMA，夹 [1,10]，没数据按 10）、周转 2，槽位/补差/换代吞吐同一个函数 ==');
{
    resetWorld(8300);
    Memory.rooms.W33S9 = {};
    assert(remoteMod.deliveryStops('W33S9') === config.remote.deliveryStopTicks, '没有实测：按回退值 ' + config.remote.deliveryStopTicks);
    Memory.rooms.W33S9.remoteStop = { ema: 2.4, n: 2 };
    assert(remoteMod.deliveryStops('W33S9') === config.remote.deliveryStopTicks, '样本不够 stopMinSamples：仍按回退值');
    Memory.rooms.W33S9.remoteStop = { ema: 2.4, n: 5 };
    assert(remoteMod.deliveryStops('W33S9') === 2.4, '样本够：用实测 2.4');
    Memory.rooms.W33S9.remoteStop = { ema: 0.3, n: 5 };
    assert(remoteMod.deliveryStops('W33S9') === 1, '实测 0.3：夹到 1');
    Memory.rooms.W33S9.remoteStop = { ema: 25, n: 5 };
    assert(remoteMod.deliveryStops('W33S9') === 10, '实测 25（卡在没目标的等待）：夹到 10');
    Memory.rooms.W33S9.remoteStop = { ema: 2, n: 5 };
    const src = { energyCapacity: 3000, roadComplete: true };
    const need = remoteMod.requiredCarryFor(src, 30, 'W33S8');
    const needMeasured = remoteMod.requiredCarryFor(src, 30, 'W33S9');
    const slotCarry = remoteMod.haulerSlots(src, 30, 5600, 'W33S9').reduce((sum, slot) => sum + slot.carry, 0);
    assert(need === 16 && needMeasured === 15 && slotCarry === 15, '需求：没数据 16、实测停靠 2 时 15，槽位合计同为 15（得 ' + [need, needMeasured, slotCarry].join('/') + '）');
}
{
    const { home } = rhWorld(8310);
    makeStructure(home, C.STRUCTURE_EXTENSION, 25, 21, { energy: 0, capacity: 50 });
    const h = rhCreep(home, 'rh.stop', 6, { state: 'deliver', dropRoom: 'W33S7' }, 26, 21, 50);
    taskBroker.beginTick();
    ROLES.remoteHauler.run(h);
    const rec = Memory.rooms.W33S7.remoteStop;
    assert(rec && rec.n === 1 && rec.ema === 0 && rec.last === 0 && h.memory.stopAt == null, '进房当 tick 就卸空：停靠 0（得 ' + JSON.stringify(rec) + '）');
    world.time++;
    h.calls.length = 0;
    h.memory.state = 'deliver';
    h.memory.dropRoom = 'W33S7';
    h.memory.stopAt = Game.time - 12;
    h.memory.stopDist = 3;
    taskBroker.beginTick();
    ROLES.remoteHauler.run(h);
    assert(rec.n === 2 && rec.last === 9 && rec.ema === 1.8, '第二趟停靠 9、EMA 1.8（得 ' + JSON.stringify(rec) + '）');
    rec.n = 5;
    Memory.rooms.W33S7.remotes.W33S6.sources[0].containerId = 'rhc0';
    remoteMod.getDemands(home);
    const source = Memory.rooms.W33S7.remotes.W33S6.sources[0];
    assert(source.haulStops === 1.8 && source.haulNeed === remoteMod.requiredCarryFor(source, source.distance, 'W33S7'),
        '编制用卸货房实测停靠 1.8（得 haulStops ' + source.haulStops + ' haulNeed ' + source.haulNeed + '）');
}

console.log('\n== feeder / courier：取满 / 投空的那一 tick 就起步（同 tick 取送 + 移动）==');
{
    resetWorld(8400);
    const r = makeRoom('W33S7', { rcl: 4, energy: 1300, cap: 1300, owner: 'me', ctrl: { x: 34, y: 24 } });
    makeSpawn(r, 23, 21);
    Memory.rooms.W33S7 = { plan: { containers: { ctrl: { x: 33, y: 25 } }, links: {}, roads: {} }, state: { at: Game.time, recovering: false, emergencyHarvest: false } };
    const storage = makeStructure(r, C.STRUCTURE_STORAGE, 21, 20, { energy: SF_RICH, capacity: 1000000 });
    const ctrl = makeStructure(r, C.STRUCTURE_CONTAINER, 33, 25, { my: false, energy: 500, capacity: 2000 });
    const f = engineLike(makeCreep(r, 'fd.chain', ['carry', 'carry', 'carry', 'carry', 'move', 'move'], { home: 'W33S7', role: 'feeder' }));
    world.creeps[f.name] = f;
    f.pos = new RoomPosition(22, 20, 'W33S7');
    ROLES.feeder.run(f);
    const w = callsOf(f, 'withdraw');
    assert(w.length === 1 && w[0].id === storage.id && w[0].amount === 200 && headingTo(f, ctrl), 'feeder 取满 200 当 tick 朝控制器容器走（withdraw ' + JSON.stringify(w) + '）');
    f.calls.length = 0; f.moveCalls.length = 0;
    f.pos = new RoomPosition(32, 25, 'W33S7');
    f.store[C.RESOURCE_ENERGY] = 200;
    ROLES.feeder.run(f);
    const t = callsOf(f, 'transfer');
    assert(t.length === 1 && t[0].id === ctrl.id && t[0].amount === 200 && headingTo(f, storage), 'feeder 投空当 tick 回 storage（transfer ' + JSON.stringify(t) + '）');
    f.calls.length = 0; f.moveCalls.length = 0;
    ctrl.store[C.RESOURCE_ENERGY] = 1950;
    ROLES.feeder.run(f);
    assert(callsOf(f, 'transfer')[0] && callsOf(f, 'transfer')[0].amount === 50 && !headingTo(f, storage), '容器只剩 50 空位：投 50、不回 storage');
    f.calls.length = 0; f.moveCalls.length = 0;
    ctrl.store[C.RESOURCE_ENERGY] = 500;
    f.pos = new RoomPosition(27, 25, 'W33S7');
    ROLES.feeder.run(f);
    assert(callsOf(f, 'transfer').length === 0 && headingTo(f, ctrl), '不在射程内：先走到容器旁');
}
{
    resetWorld(8410);
    const home = makeRoom('W33S7', { rcl: 5, energy: 1800, cap: 1800, owner: 'me' });
    makeSpawn(home, 23, 21);
    const storage = makeStructure(home, C.STRUCTURE_STORAGE, 21, 20, { energy: 26000, capacity: 1000000 });
    const weak = makeRoom('W33S8', { rcl: 4, energy: 300, cap: 900, owner: 'me' });
    const weakSpawn = makeSpawn(weak, 14, 40);
    weakSpawn.store[C.RESOURCE_ENERGY] = 250;
    const ext = makeStructure(weak, C.STRUCTURE_EXTENSION, 18, 40, { energy: 0, capacity: 50 });
    Memory.rooms.W33S7 = { plan: {}, state: { at: Game.time, recovering: false, emergencyHarvest: false } };
    Memory.rooms.W33S8 = { plan: {}, state: { at: Game.time, recovering: false, emergencyHarvest: false } };
    const c = engineLike(makeCreep(home, 'cr.chain', ['carry', 'carry', 'carry', 'carry', 'move', 'move'], { home: 'W33S8', role: 'courier', from: 'W33S7' }));
    world.creeps[c.name] = c;
    c.pos = new RoomPosition(22, 21, 'W33S7');
    ROLES.courier.run(c);
    const w = callsOf(c, 'withdraw');
    assert(w.length === 1 && w[0].id === storage.id && w[0].amount === 200 && headingRoom(c, 'W33S8') && c.memory.state === 'deliver', 'courier 取满当 tick 朝弱房走（withdraw ' + JSON.stringify(w) + '）');
    c.calls.length = 0; c.moveCalls.length = 0;
    c.room = weak;
    c.pos = new RoomPosition(15, 40, 'W33S8');
    c.store[C.RESOURCE_ENERGY] = 200;
    taskBroker.beginTick();
    ROLES.courier.run(c);
    const t = callsOf(c, 'transfer');
    assert(t.length === 1 && t[0].id === weakSpawn.id && t[0].amount === 50 && headingTo(c, ext), 'courier 投 spawn 50，当 tick 朝下一站 extension 走（transfer ' + JSON.stringify(t) + '）');
    c.calls.length = 0; c.moveCalls.length = 0;
    c.store[C.RESOURCE_ENERGY] = 40;
    world.time++;
    taskBroker.beginTick();
    ROLES.courier.run(c);
    assert(callsOf(c, 'transfer').length === 1 && headingRoom(c, 'W33S7'), 'courier 投空当 tick 回母房');
}

console.log('== 打捞：入侵者阵亡掉的化合物（tombstone / 同格掉落 / ruin 里的非能量资源）由 hauler 主动收进 terminal·storage ==');
{
    let base = 30000;
    const setup = (opts = {}) => {
        resetWorld(base += 100);
        const room = makeRoom('W35S7', { rcl: 6, energy: opts.energy == null ? 1300 : opts.energy, cap: 1300, ctrl: { x: 40, y: 25 } });
        makeSpawn(room, 38, 22);
        if (opts.storage !== false) {
            room.storage = makeStructure(room, C.STRUCTURE_STORAGE, 38, 20, { energy: 5000, capacity: 1000000 });
        }
        if (opts.terminal) {
            const used = opts.terminalFull ? 300000 : (opts.terminalFree != null ? 300000 - opts.terminalFree : 0);
            room.terminal = makeStructure(room, C.STRUCTURE_TERMINAL, 37, 20, { energy: used, capacity: 300000 });
        }
        Memory.rooms.W35S7 = { plan: { containers: {}, links: {}, roads: {} } };
        const hauler = makeCreep(room, 'salv.1', ['carry', 'carry', 'carry', 'move'], { home: 'W35S7', role: 'hauler' });
        hauler.pos = new RoomPosition(38, 21, 'W35S7');
        world.creeps[hauler.name] = hauler;
        return { room, hauler };
    };
    const step = (creep) => { world.time++; taskBroker.beginTick(); creep.actions.length = 0; creep.moveCalls.length = 0; ROLES.hauler.run(creep); };

    let { room, hauler } = setup();
    const tomb = makeTombstone(room, 12, 5, 0, { GO: 95, KO: 17, ZH: 23, UH: 11 });
    step(hauler);
    assert(headingTo(hauler, tomb) && hauler.memory.salvage && hauler.memory.salvage.x === 12 && hauler.memory.salvage.y === 5,
        '空载 hauler 认领 26 格外的化合物 tombstone 并起步（认领 ' + JSON.stringify(hauler.memory.salvage) + '）');
    hauler.pos = new RoomPosition(12, 6, 'W35S7');
    step(hauler);
    assert(hauler.store.GO === 95 && tomb.store.GO === 0, '到了先取最大的一种：GO 95 进车（得 ' + hauler.store.GO + '）');
    step(hauler);
    step(hauler);
    step(hauler);
    assert(hauler.store.KO === 17 && hauler.store.ZH === 23 && hauler.store.UH === 11 && nonEnergyTotal(tomb.store) === 0,
        '每 tick 收一种，四种全部收完（车上 ' + JSON.stringify(pickTypes(hauler.store)) + '）');
    assert(Memory.rooms.W35S7.salvaged && Memory.rooms.W35S7.salvaged.amount === 146, '遥测记下打捞总量 146（得 ' + JSON.stringify(Memory.rooms.W35S7.salvaged) + '）');
    step(hauler);
    assert(!hauler.memory.salvage && headingTo(hauler, room.storage), '堆收光后放掉认领，转去 storage 卸货');
    hauler.pos = new RoomPosition(38, 21, 'W35S7');
    step(hauler); step(hauler); step(hauler); step(hauler);
    assert(room.storage.store.GO === 95 && room.storage.store.KO === 17 && room.storage.store.ZH === 23 && room.storage.store.UH === 11,
        '四种化合物全部进 storage（得 ' + JSON.stringify(pickTypes(room.storage.store)) + '）');
    assert(nonEnergyTotal(hauler.store) === 0, '卸完车上不留矿物，容量还给能量运输');

    ({ room, hauler } = setup());
    const d1 = makeDropped(room, 12, 5, 20, 'GO');
    const d2 = makeDropped(room, 12, 5, 17, 'KO');
    makeDropped(room, 12, 5, 23, 'ZH');
    hauler.pos = new RoomPosition(12, 8, 'W35S7');
    step(hauler);
    assert(headingTo(hauler, d1) || headingTo(hauler, d2), '同格三堆掉落（20+17+23=60）合并后过门槛，hauler 起步');
    hauler.pos = new RoomPosition(12, 6, 'W35S7');
    step(hauler); step(hauler); step(hauler);
    assert(hauler.store.GO === 20 && hauler.store.KO === 17 && hauler.store.ZH === 23,
        '掉落按自己的资源类型进车，不会变成能量（车上 ' + JSON.stringify(pickTypes(hauler.store)) + '）');

    ({ room, hauler } = setup());
    const ruin = makeRuin(room, 12, 5, 0, { O: 500 });
    step(hauler);
    assert(headingTo(hauler, ruin), 'ruin 里的矿物也打捞');
    hauler.pos = new RoomPosition(12, 6, 'W35S7');
    step(hauler);
    assert(hauler.store.O === 150 && ruin.store.O === 350, '一车只装得下 150，剩下的留在 ruin 里等下一趟');
    step(hauler);
    assert(hauler.memory.salvage && headingTo(hauler, room.storage), '装满后保留认领（别的 hauler 不重复跑），先去卸货');

    ({ room, hauler } = setup({ terminal: true }));
    hauler.store.GO = 60;
    step(hauler);
    assert(room.terminal.store.GO === 60 && !room.storage.store.GO, '有 terminal 时矿物先送 terminal（得 ' + JSON.stringify(pickTypes(room.terminal.store)) + '）');
    ({ room, hauler } = setup({ terminal: true, terminalFull: true }));
    hauler.store.GO = 60;
    step(hauler);
    assert(room.storage.store.GO === 60 && !room.terminal.store.GO, 'terminal 放不下时退回 storage');

    ({ room, hauler } = setup({ terminal: true, terminalFree: 50 }));
    hauler.store.GO = 140;
    step(hauler);
    assert(room.terminal.store.GO === 50 && hauler.store.GO === 90,
        'terminal 只剩 50 空位：这趟进 50，剩 90 还在车上（得 terminal ' + room.terminal.store.GO + ' / 车上 ' + hauler.store.GO + '）');
    step(hauler);
    assert(room.storage.store.GO === 90 && !hauler.store.GO,
        'terminal 满了之后剩下的 90 改走 storage（得 ' + JSON.stringify(pickTypes(room.storage.store)) + '）');

    ({ room, hauler } = setup());
    makeTombstone(room, 12, 5, 0, { GO: 20 });
    step(hauler);
    assert(!hauler.memory.salvage, '26 格外只有 20 单位：够不着门槛（30 + 2×路程），不专程跑');
    ({ room, hauler } = setup({ energy: 100 }));
    makeTombstone(room, 12, 5, 0, { GO: 95, KO: 17, ZH: 23, UH: 11 });
    step(hauler);
    assert(!hauler.memory.salvage, 'spawn·ext 见底（房间 urgent）时先顾经济，不去捡矿物');
    ({ room, hauler } = setup({ storage: false }));
    makeTombstone(room, 12, 5, 0, { GO: 95, KO: 17, ZH: 23, UH: 11 });
    step(hauler);
    assert(!hauler.memory.salvage && nonEnergyTotal(hauler.store) === 0, '没有 terminal·storage 可卸时不去捡（捡了只能扔）');

    ({ room, hauler } = setup());
    makeTombstone(room, 12, 5, 0, { GO: 95, KO: 17, ZH: 23, UH: 11 });
    hauler.memory.fill = 'some-source-container';
    step(hauler);
    assert(hauler.memory.salvage && !hauler.memory.fill, '接下打捞单时放掉补满目标');
    assert(Memory.rooms.W35S7.haulFill && Memory.rooms.W35S7.haulFill.drop === 1,
        '遥测记一次放弃补满（得 ' + JSON.stringify(Memory.rooms.W35S7.haulFill) + '）');

    ({ room, hauler } = setup());
    makeTombstone(room, 12, 5, 0, { GO: 95, KO: 17, ZH: 23, UH: 11 });
    step(hauler);
    assert(hauler.memory.salvage, '不急的时候先认领');
    room.energyAvailable = 100;
    step(hauler);
    assert(!hauler.memory.salvage, '空车走到半路房间变急：放掉认领回去运能量');
    ({ room, hauler } = setup());
    const partial = makeTombstone(room, 12, 5, 0, { GO: 95, KO: 17 });
    hauler.pos = new RoomPosition(12, 6, 'W35S7');
    step(hauler);
    assert(hauler.store.GO === 95, '先装上一部分');
    room.energyAvailable = 100;
    step(hauler);
    assert(hauler.memory.salvage && hauler.store.KO === 17 && nonEnergyTotal(partial.store) === 0,
        '车上已有货：房间变急也把这堆收完，不半途而废（车上 ' + JSON.stringify(pickTypes(hauler.store)) + '）');

    ({ room, hauler } = setup());
    makeTombstone(room, 12, 5, 0, { GO: 95, KO: 17, ZH: 23, UH: 11 });
    hauler.memory.brokerTask = { kind: 'collect', id: 'some-source-container:collect', until: Game.time + 5 };
    step(hauler);
    assert(hauler.memory.salvage && !hauler.memory.brokerTask,
        '接下打捞单时放掉 broker 租约（残留租约会让 task_broker 把那个源容器屏蔽 150 tick）');

    ({ room, hauler } = setup({ energy: 100 }));
    makeTombstone(room, 12, 5, 0, { GO: 95, KO: 17, ZH: 23, UH: 11 });
    hauler.memory.fill = 'some-source-container';
    step(hauler); step(hauler); step(hauler);
    assert(!hauler.memory.salvage, 'urgent 房里连续 3 tick 都不写打捞认领');
    assert(!Memory.rooms.W35S7.haulFill || !Memory.rooms.W35S7.haulFill.drop,
        'urgent 时不会每 tick 记一次"放弃补满"（得 ' + JSON.stringify(Memory.rooms.W35S7.haulFill) + '）');

    ({ room, hauler } = setup());
    makeDropped(room, 12, 5, 1, 'GO');
    step(hauler);
    assert(!hauler.memory.salvage, '默认门槛下 1 单位不值得跑');
    const savedMin = config.salvage.minAmount;
    const savedPer = config.salvage.perTile;
    config.salvage.minAmount = 0;
    config.salvage.perTile = 0;
    step(hauler);
    assert(hauler.memory.salvage, 'minAmount: 0 = 什么都捡，0 不能被当成"没配"');
    config.salvage.minAmount = savedMin;
    config.salvage.perTile = savedPer;

    ({ room, hauler } = setup());
    makeDropped(room, 12, 5, 3000);
    const energyTomb = makeTombstone(room, 13, 6, 800);
    step(hauler);
    assert(!hauler.memory.salvage, '能量掉落与纯能量 tombstone 都不是打捞目标（能量归 broker 管）');
    assert(!hauler.actions.includes('pickup') || hauler.store[RESOURCE_ENERGY] > 0, '能量要么不碰，要么走正常取货路径');
    assert(nonEnergyTotal(energyTomb.store) === 0 && energyTomb.store[RESOURCE_ENERGY] === 800, '纯能量 tombstone 原封不动');

    ({ room, hauler } = setup());
    makeTombstone(room, 12, 5, 0, { GO: 95, KO: 17, ZH: 23, UH: 11 });
    hauler.store[RESOURCE_ENERGY] = 120;
    step(hauler);
    assert(!hauler.memory.salvage, '车上有能量（正在送货）：不接打捞单');

    ({ room, hauler } = setup());
    const bigPile = makeRuin(room, 12, 5, 0, { O: 500 });
    hauler.pos = new RoomPosition(12, 6, 'W35S7');
    step(hauler);
    assert(hauler.store.O === 150, '空车装满 150');
    hauler.store.O = 100;
    step(hauler);
    assert(hauler.store.O === 150 && bigPile.store.O === 300,
        '车上已有 100 时只要 50（按整车容量要 150 会被引擎整笔 ERR_FULL，一点都搬不到；得 ' + hauler.store.O + '）');

    ({ room, hauler } = setup());
    hauler.pos = new RoomPosition(2, 2, 'W35S7');
    makeTombstone(room, 45, 45, 0, { GO: 400 });
    step(hauler);
    assert(!hauler.memory.salvage, 'maxRange 之外的堆不专程去（哪怕量很大）');
    ({ room, hauler } = setup());
    hauler.pos = new RoomPosition(12, 25, 'W35S7');
    const midPile = makeTombstone(room, 12, 5, 0, { GO: 60 });
    step(hauler);
    assert(!hauler.memory.salvage, '20 格外 60 单位：过了 minAmount 但没过距离加价（30 + 2×20 = 70）');
    midPile.store.GO = 80;
    step(hauler);
    assert(hauler.memory.salvage, '同样 20 格、80 单位：过了加价后的门槛');

    ({ room, hauler } = setup({ storage: false }));
    hauler.store.GO = 60;
    step(hauler);
    assert(hauler.actions.includes('drop') && !hauler.store.GO,
        '没有 terminal/storage：车上的矿物扔掉，把容量还给能量运输');
    assert(Memory.rooms.W35S7.haulSalvage && Memory.rooms.W35S7.haulSalvage.n > 0, '扔掉也记遥测');

    ({ room, hauler } = setup());
    makeTombstone(room, 12, 5, 0, { GO: 95, KO: 17, ZH: 23, UH: 11 });
    hauler.memory.brokerTask = { kind: 'collect', id: 'salv-lease:collect', until: Game.time + 5 };
    const origRelease = taskBroker.releaseClaim;
    let released = null;
    taskBroker.releaseClaim = (id, creep) => { released = { id, name: creep && creep.name }; return origRelease(id, creep); };
    try { step(hauler); } finally { taskBroker.releaseClaim = origRelease; }
    assert(released && released.id === 'salv-lease:collect' && released.name === hauler.name,
        '退出 broker 时调 releaseClaim 放掉本 tick 的认领（得 ' + JSON.stringify(released) + '）');

    ({ room, hauler } = setup());
    hauler.store.GO = 60;
    hauler.pos = new RoomPosition(30, 30, 'W35S7');
    hauler.memory.brokerTask = { kind: 'collect', id: 'some-source-container:collect', until: Game.time + 5 };
    step(hauler);
    assert(!hauler.memory.brokerTask, '卸矿物途中也放掉 broker 租约');

    ({ room, hauler } = setup());
    makeTombstone(room, 12, 5, 0, { GO: 95, KO: 17, ZH: 23, UH: 11 });
    const second = makeCreep(room, 'salv.2', ['carry', 'carry', 'carry', 'move'], { home: 'W35S7', role: 'hauler' });
    second.pos = new RoomPosition(38, 23, 'W35S7');
    world.creeps[second.name] = second;
    step(hauler);
    step(second);
    assert(hauler.memory.salvage && !second.memory.salvage, '同一堆只认领一次，第二只不跟着跑（跑到时东西已在别人车上）');

    ({ room, hauler } = setup());
    const decaying = makeTombstone(room, 12, 5, 0, { GO: 95 });
    step(hauler);
    assert(hauler.memory.salvage, '先认领');
    decaying.store.GO = 0;
    step(hauler);
    assert(!hauler.memory.salvage, '目标被别人收走 / 衰减光：立刻放掉认领');
    ({ room, hauler } = setup());
    const goneSoon = makeTombstone(room, 12, 5, 0, { GO: 95 });
    makeTombstone(room, 20, 25, 0, { KO: 90 });
    hauler.pos = new RoomPosition(12, 7, 'W35S7');
    step(hauler);
    assert(hauler.memory.salvage && hauler.memory.salvage.x === 12, '先认领近的那堆');
    goneSoon.store.GO = 0;
    step(hauler);
    assert(!hauler.memory.salvage || hauler.memory.salvage.x === 20,
        '认领的那堆没了、房里还有别的堆：放掉旧认领，不崩（认领 ' + JSON.stringify(hauler.memory.salvage) + '）');
    ({ room, hauler } = setup());
    makeTombstone(room, 12, 5, 0, { GO: 95 });
    step(hauler);
    const claimedAt = hauler.memory.salvage.at;
    world.time += (config.salvage.timeout || 200) + 1;
    step(hauler);
    assert(hauler.memory.salvage.at > claimedAt, '认领超时后重新评估，不是一直挂着旧的');
}

console.log('== 出生口袋：spawn 旁被墙/extension 围死的格不当出生方向（线上 2026-10-08 W31S4：Spawn18 正上方 (25,15) 孵进去的升级者一步走不出来，空手站到老死）==');
{
    const pk = demoRoom(30100, 6);
    const pkMem = Memory.rooms.W33S7;
    pk.energyCapacityAvailable = 2300;
    pk.energyAvailable = 2300;
    const pkSpawn = makeSpawn(pk, 23, 21);
    pkSpawn.name = 'PkSpawn';
    for (const [x, y] of [[22, 19], [23, 19], [24, 19], [22, 20], [24, 20], [22, 21]]) makeStructure(pk, C.STRUCTURE_EXTENSION, x, y, { capacity: 50, energy: 50 });
    pk.createConstructionSite(24, 21, C.STRUCTURE_EXTENSION);
    world.time++;
    const pkDirs = spawnMgr.spawnDirections(pkSpawn);
    assert(Array.isArray(pkDirs) && !pkDirs.includes(C.TOP) && pkDirs.includes(C.BOTTOM),
        '正上方 (23,20) 是口袋：出生方向去掉 TOP，保留下方（得 ' + JSON.stringify(pkDirs) + '）');
    const pkLog = pkMem.spawnPocket && pkMem.spawnPocket.PkSpawn;
    assert(pkLog && pkLog.pockets.includes(C.TOP) && pkLog.pockets.length === 1, '遥测 spawnPocket 记下口袋方向（得 ' + JSON.stringify(pkLog) + '）');
    const pkOpts = [];
    const pkOrig = pkSpawn.spawnCreep;
    pkSpawn.spawnCreep = function (body, name, o) { pkOpts.push(o); return pkOrig.call(this, body, name, o); };
    world.time++;
    spawnMgr.run(pk);
    assert(pkOpts.length >= 1 && pkOpts.every((o) => Array.isArray(o.directions) && !o.directions.includes(C.TOP) && o.memory),
        'spawn.run 孵化时带上 directions（不含 TOP）且保留 memory（得 ' + JSON.stringify(pkOpts.map((o) => o.directions)) + '）');
    const opSpawn = makeSpawn(pk, 30, 30);
    opSpawn.name = 'OpenSpawn';
    assert(spawnMgr.spawnDirections(opSpawn) === null, '四周开阔的 spawn 不限制出生方向');
    const pkExt = pk._structs.find((s) => s.structureType === C.STRUCTURE_EXTENSION && s.pos.x === 23 && s.pos.y === 19);
    pkExt.destroy();
    world.time++;
    assert(spawnMgr.spawnDirections(pkSpawn) === null, '(23,19) 拆掉后 (23,20) 连着房间：不再限制（得 ' + JSON.stringify(spawnMgr.spawnDirections(pkSpawn)) + '）');
    for (const [x, y] of [[29, 28], [31, 28], [29, 29], [31, 29], [29, 30], [31, 30]]) makeStructure(pk, C.STRUCTURE_EXTENSION, x, y, { capacity: 50, energy: 50 });
    const pkSources = pk._sources;
    pk._sources = [];
    world.time++;
    assert(spawnMgr.spawnDirections(opSpawn) === null, '前提：(30,28) 没有源时 (30,29) 连着房间，不限制（得 ' + JSON.stringify(spawnMgr.spawnDirections(opSpawn)) + '）');
    pk._sources = (pkSources || []).concat([makeSource(pk, 30, 28, 'pkSrc')]);
    world.time++;
    const srcDirs = spawnMgr.spawnDirections(opSpawn);
    assert(Array.isArray(srcDirs) && !srcDirs.includes(C.TOP) && srcDirs.includes(C.BOTTOM), '(30,29) 只经由源格连出去：是口袋，去掉 TOP（得 ' + JSON.stringify(srcDirs) + '）');
    pk._sources = pkSources;
    const savedMineral = pk._mineral;
    pk._mineral = { id: 'pkMin', mineralType: 'H', pos: new RoomPosition(30, 28, pk.name) };
    world.time++;
    const minDirs = spawnMgr.spawnDirections(opSpawn);
    assert(Array.isArray(minDirs) && !minDirs.includes(C.TOP), '矿同样是障碍（得 ' + JSON.stringify(minDirs) + '）');
    pk._mineral = savedMineral;

    const parked = makeCreep(pk, 'pk.parked', ['carry'], { home: 'W33S7', role: 'parked' });
    parked.pos = new RoomPosition(23, 22, 'W33S7');
    world.creeps[parked.name] = parked;
    Memory.creeps[parked.name] = parked.memory;
    Memory.errors = [];
    world.time++;
    main.loop();
    assert((Memory.errors || []).length === 0 && parked.moveCalls.length === 0 && parked.pos.x === 23 && parked.pos.y === 22,
        '未知角色的 creep：loop 不报错、不动它（errors ' + JSON.stringify((Memory.errors || []).slice(0, 2)) + '）');
    delete world.creeps[parked.name];
    delete Memory.creeps[parked.name];
}

console.log('== 出生口被己方 creep 堵住：让路而不是往口袋里孵（线上 2026-10-08 W34S7：Spawn21 的替补源矿工被兜底孵进 TOP_LEFT 口袋困死）==');
{
    const spawnExit = require('../src/spawn_exit');
    const retireMod = require('../src/retire');
    const pocketCfg = config.spawnPocket;
    const ex = demoRoom(30200, 7);
    const exMem = Memory.rooms.W33S7;
    const sp21 = makeSpawn(ex, 27, 34);
    sp21.name = 'Spawn21';
    const sp23 = makeSpawn(ex, 26, 34);
    sp23.name = 'Spawn23';
    for (const [x, y] of [[25, 32], [26, 32], [27, 32], [27, 33]]) makeStructure(ex, C.STRUCTURE_WALL, x, y, { hits: 1000000, hitsMax: 300000000 });
    const exExts = {};
    for (const [x, y] of [[25, 33], [25, 34], [28, 33], [28, 35], [26, 35]]) exExts[x + ',' + y] = makeStructure(ex, C.STRUCTURE_EXTENSION, x, y, { capacity: 100, energy: 100 });
    world.time++;
    const exDirs = spawnMgr.spawnDirections(sp21);
    assert(JSON.stringify(exDirs) === JSON.stringify([C.RIGHT, C.BOTTOM]), '复现线上几何：Spawn21 只往 RIGHT/BOTTOM 出生（得 ' + JSON.stringify(exDirs) + '）');
    assert(exMem.spawnPocket.Spawn21.pockets.length === 1 && exMem.spawnPocket.Spawn21.pockets[0] === C.TOP_LEFT, 'TOP_LEFT (26,33) 是口袋（得 ' + JSON.stringify(exMem.spawnPocket.Spawn21) + '）');

    const place = (name, body, x, y, memory) => {
        const c = makeCreep(ex, name, body, Object.assign({ home: 'W33S7' }, memory || {}));
        c.pos = new RoomPosition(x, y, 'W33S7');
        world.creeps[name] = c;
        Memory.creeps[name] = c.memory;
        return c;
    };
    const unplace = (c) => { delete world.creeps[c.name]; delete Memory.creeps[c.name]; };
    const operator = place('ex.operator', ['carry', 'carry', 'move'], 27, 35, { role: 'operator' });
    const builder = place('ex.builder', ['work', 'carry', 'move'], 28, 34, { role: 'builder' });
    const setCalls = [];
    const stalled = (name, remainingTime, directions) => ({ name, needTime: 9, remainingTime, directions,
        setDirections(dirs) { setCalls.push(dirs.slice()); this.directions = dirs.slice(); return C.OK; } });
    sp21.spawning = stalled('ex.miner', 3, [C.RIGHT, C.BOTTOM]);
    delete exMem.spawnStall; delete exMem.spawnStallLog;
    world.time++;
    spawnMgr.releaseStalledSpawns(ex, exMem, [sp21, sp23]);
    assert(!builder.memory.vacate && !operator.memory.vacate && !exMem.spawnStall, '还在倒计时（remainingTime 3）：不打扰任何人');
    sp21.spawning.remainingTime = 1;
    world.time++;
    spawnMgr.releaseStalledSpawns(ex, exMem, [sp21, sp23]);
    const flag = builder.memory.vacate;
    assert(flag && flag.spawn === sp21.id && flag.name === 'ex.miner' && flag.x === 28 && flag.y === 34 && flag.until === Game.time + pocketCfg.vacateHoldTicks,
        'RIGHT (28,34) 上的 builder 被要求让路（得 ' + JSON.stringify(flag) + '）');
    assert(!operator.memory.vacate, '一次只让一只（operator 留在站位）');
    assert(exMem.spawnStallLog && exMem.spawnStallLog.vacate && exMem.spawnStallLog.vacate.n === 1 && exMem.spawnStallLog.vacate.blocker === 'ex.builder' &&
        exMem.spawnStallLog.vacate.spawn === 'Spawn21', '遥测 spawnStallLog.vacate 记下让路请求（得 ' + JSON.stringify(exMem.spawnStallLog) + '）');
    assert(exMem.spawnStall && exMem.spawnStall.Spawn21 && exMem.spawnStall.Spawn21.vacate === 'ex.builder' && exMem.spawnStall.Spawn21.since == null,
        '还没失败过：记录让路、不算卡住（得 ' + JSON.stringify(exMem.spawnStall) + '）');
    world.time++;
    spawnMgr.releaseStalledSpawns(ex, exMem, [sp21, sp23]);
    assert(exMem.spawnStallLog.vacate.n === 1, '有效标记还在：不重复请求');
    builder.moveCalls.length = 0; builder.actions.length = 0;
    Memory.errors = [];
    main.loop();
    const exMove = builder.moveCalls[builder.moveCalls.length - 1];
    assert(builder.moveCalls.length === 1 && exMove.target.x === 29 && exMove.target.y === 33 && exMove.opts.range === 0,
        'builder 走到 3 步内最近的空格 (29,33)、这 tick 只做这一件事（得 ' + JSON.stringify(builder.moveCalls) + '）');
    assert(!builder.actions.some((a) => a !== 'moveTo'), '让路的这 tick 不跑 builder 角色（得 ' + JSON.stringify(builder.actions) + '）');
    assert((Memory.errors || []).length === 0, 'loop 不报错（得 ' + JSON.stringify((Memory.errors || []).slice(0, 2)) + '）');
    assert(exMem.spawnStallLog.vacate.moved === 1 && exMem.spawnStallLog.vacate.last && exMem.spawnStallLog.vacate.last.to.x === 29,
        '遥测记下让路的移动（得 ' + JSON.stringify(exMem.spawnStallLog.vacate) + '）');
    builder.pos = new RoomPosition(29, 33, 'W33S7');
    sp21.spawning.remainingTime = 0;
    builder.moveCalls.length = 0; builder.actions.length = 0;
    world.time++;
    spawnMgr.releaseStalledSpawns(ex, exMem, [sp21, sp23]);
    assert(spawnExit.runVacate(builder) === true && builder.moveCalls.length === 0, '离开后等出生完成：接管但不动');
    assert(!operator.memory.vacate && exMem.spawnStallLog.vacate.n === 1, 'RIGHT 已空：不再要 operator 让路');
    assert(exMem.spawnStall.Spawn21.since === Game.time, '这一 tick 才算第一次出生失败');
    sp21.spawning = null;
    const newborn = place('ex.miner', ['work', 'work', 'move'], 28, 34, { role: 'harvester' });
    world.time++;
    spawnMgr.releaseStalledSpawns(ex, exMem, [sp21, sp23]);
    const born = exMem.spawnStallLog.born;
    assert(born && born.name === 'ex.miner' && born.x === 28 && born.y === 34 && born.dir === C.RIGHT && born.pocket === false && born.vacate === 'ex.builder' && !born.released,
        '遥测 born：生在 RIGHT、不是口袋、靠让路（得 ' + JSON.stringify(born) + '）');
    assert(!exMem.spawnStall, '出生后清掉记录');
    const bornHist = exMem.spawnStallLog.bornHistory;
    assert(Array.isArray(bornHist) && bornHist.length === 1 && bornHist[0].name === 'ex.miner' && bornHist[0].x === 28 && bornHist[0].pocket === false,
        '遥测 bornHistory 留下这次出生（得 ' + JSON.stringify(bornHist) + '）');
    assert(spawnExit.runVacate(builder) === false && !builder.memory.vacate, '出生完成：撤掉让路标记、交还角色');
    unplace(newborn);

    const parked = place('ex.parked', ['carry'], 28, 34, { role: 'parked' });
    builder.pos = new RoomPosition(30, 30, 'W33S7');
    sp21.spawning = stalled('ex.miner2', 1, [C.RIGHT, C.BOTTOM]);
    world.time++;
    spawnMgr.releaseStalledSpawns(ex, exMem, [sp21, sp23]);
    assert(!parked.memory.vacate && operator.memory.vacate && operator.memory.vacate.x === 27 && operator.memory.vacate.y === 35,
        '没有 MOVE 的跳过、让 operator 让路（得 ' + JSON.stringify([parked.memory.vacate, operator.memory.vacate]) + '）');
    operator.moveCalls.length = 0;
    assert(spawnExit.runVacate(operator) === true && operator.moveCalls.length === 1, 'operator 走开');
    const opTo = operator.moveCalls[0].target;
    assert(Math.max(Math.abs(opTo.x - 27), Math.abs(opTo.y - 34)) > 1 && Math.max(Math.abs(opTo.x - 26), Math.abs(opTo.y - 34)) > 1 && !(opTo.x === 26 && opTo.y === 33),
        'operator 的去处不贴着任何 spawn、不是口袋（得 ' + JSON.stringify(opTo) + '）');
    operator.pos = new RoomPosition(opTo.x, opTo.y, 'W33S7');
    for (let i = 0; i < 3; i++) {
        operator.moveCalls.length = 0;
        world.time++;
        sp21.spawning.remainingTime = 0;
        spawnMgr.releaseStalledSpawns(ex, exMem, [sp21, sp23]);
        assert(spawnExit.runVacate(operator) === true && operator.moveCalls.length === 0, '出生前 operator 不回站位（第 ' + (i + 1) + ' tick）');
    }
    sp21.spawning = null;
    world.time++;
    spawnMgr.releaseStalledSpawns(ex, exMem, [sp21, sp23]);
    assert(spawnExit.runVacate(operator) === false && !operator.memory.vacate, 'spawn 不孵了：撤标记');
    operator.pos = new RoomPosition(27, 35, 'W33S7');
    operator.fatigue = 4;
    sp21.spawning = stalled('ex.miner3', 1, [C.RIGHT, C.BOTTOM]);
    world.time++;
    spawnMgr.releaseStalledSpawns(ex, exMem, [sp21, sp23]);
    operator.moveCalls.length = 0;
    assert(operator.memory.vacate && spawnExit.runVacate(operator) === true && operator.moveCalls.length === 0, '疲劳中：标记照打，等疲劳清零再走');
    operator.fatigue = 0;
    world.time += pocketCfg.vacateHoldTicks + 1;
    assert(spawnExit.runVacate(operator) === false && !operator.memory.vacate, 'until 过期：撤标记');
    sp21.spawning = null;
    world.time++;
    spawnMgr.releaseStalledSpawns(ex, exMem, [sp21, sp23]);

    operator.body = [{ type: 'carry' }];
    delete exMem.spawnStallLog;
    setCalls.length = 0;
    sp21.spawning = stalled('ex.miner4', 0, [C.RIGHT, C.BOTTOM]);
    for (let i = 0; i <= pocketCfg.stallTicks + 2; i++) { world.time++; spawnMgr.releaseStalledSpawns(ex, exMem, [sp21, sp23]); }
    const exLog = exMem.spawnStallLog;
    assert(exLog.cannotVacate && exLog.cannotVacate.n === 1 && exLog.cannotVacate.name === 'ex.miner4' && exLog.cannotVacate.reason === 'noMove',
        '没有 MOVE 的堵口：记 cannotVacate 一次（得 ' + JSON.stringify(exLog.cannotVacate) + '）');
    assert(!operator.memory.vacate && !parked.memory.vacate, '没有 MOVE 的不打让路标记');
    assert(setCalls.length === 0 && exLog.noRelease && exLog.noRelease.name === 'ex.miner4' && JSON.stringify(exLog.noRelease.from) === JSON.stringify([C.RIGHT, C.BOTTOM]),
        '唯一没放的方向是口袋 TOP_LEFT：不调 setDirections、记 noRelease（线上旧代码放开全部 8 个方向、孵进口袋）（得 ' + JSON.stringify([setCalls, exLog]) + '）');
    exExts['28,35'].destroy();
    const exProbe = place('ex.probe', ['carry', 'move'], 28, 34, { role: 'builder' });
    const exTarget = spawnExit.vacateTarget(exProbe, ex);
    assert(exTarget && !(exTarget.x === 28 && exTarget.y === 35) && exTarget.x === 29 && exTarget.y === 33,
        '去处不选贴着 spawn 的 (28,35)，选 (29,33)（得 ' + JSON.stringify(exTarget) + '）');
    unplace(exProbe);
    sp21.spawning = stalled('ex.miner5', 0, [C.RIGHT, C.BOTTOM]);
    for (let i = 0; i <= pocketCfg.stallTicks; i++) { world.time++; spawnMgr.releaseStalledSpawns(ex, exMem, [sp21, sp23]); }
    assert(setCalls.length === 1 && JSON.stringify(setCalls[0]) === JSON.stringify([C.RIGHT, C.BOTTOM, C.BOTTOM_RIGHT]),
        '兜底只放开现在可走、不是口袋的 BOTTOM_RIGHT（原方向排前面），TOP_LEFT 口袋不放（得 ' + JSON.stringify(setCalls) + '）');
    assert(exMem.spawnStallLog.n === 1 && exMem.spawnStallLog.name === 'ex.miner5' && exMem.spawnStallLog.waited === pocketCfg.stallTicks &&
        JSON.stringify(exMem.spawnStallLog.to) === JSON.stringify([C.RIGHT, C.BOTTOM, C.BOTTOM_RIGHT]),
        '遥测 n/waited/from/to（得 ' + JSON.stringify(exMem.spawnStallLog) + '）');
    for (let i = 0; i < 3; i++) { world.time++; spawnMgr.releaseStalledSpawns(ex, exMem, [sp21, sp23]); }
    assert(setCalls.length === 1, '同一只只兜底一次');
    sp21.spawning = null;
    world.time++;
    spawnMgr.releaseStalledSpawns(ex, exMem, [sp21, sp23]);
    sp21.spawning = stalled('ex.surrounded', 0, undefined);
    for (let i = 0; i <= pocketCfg.stallTicks; i++) { world.time++; spawnMgr.releaseStalledSpawns(ex, exMem, [sp21, sp23]); }
    assert(setCalls.length === 1 && exMem.spawnStallLog.surrounded && exMem.spawnStallLog.surrounded.name === 'ex.surrounded',
        '没限制方向还生不出来：不调 setDirections、记 surrounded（得 ' + JSON.stringify(exMem.spawnStallLog) + '）');
    sp21.spawning = null;
    operator.body = [{ type: 'carry' }, { type: 'move' }];
    unplace(parked);
    sp21.spawning = stalled('ex.free', 1, [C.RIGHT, C.BOTTOM]);
    world.time++;
    spawnMgr.releaseStalledSpawns(ex, exMem, [sp21, sp23]);
    assert(!operator.memory.vacate, 'RIGHT 空着：不要 operator 让路');
    sp21.spawning = null;
    world.time++;
    spawnMgr.releaseStalledSpawns(ex, exMem, [sp21, sp23]);

    const trappedMiner = place('ex.trapped', ['work', 'work', 'work', 'carry', 'move'], 26, 33, { role: 'harvester', sourceIdx: 0 });
    builder.pos = new RoomPosition(28, 34, 'W33S7');
    const scanEvery = pocketCfg.trappedScanInterval;
    while (utils.isRoomPhaseTick('W33S7', scanEvery)) world.time++;
    spawnExit.markPocketTrapped(ex, exMem, [sp21, sp23]);
    assert(!trappedMiner.memory.pocketTrapped, '不在扫描 tick：不看');
    while (!utils.isRoomPhaseTick('W33S7', scanEvery)) world.time++;
    spawnExit.markPocketTrapped(ex, exMem, [sp21, sp23]);
    const seen1 = trappedMiner.memory.pocketSeen;
    assert(!trappedMiner.memory.pocketTrapped && seen1 && seen1.x === 26 && seen1.y === 33 && seen1.at === Game.time,
        '第一次扫描只记 pocketSeen、不标记（得 ' + JSON.stringify(trappedMiner.memory) + '）');
    world.time++;
    while (!utils.isRoomPhaseTick('W33S7', scanEvery)) world.time++;
    Memory.errors = [];
    main.loop();
    const trap = trappedMiner.memory.pocketTrapped;
    assert(!trappedMiner.memory.pocketSeen, '确认后清掉 pocketSeen');
    assert(trap && (trap.spawn === sp21.id || trap.spawn === sp23.id) && trap.x === 26 && trap.y === 33,
        '口袋 (26,33) 里的矿工被标记 pocketTrapped（得 ' + JSON.stringify(trap) + '）');
    assert(!builder.memory.pocketTrapped, '普通出口 (28,34) 上的 builder 不标记');
    assert(utils.isRetiring(trappedMiner.memory), '标记后编制立刻排除它（isRetiring）');
    const recycler = [sp21, sp23].find((sp) => sp.actions.some((a) => a.action === 'recycleCreep' && a.target === 'ex.trapped'));
    assert(recycler && trappedMiner.actions.includes('recycled') && !trappedMiner.actions.includes('harvest') && trappedMiner.moveCalls.length === 0,
        '同一 tick 由贴着的 spawn 回收、不跑矿工角色（得 ' + JSON.stringify(trappedMiner.actions) + '）');
    const trapLog = exMem.spawnStallLog.trapped;
    assert(trapLog && trapLog.n === 1 && trapLog.name === 'ex.trapped' && trapLog.recycled === 1 && trapLog.code === C.OK && trapLog.x === 26 && trapLog.y === 33,
        '遥测 spawnStallLog.trapped 记下标记与回收（得 ' + JSON.stringify(trapLog) + '）');
    assert((Memory.errors || []).length === 0, 'loop 不报错（得 ' + JSON.stringify((Memory.errors || []).slice(0, 2)) + '）');
    trappedMiner.pos = new RoomPosition(30, 30, 'W33S7');
    assert(retireMod.retirePocketTrapped(trappedMiner) === false && !trappedMiner.memory.pocketTrapped, '已不在那格：撤标记');
    for (const c of [operator, builder, trappedMiner]) unplace(c);

    const wall2732 = ex._structs.findIndex((st) => st.structureType === C.STRUCTURE_WALL && st.pos.x === 27 && st.pos.y === 32);
    ex._structs.splice(wall2732, 1);
    assert(ex.createConstructionSite(27, 32, C.STRUCTURE_EXTENSION) === C.OK, '夹具：(27,32) 放 extension 工地');
    world.time++;
    assert(spawnExit.computeSpawnDirections(ex, sp21).pockets.includes(C.TOP_LEFT), '出生方向仍把工地围成的 (26,33) 当口袋（按建成后算）');
    assert(!spawnExit.computeSpawnDirections(ex, sp21, spawnExit.walkability(ex, { sites: false })).pockets.includes(C.TOP_LEFT),
        '不算工地时 (26,33) 连得出去（sites:false）');
    const siteBuilder = place('ex.sitebuilder', ['work', 'carry', 'move'], 26, 33, { role: 'builder' });
    for (let scan = 0; scan < 3; scan++) {
        world.time++;
        while (!utils.isRoomPhaseTick('W33S7', scanEvery)) world.time++;
        spawnExit.markPocketTrapped(ex, exMem, [sp21, sp23]);
    }
    assert(!siteBuilder.memory.pocketTrapped && !siteBuilder.memory.pocketSeen && !utils.isRetiring(siteBuilder.memory),
        '站在只因工地围成的格里的 builder 不标记、不回收（得 ' + JSON.stringify(siteBuilder.memory) + '）');
    assert(exMem.spawnStallLog.trapped.n === 1, 'trapped 计数不变（得 ' + JSON.stringify(exMem.spawnStallLog.trapped) + '）');
    unplace(siteBuilder);
    for (const site of ex.find(C.FIND_MY_CONSTRUCTION_SITES).slice()) if (site.pos.x === 27 && site.pos.y === 32) site.remove();
}

console.log('== 升级者卡死看门狗：离控制器远、原地不动的升级者先重算路径、再退役让替补出生（线上 2026-10-08 W31S4：慧音甲 困在出生口袋空手站了 600+ tick）==');
{
    const wd = demoRoom(30300, 7);
    const wdPlan = Memory.rooms.W33S7.plan;
    const wdMem = Memory.rooms.W33S7;
    const wdCfg = require('../src/config').upgrading;
    wd.energyCapacityAvailable = 5600;
    wd.energyAvailable = 5600;
    const wdSpawn = makeSpawn(wd, 23, 21);
    for (const [x, y] of [[22, 19], [23, 19], [24, 19], [22, 20], [24, 20], [22, 21], [24, 21]]) makeStructure(wd, C.STRUCTURE_EXTENSION, x, y, { capacity: 100, energy: 100 });
    makeStructure(wd, C.STRUCTURE_STORAGE, 23, 23, { energy: 2500, capacity: 1000000 });
    const wdLink = makeStructure(wd, C.STRUCTURE_LINK, wdPlan.links.ctrl.x, wdPlan.links.ctrl.y, { energy: 796, capacity: 800 });
    wdMem.upgradeSupply = { ema: 1, extra: 0, at: -1, changedAt: -1, low: true };
    const wdUp = makeCreep(wd, 'wd.up', [].concat(Array(12).fill('work'), Array(6).fill('carry'), ['move']), { home: 'W33S7', role: 'upgrader' });
    wdUp.pos = new RoomPosition(23, 20, 'W33S7');
    world.creeps[wdUp.name] = wdUp;
    world.time++;
    ROLES.upgrader.run(wdUp);
    assert(headingTo(wdUp, wdLink) && wdUp.store[C.RESOURCE_ENERGY] === 0, '复现：空手升级者朝 24 格外的 ctrl link 走（走不动）');
    let wdTicks = 1;
    const wdDeleteMark = wheelMovementState.deletedRooms.length;
    while (wdTicks <= wdCfg.stuckRepathTicks) { wdUp.actions.length = 0; wdUp.moveCalls.length = 0; world.time++; wdTicks++; ROLES.upgrader.run(wdUp); }
    assert(wdMem.upgraderStuck && wdMem.upgraderStuck.action === 'repath' && wdMem.upgraderStuck.repath === 1 && wdMem.upgraderStuck.name === 'wd.up',
        '原地不动 ' + wdCfg.stuckRepathTicks + ' tick：先重算路径一次（遥测 ' + JSON.stringify(wdMem.upgraderStuck) + '）');
    const wdDeleted = wheelMovementState.deletedRooms.slice(wdDeleteMark);
    assert(wdDeleted.some((e) => e.kind === 'creep' && e.creepName === 'wd.up') && wdMem.upgraderStuck.reset === 1,
        '重算只重置这只升级者自己的路径（resetCreepPath，遥测 reset ' + wdMem.upgraderStuck.reset + '）');
    assert(!wdDeleted.some((e) => e.kind !== 'creep'), '不再 invalidateRoom：全房缓存路径/costMatrix 不动（得 ' + JSON.stringify(wdDeleted) + '）');
    assert(!utils.isRetiring(wdUp.memory), '重算阶段还不退役');
    while (wdTicks <= wdCfg.stuckRetireTicks) { wdUp.actions.length = 0; wdUp.moveCalls.length = 0; world.time++; wdTicks++; ROLES.upgrader.run(wdUp); }
    assert((wdMem.upgraderStuck || {}).repath === 1, '重算只做一次');
    assert(wdUp.memory.stuckRetiring && utils.isRetiring(wdUp.memory) && (wdMem.upgraderStuck || {}).action === 'retire' && wdMem.upgraderStuck.retire === 1,
        '原地不动 ' + wdCfg.stuckRetireTicks + ' tick：退役，编制计数排除它（遥测 ' + JSON.stringify(wdMem.upgraderStuck) + '）');
    assert(wdUp.actions.includes('recycled') && wdSpawn.actions.some((a) => a.action === 'recycleCreep' && a.target === 'wd.up'),
        '贴着 spawn：当场回收（动作 ' + wdUp.actions.join(',') + '）');
    wd._sources.forEach((src, i) => { world.creeps['wdh' + i] = makeCreep(wd, 'wdh' + i, utils.makeBody('staticHarvester', 5600), { home: 'W33S7', role: 'harvester', sourceIdx: i, sourceId: src.id, staticMiner: true }); });
    world.creeps['wd.hauler'] = makeCreep(wd, 'wd.hauler', utils.makeBody('hauler', 1300), { home: 'W33S7', role: 'hauler' });
    world.time++;
    spawnMgr.run(wd);
    assert(wdMem.demand.planned.upgrader === 0 && wdMem.demand.targets.upgrader >= 1, '退役中的卡死升级者不计入编制（planned ' + JSON.stringify(wdMem.demand.planned) + '）');
    const wdHasNew = () => Object.values(world.creeps).some((c) => c.memory && c.memory.role === 'upgrader' && c.name !== 'wd.up');
    for (let i = 0; i < 5 && !wdHasNew(); i++) { world.time++; wd.energyAvailable = 5600; spawnMgr.run(wd); }
    assert(wdHasNew(), '卡死的升级者退役后孵出替补升级者');

    const okUp = makeCreep(wd, 'wd.ok', utils.makeBody('upgrader', 2300, { maxWork: 20 }), { home: 'W33S7', role: 'upgrader' });
    okUp.pos = new RoomPosition(wdLink.pos.x - 1, wdLink.pos.y, 'W33S7');
    world.creeps[okUp.name] = okUp;
    const walker = makeCreep(wd, 'wd.walk', utils.makeBody('upgrader', 2300, { maxWork: 20 }), { home: 'W33S7', role: 'upgrader' });
    walker.pos = new RoomPosition(10, 30, 'W33S7');
    world.creeps[walker.name] = walker;
    for (let i = 0; i < wdCfg.stuckRetireTicks + 5; i++) {
        world.time++;
        okUp.store[C.RESOURCE_ENERGY] = 0;
        walker.pos = new RoomPosition(10 + (i % 2), 30, 'W33S7');
        ROLES.upgrader.run(okUp);
        ROLES.upgrader.run(walker);
    }
    assert(!okUp.memory.stuckRetiring && !okUp.memory.upStuck, '控制器 3 格内不动的升级者不算卡死');
    assert(!walker.memory.stuckRetiring, '一直在移动的升级者不算卡死');
    const tired = makeCreep(wd, 'wd.tired', utils.makeBody('upgrader', 5600, { maxWork: 47 }), { home: 'W33S7', role: 'upgrader' });
    tired.pos = new RoomPosition(12, 32, 'W33S7');
    tired.fatigue = 40;
    world.creeps[tired.name] = tired;
    for (let i = 0; i < wdCfg.stuckRetireTicks + 5; i++) { world.time++; ROLES.upgrader.run(tired); }
    assert(!tired.memory.stuckRetiring && !tired.memory.upStuck, '有疲劳（在走、只是慢）不计时');

    for (const name of ['wd.ok', 'wd.walk', 'wd.tired']) delete world.creeps[name];
    delete wdMem.upgraderStuck;
    let wdDowngradeAt = world.time + 20000;
    Object.defineProperty(wd.controller, 'ticksToDowngrade', { get: () => wdDowngradeAt - world.time, set: () => {}, configurable: true });
    let wdSeq = 0;
    const stuckOne = () => {
        const up = makeCreep(wd, 'wd.bo' + (++wdSeq), [].concat(Array(12).fill('work'), Array(6).fill('carry'), ['move']), { home: 'W33S7', role: 'upgrader' });
        up.pos = new RoomPosition(23, 20, 'W33S7');
        world.creeps[up.name] = up;
        for (let i = 0; i <= wdCfg.stuckRetireTicks + 1 && !up.memory.stuckRetiring; i++) { up.actions.length = 0; up.moveCalls.length = 0; world.time++; ROLES.upgrader.run(up); }
        delete world.creeps[up.name];
        return up;
    };
    const boAfter = wdCfg.stuckBackoffAfter;
    assert(boAfter >= 2 && wdCfg.stuckBackoffTicks >= wdCfg.stuckRetireTicks, '退避参数：至少连续 2 次、退避长于一次卡死判定');
    for (let k = 1; k < boAfter; k++) {
        const up = stuckOne();
        assert(up.memory.stuckRetiring && wdMem.upgraderStuck.streak === k && !(wdMem.upgraderStuck.backoffUntil > world.time),
            '第 ' + k + ' 次退役：只计数、不退避（遥测 ' + JSON.stringify(wdMem.upgraderStuck) + '）');
    }
    const boLast = stuckOne();
    assert(boLast.memory.stuckRetiring && wdMem.upgraderStuck.streak === boAfter && wdMem.upgraderStuck.backoffs === 1 &&
        wdMem.upgraderStuck.backoffUntil === world.time + wdCfg.stuckBackoffTicks,
        '连续 ' + boAfter + ' 次退役控制器零进度：进入退避 ' + wdCfg.stuckBackoffTicks + ' tick（遥测 ' + JSON.stringify(wdMem.upgraderStuck) + '）');
    const boRetiresBefore = wdMem.upgraderStuck.retire;
    const boHeld = stuckOne();
    assert(!boHeld.memory.stuckRetiring && !utils.isRetiring(boHeld.memory) && wdMem.upgraderStuck.held === 1 && wdMem.upgraderStuck.retire === boRetiresBefore,
        '退避期间卡住的升级者不退役（留着、编制不出替补），记 held（遥测 ' + JSON.stringify(wdMem.upgraderStuck) + '）');
    world.time = wdMem.upgraderStuck.backoffUntil;
    world.creeps[boHeld.name] = boHeld;
    boHeld.actions.length = 0;
    ROLES.upgrader.run(boHeld);
    delete world.creeps[boHeld.name];
    assert(boHeld.memory.stuckRetiring && wdMem.upgraderStuck.backoffs === 2 && wdMem.upgraderStuck.backoffUntil === world.time + wdCfg.stuckBackoffTicks,
        '退避到期后卡着的那只立刻退役，仍零进度就再退避（遥测 ' + JSON.stringify(wdMem.upgraderStuck) + '）');
    world.time += wdCfg.stuckBackoffTicks + 1;
    wd.controller.progress = (Number(wd.controller.progress) || 0) + 500;
    const boProgress = stuckOne();
    assert(boProgress.memory.stuckRetiring && wdMem.upgraderStuck.streak === 1 && wdMem.upgraderStuck.backoffs === 2,
        '两次退役之间控制器有进度：计数从 1 重新开始（遥测 ' + JSON.stringify(wdMem.upgraderStuck) + '）');
    stuckOne();
    const boMark = wdMem.upgraderStuck.mark;
    assert(wdMem.upgraderStuck.streak === 2, '前提：没有进度时计数照常累加（得 ' + wdMem.upgraderStuck.streak + '）');
    wdDowngradeAt += 5000;
    stuckOne();
    assert(boMark && typeof boMark.d === 'number' && wdMem.upgraderStuck.streak === 1, '降级时间被推后（RCL8 的升级）也算进度（遥测 ' + JSON.stringify(wdMem.upgraderStuck) + '）');
}

console.log('== 升级者按可持续供给定身体与编制：不跟着瞬时限流在 W12 / W47 之间翻（线上 2026-10-08：限流一放开就孵 W47C2M1，21 只 731 WORK 养身体 51.5/tick，CP 被 ctrl link 20/tick 卡死）==');
{
    const sp = demoRoom(30500, 7);
    const spPlan = Memory.rooms.W33S7.plan;
    const spMem = Memory.rooms.W33S7;
    sp.energyCapacityAvailable = 5600;
    sp.energyAvailable = 5600;
    makeSpawn(sp, 23, 21);
    const spStorage = makeStructure(sp, C.STRUCTURE_STORAGE, 23, 24, { energy: 2500, capacity: 1000000 });
    makeStructure(sp, C.STRUCTURE_LINK, spPlan.links.ctrl.x, spPlan.links.ctrl.y, { energy: 796, capacity: 800 });
    makeStructure(sp, C.STRUCTURE_LINK, spPlan.links.src0.x, spPlan.links.src0.y, { energy: 500, capacity: 800 });
    makeStructure(sp, C.STRUCTURE_LINK, spPlan.links.src1.x, spPlan.links.src1.y, { energy: 500, capacity: 800 });
    world.time++;
    assert(utils.upgraderSupplyWork(sp, spMem) === 20, '可持续供给：2 源 20/tick、storage 在 lowExitAbove 以下 → 20 WORK（得 ' + utils.upgraderSupplyWork(sp, spMem) + '）');
    spMem.state = Object.assign(spMem.state || {}, { builderBacklog: 0 });
    world.time += require('../src/config').upgrading.competeHoldTicks + 1;
    const spFree = spawnMgr.upgraderBody(sp, spMem, 5600);
    assert(utils.upgraderWorkCap(sp, spMem) === Infinity && workParts(spFree) === 20 && utils.bodyCost(spFree) <= 2350,
        '限流放开时身体仍按供给 W20（≤ 2350，富余预算按模板补 CARRY），不是 W47C2M1=4850（得 W' + workParts(spFree) + ' 成本 ' + utils.bodyCost(spFree) + '）');
    assert(spMem.upgradeSupply.sizeCap && spMem.upgradeSupply.sizeCap.cap === 20 && spMem.upgradeSupply.sizeCap.would === 47,
        '遥测 sizeCap：容量能出 W47、被供给封顶到 W20（得 ' + JSON.stringify(spMem.upgradeSupply.sizeCap) + '）');
    spMem.state.builderBacklog = 5;
    world.time++;
    const spHeld = spawnMgr.upgraderBody(sp, spMem, 5600);
    assert(utils.upgraderWorkCap(sp, spMem) === 12 && workParts(spHeld) === 20, '限流 W12 时身体仍是 W20：两种状态同一个身体，不再换代来回翻（得 W' + workParts(spHeld) + '）');
    spStorage.store[C.RESOURCE_ENERGY] = 40000;
    world.time++;
    assert(utils.upgraderSupplyWork(sp, spMem) === 40 && workParts(spawnMgr.upgraderBody(sp, spMem, 5600)) === 40, 'storage 4 万：供给 40 WORK → W40（得 ' + utils.upgraderSupplyWork(sp, spMem) + '）');
    spStorage.store[C.RESOURCE_ENERGY] = 200000;
    world.time++;
    assert(workParts(spawnMgr.upgraderBody(sp, spMem, 5600)) === 47, 'storage 20 万：富房照旧满身体 W47');
    sp.controller.level = 8;
    assert(utils.upgraderSupplyWork(sp, spMem) === 15, 'RCL8 封 15（引擎上限）');
    sp.controller.level = 7;
    spStorage.store[C.RESOURCE_ENERGY] = 2500;
    world.time++;
    spMem.state.builderBacklog = 0;
    spMem.upgradeSupply = Object.assign(spMem.upgradeSupply, { ema: 1, extra: 1, at: -1, changedAt: -1, competeAt: null });
    world.time++;
    const spTarget = spawnMgr.upgraderTarget(sp, spMem);
    assert(utils.upgraderWorkCap(sp, spMem) === Infinity && spTarget === 1 && spMem.upgradeSupply.capCount === 1,
        '限流放开、link 满着：升级者目标按供给封顶为 1，不按 extra 加到 maxUpgraders（得 ' + spTarget + ' capCount ' + spMem.upgradeSupply.capCount + '）');
    const spW12 = makeCreep(sp, 'sp.w12', utils.makeBody('upgrader', 1350, { maxWork: 12 }), { home: 'W33S7', role: 'upgrader' }, { ticksToLive: 300 });
    const spW4 = makeCreep(sp, 'sp.w4', utils.makeBody('upgrader', 550, { maxWork: 4 }), { home: 'W33S7', role: 'upgrader' }, { ticksToLive: 300 });
    assert(workParts(spW12.body) === 12 && !spawnMgr.bodyImproves(spW12, spFree, 'upgrader'), '在岗 W12、方案 W20：不提前换代');
    assert(workParts(spW4.body) === 4 && spawnMgr.bodyImproves(spW4, spFree, 'upgrader'), '在岗 W4、方案 W20：换代');
}

console.log('== 升级者在编 WORK 闸：在编 WORK 已够可持续供给就不再按人头补（线上 W38S7：4 只 W47 = 188 WORK 对 20/tick 的供给）==');
{
    const gt = demoRoom(30700, 4);
    const gtMem = Memory.rooms.W33S7;
    gt.energyCapacityAvailable = 1300;
    gt.energyAvailable = 1300;
    makeSpawn(gt, 23, 21);
    makeStructure(gt, C.STRUCTURE_STORAGE, 23, 24, { energy: 2500, capacity: 1000000 });
    gt._sources.forEach((src, i) => { world.creeps['gth' + i] = makeCreep(gt, 'gth' + i, utils.makeBody('staticHarvester', 1300), { home: 'W33S7', role: 'harvester', sourceIdx: i, sourceId: src.id, staticMiner: true }); });
    for (let i = 0; i < 4; i++) world.creeps['gtha' + i] = makeCreep(gt, 'gtha' + i, utils.makeBody('hauler', 1300), { home: 'W33S7', role: 'hauler' });
    world.creeps.gtb = makeCreep(gt, 'gtb', utils.makeBody('builder', 1300), { home: 'W33S7', role: 'builder' });
    world.creeps.gtUp = makeCreep(gt, 'gtUp', [].concat(Array(25).fill('work'), ['carry', 'carry', 'move']), { home: 'W33S7', role: 'upgrader' });
    world.time++;
    spawnMgr.run(gt);
    const gtNew = Object.values(world.creeps).filter((c) => c.memory.role === 'upgrader' && c.name !== 'gtUp');
    assert(gtMem.demand.targets.upgrader === 2 && gtNew.length === 0 && gtMem.upgradeSupply.workGate && gtMem.upgradeSupply.workGate.planned === 25 && gtMem.upgradeSupply.workGate.cap === 20,
        '人头 1 < 目标 2，但在编 25 WORK ≥ 供给 20：不再出升级者请求（新孵 ' + gtNew.length + '，闸 ' + JSON.stringify(gtMem.upgradeSupply.workGate) + '）');
    world.creeps.gtUp.ticksToLive = 20;
    for (let i = 0; i < 4 && !Object.values(world.creeps).some((c) => c.memory.role === 'upgrader' && c.name !== 'gtUp'); i++) { world.time++; gt.energyAvailable = 1300; spawnMgr.run(gt); }
    assert(Object.values(world.creeps).some((c) => c.memory.role === 'upgrader' && c.name !== 'gtUp'), '在编大身体进了替补提前量：替补照常孵');
}

function nonEnergyTotal(store) {
    return Object.keys(store).reduce((sum, key) =>
        (key !== C.RESOURCE_ENERGY && typeof store[key] === 'number' ? sum + store[key] : sum), 0);
}
function pickTypes(store) {
    const out = {};
    for (const key of Object.keys(store)) if (typeof store[key] === 'number' && store[key] > 0) out[key] = store[key];
    return out;
}

console.log('== CPU：orderCreeps 只给能接任务的角色竞价，顺序与分数不变 ==');
{
    resetWorld(60001);
    const ocRoom = makeRoom('W33S7', { rcl: 4, energy: 300, cap: 800, ctrl: { x: 34, y: 24 } });
    ocRoom._sources = [makeSource(ocRoom, 14, 6, 'ocS0'), makeSource(ocRoom, 31, 12, 'ocS1')];
    const ocSpawn = makeSpawn(ocRoom, 23, 21);
    ocSpawn.store[C.RESOURCE_ENERGY] = 100;
    makeStructure(ocRoom, C.STRUCTURE_EXTENSION, 25, 22, { capacity: 50, energy: 0 });
    makeStructure(ocRoom, C.STRUCTURE_CONTAINER, 15, 7, { capacity: 2000, energy: 900 });
    ocRoom.createConstructionSite(27, 27, C.STRUCTURE_ROAD);
    Memory.rooms.W33S7 = {};
    const ocSpecs = [
        ['oc.hauler', 'hauler', ['carry', 'carry', 'move'], 100],
        ['oc.hauler2', 'hauler', ['carry', 'carry', 'move'], 0],
        ['oc.harvester', 'harvester', ['work', 'work', 'carry', 'move'], 0],
        ['oc.upgrader', 'upgrader', ['work', 'carry', 'move'], 50],
        ['oc.builder', 'builder', ['work', 'carry', 'move'], 50],
        ['oc.rhauler', 'remoteHauler', ['work', 'carry', 'carry', 'move', 'move'], 100],
        ['oc.rminer', 'remoteMiner', ['work', 'work', 'carry', 'move'], 0],
        ['oc.reserver', 'reserver', ['claim', 'move'], 0],
        ['oc.operator', 'operator', ['carry', 'carry', 'move'], 0],
        ['oc.scout', 'scout', ['move'], 0],
        ['oc.defender', 'defender', ['attack', 'move'], 0],
    ];
    const scans = {};
    const ocCreeps = ocSpecs.map(([name, role, body, energy], index) => {
        const creep = makeCreep(ocRoom, name, body, { home: 'W33S7', role }, { ticksToLive: 200 + index * 97 });
        creep.store[C.RESOURCE_ENERGY] = energy;
        creep.pos = new RoomPosition(10 + index * 3, 20 + (index % 4) * 4, 'W33S7');
        const scan = creep.getActiveBodyparts.bind(creep);
        creep.getActiveBodyparts = (type) => { scans[name] = (scans[name] || 0) + 1; return scan(type); };
        world.creeps[name] = creep;
        return creep;
    });
    const order = taskBroker.orderCreeps(ocCreeps.slice()).map((c) => c.name);
    const scores = global.__taskBrokerRuntime.scores;
    const pool = taskBroker.pooledTasks(ocRoom);
    assert(pool.length >= 4 && ['deliver', 'collect', 'harvest', 'upgrade', 'build'].every((kind) => pool.some((t) => t.kind === kind)),
        '前提：任务池里投递/取货/采集/升级/建造都有（得 ' + pool.map((t) => t.kind).join(',') + '）');
    const amount = { deliver: true, collect: true };
    let sameScores = true;
    const detail = [];
    for (const creep of ocCreeps) {
        let ref = -Infinity;
        for (const task of pool) {
            if (amount[task.kind] && !(taskBroker.availableFor(task, creep) > 0)) continue;
            ref = Math.max(ref, taskBroker.scoreTask(creep, task));
        }
        if (Number.isFinite(ref) && scores[creep.name] !== Math.round(ref * 100) / 100) {
            sameScores = false;
            detail.push(creep.name + ':' + scores[creep.name] + '≠' + ref);
        }
    }
    assert(['oc.hauler', 'oc.upgrader', 'oc.builder', 'oc.rhauler'].every((name) => scores[name] > 100),
        '前提：搬运/升级/建造/外矿运输工都竞到了任务（分数 ' + JSON.stringify(scores) + '）');
    assert(sameScores, '能接任务的 creep 分数 = 旧语义下最优任务的分数（' + detail.join(' ') + '）');
    const incompatible = ocCreeps.filter((c) => ['remoteMiner', 'reserver', 'operator', 'scout', 'defender'].includes(c.memory.role));
    assert(incompatible.every((c) => pool.every((task) => taskBroker.scoreTask(c, task) === -Infinity)),
        '不能接任务的角色对池里每个任务打分都是 -Infinity（旧代码也只会落到角色权重 × 寿命紧迫度）');
    const sorted = ocCreeps.map((c, index) => ({ name: c.name, score: scores[c.name], index }))
        .sort((a, b) => b.score - a.score || a.index - b.index).map((e) => e.name);
    assert(order.join(',') === sorted.join(','), '执行顺序 = 按分数降序、同分保持原序（得 ' + order.join(',') + '）');
    for (const name of Object.keys(scans)) scans[name] = 0;
    world.time++;
    taskBroker.orderCreeps(ocCreeps.slice());
    assert(['oc.rminer', 'oc.reserver', 'oc.operator', 'oc.scout', 'oc.defender'].every((name) => !scans[name]),
        'remoteMiner/reserver/operator/scout/defender 排序时一次身体都不扫（得 ' + JSON.stringify(scans) + '）');
    const compatibleTasks = taskBroker.pooledTasks(ocRoom).filter((t) => taskBroker.scoreTask(ocCreeps[0], t) > -Infinity).length;
    for (const name of Object.keys(scans)) scans[name] = 0;
    world.time++;
    taskBroker.orderCreeps(ocCreeps.slice());
    assert(scans['oc.hauler'] <= 2 + 2 * compatibleTasks && scans['oc.hauler'] < 2 * taskBroker.pooledTasks(ocRoom).length,
        'hauler 排序扫身体次数 ≤ 2 + 2×兼容任务数，少于旧写法的 2×全部任务数（得 ' + scans['oc.hauler'] + '，池 ' +
        taskBroker.pooledTasks(ocRoom).length + '，兼容 ' + compatibleTasks + '）');
}

console.log('== CPU：bucket 吃紧时按价值降载（cpu_shed）==');
{
    const cpuShed = require('../src/cpu_shed');
    const shedCfg = config.cpuShed;
    const cpuOf = (bucket) => ({ limit: 150, bucket });
    assert(cpuShed.modeFor(cpuOf(10000), null, 1) === 'normal' && cpuShed.modeFor(cpuOf(shedCfg.lowBucket), null, 1) === 'normal' &&
        cpuShed.modeFor(cpuOf(shedCfg.lowBucket - 1), null, 1) === 'low' && cpuShed.modeFor(cpuOf(shedCfg.criticalBucket - 1), null, 1) === 'critical',
        'bucket ≥ lowBucket 正常、< lowBucket 降载、< criticalBucket 紧急');
    assert(cpuShed.modeFor(cpuOf(10000), { mode: 'critical', until: 5 }, 4) === 'critical' && cpuShed.modeFor(cpuOf(10000), { mode: 'critical', until: 5 }, 5) === 'normal',
        'Memory.cpuShedForce 在 until 之前强制模式，到期即失效');
    assert(cpuShed.creepCap(cpuOf(10000), 'normal', null, 1) === 150 - config.cpuReserve &&
        cpuShed.creepCap(cpuOf(1000), 'low', null, 1) === 150 - shedCfg.lowReserve &&
        cpuShed.creepCap(cpuOf(100), 'critical', null, 1) === 150 - shedCfg.criticalReserve &&
        cpuShed.creepCap(cpuOf(10000), 'critical', { mode: 'critical', cap: 0, until: 9 }, 1) === 0,
        'creep 循环上限：正常 limit − cpuReserve（旧值）、降载 limit − lowReserve、紧急 limit − criticalReserve、强制可给 cap');
    assert(shedCfg.lowReserve > config.cpuReserve && shedCfg.criticalReserve > shedCfg.lowReserve, '降载越紧上限越低');

    resetWorld(50001);
    const shRoom = makeRoom('W33S7', { rcl: 7, energy: 5000, cap: 5600, ctrl: { x: 34, y: 24 } });
    shRoom._sources = [makeSource(shRoom, 14, 6, 'shS0'), makeSource(shRoom, 31, 12, 'shS1')];
    const shRemote = makeRoom('W33S6', { my: false, rcl: 0, ctrl: { x: 25, y: 25 }, reservation: { username: 'me', ticksToEnd: shedCfg.reserverComfort + 500 }, exits: { '5': 'W33S7' } });
    const shRemoteLow = makeRoom('W32S7', { my: false, rcl: 0, ctrl: { x: 25, y: 25 }, reservation: { username: 'me', ticksToEnd: shedCfg.reserverComfort - 500 }, exits: { '3': 'W33S7' } });
    Memory.rooms.W33S7 = {};
    const mk = (name, role, body, opts = {}) => {
        const creep = makeCreep(opts.room || shRoom, name, body, Object.assign({ home: 'W33S7', role }, opts.memory || {}));
        creep.owner = { username: 'me' };
        creep.pos = new RoomPosition(opts.x || (5 + Object.keys(world.creeps).length * 2), opts.y || 40, (opts.room || shRoom).name);
        if (opts.energy) creep.store[C.RESOURCE_ENERGY] = opts.energy;
        world.creeps[name] = creep;
        Memory.creeps[name] = creep.memory;
        return creep;
    };
    mk('sh.harv0', 'harvester', ['work', 'work', 'carry', 'move'], { memory: { sourceId: 'shS0', sourceIdx: 0 } });
    mk('sh.harv1', 'harvester', ['work', 'work', 'carry', 'move'], { memory: { sourceId: 'shS1', sourceIdx: 1 } });
    mk('sh.hauler0', 'hauler', ['carry', 'carry', 'move']);
    mk('sh.hauler1', 'hauler', ['carry', 'carry', 'move']);
    mk('sh.upgrader', 'upgrader', ['work', 'carry', 'move'], { energy: 50 });
    mk('sh.defender', 'defender', ['attack', 'move']);
    mk('sh.rminer', 'remoteMiner', ['work', 'work', 'carry', 'move'], { room: shRemote, memory: { remoteRoom: 'W33S6' } });
    mk('sh.scout', 'scout', ['move']);
    mk('sh.reserver', 'reserver', ['claim', 'move'], { room: shRemote, memory: { remoteRoom: 'W33S6' } });
    mk('sh.reserverLow', 'reserver', ['claim', 'move'], { room: shRemoteLow, memory: { remoteRoom: 'W32S7' } });
    mk('sh.operator', 'operator', ['carry', 'carry', 'move']);
    mk('sh.rhEmpty', 'remoteHauler', ['carry', 'carry', 'move'], { memory: { remoteRoom: 'W33S6' } });
    mk('sh.rhLoaded', 'remoteHauler', ['carry', 'carry', 'move'], { energy: 100, memory: { remoteRoom: 'W33S6' } });
    const roleNames = ['harvester', 'hauler', 'upgrader', 'defender', 'remoteMiner', 'scout', 'reserver', 'operator', 'remoteHauler'];
    const savedRuns = {};
    for (const r of roleNames) { savedRuns[r] = ROLES[r].run; ROLES[r].run = () => {}; }
    const savedStart = taskBroker.startCreep;
    let ran = [];
    taskBroker.startCreep = (creep) => { ran.push(creep.name); return savedStart(creep); };
    const savedCpu = Game.cpu;
    const tick = (bucket, used) => {
        world.time++;
        ran = [];
        Game.cpu = Object.assign({}, savedCpu, { limit: 150, bucket, getUsed: () => used });
        main.loop();
        return ran.slice();
    };
    try {
        tick(10000, 5);
        cpuShed.digest();
        const healthy = tick(10000, 1000);
        const healthyShed = cpuShed.digest();
        assert(healthy.includes('sh.scout') && healthy.includes('sh.operator') && healthy.includes('sh.reserver') && healthy.includes('sh.rhEmpty'),
            'bucket 健康时行为不变：scout/operator/reserver/空车外矿运输工照跑（得 ' + healthy.join(',') + '）');
        assert(healthyShed.skip === 0 && healthyShed.low === 0 && healthyShed.crit === 0, 'bucket 健康时不进降载、不记降载跳过（得 ' + JSON.stringify(healthyShed) + '）');

        const cheap = tick(300, 5);
        assert(cheap.length === Object.keys(world.creeps).length, '紧急模式下 CPU 没超上限时一只都不跳（得 ' + cheap.length + '/' + Object.keys(world.creeps).length + '）');

        const crit1 = tick(300, 1000);
        const mustRun = ['sh.harv0', 'sh.harv1', 'sh.upgrader', 'sh.defender', 'sh.rminer', 'sh.rhLoaded', 'sh.reserverLow'];
        assert(mustRun.every((name) => crit1.includes(name)),
            '紧急 + 超上限：本房矿工/upgrader/defender/remoteMiner/载货外矿运输工/预定不足的 reserver 照跑（得 ' + crit1.join(',') + '）');
        const shedNames = ['sh.scout', 'sh.reserver', 'sh.operator', 'sh.rhEmpty'];
        assert(shedNames.every((name) => !crit1.includes(name)),
            '紧急 + 超上限：scout、预定富余的 reserver、operator、空闲空车外矿运输工被跳（得 ' + crit1.join(',') + '）');
        const haulersRan = ['sh.hauler0', 'sh.hauler1'].filter((name) => crit1.includes(name));
        assert(haulersRan.length === 1, '两只空闲 hauler 只跳一只：房里最后一只能跑的 hauler 永远执行（执行了 ' + haulersRan.join(',') + '）');
        const crit2 = tick(300, 1000);
        assert(shedNames.every((name) => !crit2.includes(name)), '连续第 2 tick 仍可跳（maxConsecutive=' + shedCfg.maxConsecutive + '）');
        const crit3 = tick(300, 1000);
        assert(shedNames.every((name) => crit3.includes(name)) && crit3.includes(haulersRan[0] === 'sh.hauler0' ? 'sh.hauler1' : 'sh.hauler0'),
            '连跳 ' + shedCfg.maxConsecutive + ' tick 后第 3 tick 必跑，不会被饿死（得 ' + crit3.join(',') + '）');
        assert(['sh.hauler0', 'sh.hauler1'].filter((name) => crit3.includes(name)).length >= 1, '第 3 tick 至少一只 hauler 执行');

        while (world.time % 30 !== 0) world.time++;
        main.sampleStats();
        const stat = Memory.stats[Memory.stats.length - 1];
        const shed = stat && stat.shed;
        assert(shed && shed.crit >= 4 && shed.skip >= 10 && shed.roles.scout >= 2 && shed.roles.reserver >= 2,
            'Memory.stats 带降载遥测：紧急 tick 数、跳过次数、按角色分布（得 ' + JSON.stringify(shed) + '）');
        assert(shed && !shed.roles.harvester && !shed.roles.upgrader && !shed.roles.defender && !shed.roles.remoteMiner,
            '遥测里没有矿工/upgrader/defender/remoteMiner 被跳');
        const skippedCpu = global.__taskBrokerRuntime.metrics.W33S7 ? global.__taskBrokerRuntime.metrics.W33S7.skippedCpu : 0;
        assert(skippedCpu >= 1 || (Memory.taskBroker && Memory.taskBroker.rooms && Memory.taskBroker.rooms.W33S7 && Memory.taskBroker.rooms.W33S7.skippedCpu >= 1),
            'broker 遥测的 skippedCpu 也记下降载跳过');

        {
            let reads = 0;
            let counting = false;
            const savedOrder = taskBroker.orderCreeps;
            const savedFlushFn = taskBroker.flush;
            taskBroker.orderCreeps = function () { counting = true; return savedOrder.apply(this, arguments); };
            taskBroker.flush = function () { counting = false; return savedFlushFn.apply(this, arguments); };
            try {
                world.time++;
                while (world.time % 5 === 0 || world.time % 30 === 0) world.time++;
                ran = [];
                cpuShed.digest();
                Game.cpu = Object.assign({}, savedCpu, { limit: 150, bucket: 300, getUsed: () => { if (counting) reads++; return 1000; } });
                main.loop();
                const skipped = cpuShed.digest().skip;
                assert(skipped >= 4, '前提：这一 tick 跳了好几只（得 ' + skipped + '）');
                assert(reads <= 3 && reads < skipped, '越线之后不再逐只读 getUsed（跳了 ' + skipped + ' 只，分发循环里读了 ' + reads + ' 次）');
            } finally {
                taskBroker.orderCreeps = savedOrder;
                taskBroker.flush = savedFlushFn;
            }
        }
        {
            const dispEvery = require('../src/config').cpuProfile.dispatchEvery;
            assert(dispEvery === 30, 'cpuProfile.dispatchEvery 默认 30（每条 stats 一个阶段样本）');
            let reads = 0;
            let counting = false;
            const savedOrder = taskBroker.orderCreeps;
            const savedFlushFn = taskBroker.flush;
            taskBroker.orderCreeps = function () { counting = true; return savedOrder.apply(this, arguments); };
            taskBroker.flush = function () { counting = false; return savedFlushFn.apply(this, arguments); };
            const sampleTick = (want, bucket) => {
                while (world.time % 30 !== 0) world.time++;
                main.sampleStats();
                let clock = 0;
                world.time++;
                while (world.time % 30 !== want) world.time++;
                ran = [];
                reads = 0;
                cpuShed.digest();
                Game.cpu = Object.assign({}, savedCpu, { limit: 150, bucket, getUsed: () => { if (counting) reads++; return (clock += 0.1); } });
                main.loop();
                const ranCount = ran.length;
                const used = reads;
                while (world.time % 30 !== 0) world.time++;
                main.sampleStats();
                const entry = Memory.stats[Memory.stats.length - 1];
                return { disp: entry.cpuDispatch || {}, roles: entry.cpuRoles || {}, sampled: entry.cpuSampled, reads: used, ran: ranCount };
            };
            try {
                let got = sampleTick(15, 10000);
                assert(Array.isArray(got.sampled) && got.sampled[0] === 1 && got.sampled[1] === 1, 'stats 记窗口内抽样 tick 数 cpuSampled [角色, 阶段]（得 ' + JSON.stringify(got.sampled) + '）');
                const dispReads = got.reads;
                const dispRan = got.ran;
                assert(['order', 'retire', 'start', 'run', 'finish'].every((key) => got.disp[key] > 0),
                    'cpuDispatch 记下 order/retire/start/run/finish 五段（得 ' + JSON.stringify(got.disp) + '）');
                assert(Object.keys(got.roles).length > 0 && Object.values(got.roles).every((value) => value >= 0), 'cpuRoles 照常（得 ' + JSON.stringify(got.roles) + '）');
                got = sampleTick(10, 10000);
                assert(Object.keys(got.disp).length === 0, '非阶段抽样 tick 不记 cpuDispatch（得 ' + JSON.stringify(got.disp) + '）');
                assert(Array.isArray(got.sampled) && got.sampled[0] === 1 && got.sampled[1] === 0, '非阶段抽样 tick：cpuSampled [1, 0]（得 ' + JSON.stringify(got.sampled) + '）');
                assert(Object.keys(got.roles).length > 0, '角色计时照量（得 ' + JSON.stringify(got.roles) + '）');
                assert(got.ran > 0 && got.ran === dispRan && dispReads - got.reads >= 2 * got.ran,
                    '角色抽样 tick 每只省下 2 次读数（跑了 ' + got.ran + ' 只，阶段 tick 读 ' + dispReads + ' 次、角色 tick 读 ' + got.reads + ' 次）');
                got = sampleTick(15, 300);
                assert(Object.keys(got.disp).length === 0, '降载中不量分发阶段（得 ' + JSON.stringify(got.disp) + '）');
            } finally {
                taskBroker.orderCreeps = savedOrder;
                taskBroker.flush = savedFlushFn;
            }
        }
        Memory.cpuShedForce = { mode: 'critical', cap: 0, until: world.time + 2 };
        const forced = tick(10000, 5);
        assert(!forced.includes('sh.scout') && forced.includes('sh.harv0'), 'Memory.cpuShedForce 强制紧急 + cap 0：CPU 再低也跳可跳单位、矿工照跑（得 ' + forced.join(',') + '）');
        world.time += 5;
        tick(10000, 5);
        assert(Memory.cpuShedForce === undefined, '强制到期后自动删除');

        const endReserve = shedCfg.endReserve;
        assert(endReserve >= 22 && shedCfg.hardStopArm > 0, 'endReserve 至少盖住 move.end ~15 + 序列化 ~7（得 ' + endReserve + '）');
        let endTicks = 0;
        let flushes = 0;
        const savedEndTick = movement.endTick;
        const savedFlush = taskBroker.flush;
        movement.endTick = function () { endTicks++; return savedEndTick.apply(this, arguments); };
        taskBroker.flush = function () { flushes++; return savedFlush.apply(this, arguments); };
        const stepTick = (bucket, tickLimit, base, per) => {
            world.time++;
            ran = [];
            Game.cpu = Object.assign({}, savedCpu, { limit: 150, bucket, tickLimit, getUsed: () => base + ran.length * per });
            main.loop();
            return ran.slice();
        };
        try {
            cpuShed.digest();
            const hardBefore = (Memory.cpuHardStop && Memory.cpuHardStop.n) || 0;
            const total = Object.keys(world.creeps).length;
            endTicks = 0; flushes = 0;
            const hard = stepTick(0, 150, 100, 5);
            const line = 150 - endReserve;
            const expectRan = Math.floor((line - 100) / 5) + 1;
            assert(hard.length === expectRan, 'bucket 0、tickLimit 150：越过 tickLimit − endReserve 后一只都不再跑（跑了 ' + hard.length + '，应 ' + expectRan + '）');
            assert(['sh.harv0', 'sh.harv1'].every((name) => hard.includes(name)) && !hard.includes('sh.scout'), '硬停只砍尾巴：排在前面的矿工跑了、排在最后的 scout 没跑（得 ' + hard.join(',') + '）');
            assert(endTicks === 1 && flushes === 1, '硬停的 tick 照常跑 movement.endTick 与 broker flush（endTick ' + endTicks + '、flush ' + flushes + '）');
            assert(Memory.cpuHardStop && Memory.cpuHardStop.n === hardBefore + 1 && Memory.cpuHardStop.at === world.time && Memory.cpuHardStop.cut === total - expectRan,
                'Memory.cpuHardStop 记下次数/tick/没跑的数量（得 ' + JSON.stringify(Memory.cpuHardStop) + '）');
            const none = stepTick(0, 150, 200, 0);
            assert(none.length === 0, '开跑前就过线：永不跳的矿工/defender 也不跑（得 ' + none.join(',') + '）');
            const hardStat = cpuShed.digest();
            assert(hardStat.hard === 2 && hardStat.cut === (total - expectRan) + total && hardStat.hardEnd === 2,
                'stats.shed 带硬停遥测：硬停 tick 数、没跑的 creep 数、收尾跑完的次数（得 ' + JSON.stringify(hardStat) + '）');
            const relaxed = stepTick(10000, 500, 60, 1);
            assert(relaxed.length === total, 'tickLimit 500 时一只都不少（得 ' + relaxed.length + '/' + total + '）');
            Game.cpu = Object.assign({}, savedCpu, { limit: 150, bucket: 10000, tickLimit: 500, getUsed: () => 60 });
            assert(cpuShed.begin().armed === false, 'tickLimit 500、用量 60：不 armed（循环里不逐只读 getUsed）');
            Game.cpu = Object.assign({}, savedCpu, { limit: 150, bucket: 0, tickLimit: 150, getUsed: () => 60 });
            assert(cpuShed.begin().armed === true, 'tickLimit 150：armed');
            Game.cpu = Object.assign({}, savedCpu, { limit: 150, bucket: 10000, getUsed: () => 60 });
            assert(cpuShed.begin().hardStop === null, '没有 tickLimit（模拟器/单测）不硬停');
            assert(cpuShed.hardStopLine({ tickLimit: 9000 }, { stop: 0, stopUntil: 10 }, 9) === 0 && cpuShed.hardStopLine({ tickLimit: 9000 }, { stop: 0, stopUntil: 10 }, 10) === 9000 - endReserve,
                'Memory.cpuShedForce.stop 在 stopUntil 之前覆盖硬停线');
            cpuShed.digest();
        } finally {
            movement.endTick = savedEndTick;
            taskBroker.flush = savedFlush;
        }
    } finally {
        Game.cpu = savedCpu;
        taskBroker.startCreep = savedStart;
        for (const r of roleNames) ROLES[r].run = savedRuns[r];
    }
}

