    Memory.errors = [];
    delete Memory.brainRetiredAlert;
    brainMod.retiredGuard();
    brainMod.retiredGuard();
    assert(notes.length === 1 && Memory.errors.filter((e) => /brain\.retiredGuard/.test(JSON.stringify(e))).length === 1, 'retired 为 false：Game.notify + Memory.errors 各一次，不重复');
    config.brain = {};
