    const ownCfg = Object.assign({}, cfg, { ownOrders: Object.assign({}, cfg.ownOrders, { buyMinerals: false, sell: [], energy: Object.assign({}, e, { rooms: ['W33S7'], preferSenders: [], budget: Object.assign({}, e.budget, { from: '2000-01-01' }) }) }) });
